/* Petit message discret en bas de l'écran (confirmation d'une action : "Texte copié",
   "Amen.", etc.). Appelé partout dans l'app — jusqu'ici jamais défini, ce qui faisait
   planter silencieusement (ReferenceError) toute action qui s'en servait. */
let TOAST_HIDE_TIMER = null;
function showToast(message){
  const host = document.getElementById('app') || document.body;
  let el = document.getElementById('lumen-toast');
  if(!el){
    el = document.createElement('div');
    el.id = 'lumen-toast';
    el.className = 'toast';
    host.appendChild(el);
  }
  el.textContent = message;
  el.classList.add('show');
  clearTimeout(TOAST_HIDE_TIMER);
  TOAST_HIDE_TIMER = setTimeout(()=> el.classList.remove('show'), 2200);
}

/* window.storage only exists inside Claude.ai artifacts. Once deployed standalone
   (e.g. GitHub Pages), it's undefined — this polyfill makes "guest mode" (sans compte)
   actually work by using the browser's own localStorage instead. */
function makeLocalStoragePolyfill(){
  const prefix = 'lumen:';
  return {
    async get(key, shared){
      try{
        const raw = localStorage.getItem(prefix+key);
        if(raw === null) return null;
        return { key, value: raw, shared: !!shared };
      }catch(e){ return null; }
    },
    async set(key, value, shared){
      try{ localStorage.setItem(prefix+key, value); return { key, value, shared: !!shared }; }
      catch(e){ return null; }
    },
    async delete(key, shared){
      try{ localStorage.removeItem(prefix+key); return { key, deleted:true, shared: !!shared }; }
      catch(e){ return null; }
    },
    async list(prefixFilter, shared){
      try{
        const keys = [];
        for(let i=0;i<localStorage.length;i++){
          const k = localStorage.key(i);
          if(k && k.startsWith(prefix)){
            const short = k.slice(prefix.length);
            if(!prefixFilter || short.startsWith(prefixFilter)) keys.push(short);
          }
        }
        return { keys, prefix: prefixFilter, shared: !!shared };
      }catch(e){ return null; }
    }
  };
}
const NATIVE_STORAGE = (window.storage && typeof window.storage.get === 'function')
  ? window.storage
  : makeLocalStoragePolyfill();
let FIRESTORE_ERROR_SHOWN = false;
function reportFirestoreError(e){
  console.error('Firestore error:', e);
  if(FIRESTORE_ERROR_SHOWN) return;
  FIRESTORE_ERROR_SHOWN = true;
  const code = e && e.code;
  let msg = "⚠️ Vos données ne se sauvegardent pas sur votre compte (erreur : " + (code || e.message || 'inconnue') + ").";
  if(code === 'permission-denied'){
    msg = "⚠️ Sauvegarde bloquée : les règles de sécurité Firestore n'autorisent pas l'écriture. Vérifiez-les dans la console Firebase.";
  }
  showToast(msg);
}
function makeFirestoreShim(uid){
  function docFor(key, shared){
    return shared ? fbDb.collection('shared').doc(key) : fbDb.collection('users').doc(uid).collection('data').doc(key);
  }
  return {
    async get(key, shared){
      try{
        const snap = await docFor(key, shared).get();
        if(!snap.exists) return null;
        const d = snap.data();
        return { key, value: d.value, shared: !!shared };
      }catch(e){ console.warn('storage.get', key, e); reportFirestoreError(e); return null; }
    },
    async set(key, value, shared){
      try{
        await docFor(key, shared).set({ value, updatedAt: Date.now() });
        return { key, value, shared: !!shared };
      }catch(e){ console.warn('storage.set', key, e); reportFirestoreError(e); return null; }
    },
    async delete(key, shared){
      try{ await docFor(key, shared).delete(); return { key, deleted:true, shared: !!shared }; }
      catch(e){ reportFirestoreError(e); return null; }
    },
    async list(prefix, shared){
      try{
        const col = shared ? fbDb.collection('shared') : fbDb.collection('users').doc(uid).collection('data');
        const snap = await col.get();
        const keys = snap.docs.map(d=>d.id).filter(k=> !prefix || k.startsWith(prefix));
        return { keys, prefix, shared: !!shared };
      }catch(e){ reportFirestoreError(e); return null; }
    }
  };
}

let CURRENT_USER = null;

function authError(msg){
  const el = document.getElementById('auth-error');
  el.textContent = msg;
  el.classList.add('show');
}
function clearAuthError(){
  document.getElementById('auth-error').classList.remove('show');
}
const AUTH_ERROR_MESSAGES = {
  'auth/invalid-email': "Adresse email invalide.",
  'auth/user-not-found': "Aucun compte avec cet email.",
  'auth/wrong-password': "Mot de passe incorrect.",
  'auth/invalid-credential': "Email ou mot de passe incorrect.",
  'auth/email-already-in-use': "Un compte existe déjà avec cet email.",
  'auth/weak-password': "Le mot de passe doit faire au moins 6 caractères.",
  'auth/unauthorized-domain': "Ce domaine n'est pas autorisé côté Firebase (à ajouter dans Authentication → Paramètres → Domaines autorisés).",
  'auth/network-request-failed': "Problème réseau — vérifiez votre connexion."
};
function friendlyAuthError(err){
  const raw = err.message || String(err);
  if(/database|indexeddb/i.test(raw)){
    return "Le navigateur a eu un souci pour mémoriser votre connexion (souvent temporaire). Réessayez, ou utilisez le bouton de réinitialisation ci-dessous.";
  }
  return AUTH_ERROR_MESSAGES[err.code] || raw || "Une erreur est survenue.";
}

let AUTH_MODE_TAB = 'login';
function setAuthSubmitLoading(loading){
  const btn = document.getElementById('auth-submit-btn');
  btn.disabled = loading;
  btn.textContent = loading ? 'Un instant…' : (AUTH_MODE_TAB==='login' ? 'Se connecter' : 'Créer mon compte');
}
function wireAuthScreen(){
  document.getElementById('auth-tab-login').onclick = ()=>{
    AUTH_MODE_TAB='login'; clearAuthError();
    document.getElementById('auth-tab-login').classList.add('active');
    document.getElementById('auth-tab-signup').classList.remove('active');
    document.getElementById('auth-submit-btn').textContent = 'Se connecter';
  };
  document.getElementById('auth-tab-signup').onclick = ()=>{
    AUTH_MODE_TAB='signup'; clearAuthError();
    document.getElementById('auth-tab-signup').classList.add('active');
    document.getElementById('auth-tab-login').classList.remove('active');
    document.getElementById('auth-submit-btn').textContent = 'Créer mon compte';
  };
  document.getElementById('auth-password-toggle').onclick = ()=>{
    const input = document.getElementById('auth-password');
    const btn = document.getElementById('auth-password-toggle');
    if(input.type === 'password'){ input.type = 'text'; btn.textContent = '🙈'; }
    else { input.type = 'password'; btn.textContent = '👁️'; }
  };
  document.getElementById('auth-submit-btn').onclick = async ()=>{
    clearAuthError();
    const email = document.getElementById('auth-email').value.trim();
    const password = document.getElementById('auth-password').value;
    if(!email || !password){ authError("Merci de renseigner un email et un mot de passe."); return; }
    if(!FIREBASE_READY){ authError("La connexion à Firebase n'est pas disponible dans cet environnement."); return; }
    setAuthSubmitLoading(true);
    try{
      if(AUTH_MODE_TAB==='login'){
        await fbAuth.signInWithEmailAndPassword(email, password);
      } else {
        await fbAuth.createUserWithEmailAndPassword(email, password);
      }
    }catch(e){
      if(fbAuth.currentUser){
        CURRENT_USER = fbAuth.currentUser;
        window.storage = makeFirestoreShim(CURRENT_USER.uid);
        document.getElementById('auth-screen').classList.add('hidden');
        setAuthSubmitLoading(false);
        startApp();
        return;
      }
      authError(friendlyAuthError(e)); showAuthResetOption();
    }
    setAuthSubmitLoading(false);
  };
  document.getElementById('auth-google-btn').onclick = async ()=>{
    clearAuthError();
    if(!FIREBASE_READY){ authError("La connexion à Firebase n'est pas disponible dans cet environnement."); return; }
    try{
      const provider = new firebase.auth.GoogleAuthProvider();
      await fbAuth.signInWithPopup(provider);
    }catch(e){
      if(fbAuth.currentUser){
        // La connexion Google a en réalité réussi ; seule l'écriture locale a échoué.
        CURRENT_USER = fbAuth.currentUser;
        window.storage = makeFirestoreShim(CURRENT_USER.uid);
        document.getElementById('auth-screen').classList.add('hidden');
        startApp();
        return;
      }
      if(e.code === 'auth/popup-blocked' || e.code === 'auth/cancelled-popup-request'){
        authError("La fenêtre Google a été bloquée par le navigateur. Autorisez les popups pour ce site, ou utilisez la connexion par email.");
      } else if(e.code !== 'auth/popup-closed-by-user'){
        authError(friendlyAuthError(e));
        showAuthResetOption();
      }
    }
  };
  document.getElementById('auth-forgot-btn').onclick = async ()=>{
    clearAuthError();
    const email = document.getElementById('auth-email').value.trim();
    if(!email){ authError("Renseignez d'abord votre adresse email ci-dessus, puis touchez à nouveau ce lien."); return; }
    if(!FIREBASE_READY){ authError("La connexion à Firebase n'est pas disponible dans cet environnement."); return; }
    try{
      await fbAuth.sendPasswordResetEmail(email);
      authError("Un email pour réinitialiser votre mot de passe vient de vous être envoyé.");
    }catch(e){ authError(friendlyAuthError(e)); showAuthResetOption(); }
  };
  document.getElementById('auth-guest-btn').onclick = ()=>{
    window.storage = NATIVE_STORAGE;
    CURRENT_USER = null;
    document.getElementById('auth-screen').classList.add('hidden');
    startApp();
  };
}

async function initAuthPersistence(){
  const P = firebase.auth.Auth.Persistence;
  try{
    await fbAuth.setPersistence(P.LOCAL);
    return 'LOCAL';
  }catch(e1){
    console.warn('Persistance LOCAL (IndexedDB) indisponible, repli sur SESSION', e1);
    try{
      await fbAuth.setPersistence(P.SESSION);
      return 'SESSION';
    }catch(e2){
      console.warn('Persistance SESSION indisponible, repli sur NONE', e2);
      try{
        await fbAuth.setPersistence(P.NONE);
        return 'NONE';
      }catch(e3){
        console.warn('Aucun mode de persistance disponible', e3);
        return null;
      }
    }
  }
}

async function startAuthFlow(){
  wireAuthScreen();
  if(!FIREBASE_READY){
    document.getElementById('auth-loading').style.display = 'none';
    document.getElementById('auth-form-wrap').style.display = 'block';
    authError("Firebase n'a pas pu s'initialiser ici — vous pouvez continuer sans compte.");
    return;
  }
  const persistenceMode = await initAuthPersistence();
  if(persistenceMode === 'SESSION'){
    showToast("Mode de connexion simplifié activé (vous devrez vous reconnecter à chaque nouvelle visite, mais vos données restent bien sauvegardées).");
  } else if(persistenceMode === 'NONE'){
    showToast("Stockage du navigateur indisponible : la connexion ne survivra pas au rechargement de la page.");
  }
  let resolved = false;
  const timeoutId = setTimeout(()=>{
    if(resolved) return;
    resolved = true;
    document.getElementById('auth-loading').style.display = 'none';
    document.getElementById('auth-form-wrap').style.display = 'block';
    authError("La connexion met trop de temps à répondre (souvent un souci de stockage du navigateur). Vous pouvez réessayer, réinitialiser la connexion ci-dessous, ou continuer sans compte.");
    showAuthResetOption();
  }, 7000);
  try{
    fbAuth.onAuthStateChanged(
      (user)=>{
        if(resolved) return;
        resolved = true;
        clearTimeout(timeoutId);
        if(user){
          CURRENT_USER = user;
          window.storage = makeFirestoreShim(user.uid);
          document.getElementById('auth-screen').classList.add('hidden');
          startApp();
        } else {
          document.getElementById('auth-loading').style.display = 'none';
          document.getElementById('auth-form-wrap').style.display = 'block';
        }
      },
      (err)=>{
        if(resolved) return;
        resolved = true;
        clearTimeout(timeoutId);
        console.error('onAuthStateChanged error', err);
        document.getElementById('auth-loading').style.display = 'none';
        document.getElementById('auth-form-wrap').style.display = 'block';
        authError("Problème de connexion au service d'authentification (" + (err.message||err) + "). Réessayez, réinitialisez la connexion, ou continuez sans compte.");
        showAuthResetOption();
      }
    );
  }catch(err){
    clearTimeout(timeoutId);
    resolved = true;
    console.error('startAuthFlow error', err);
    document.getElementById('auth-loading').style.display = 'none';
    document.getElementById('auth-form-wrap').style.display = 'block';
    authError("Erreur d'initialisation de la connexion. Réinitialisez la connexion ci-dessous ou continuez sans compte.");
    showAuthResetOption();
  }
}
function showAuthResetOption(){
  if(document.getElementById('auth-reset-btn')) return;
  const btn = document.createElement('button');
  btn.id = 'auth-reset-btn';
  btn.className = 'auth-forgot-link';
  btn.textContent = '🔄 Réinitialiser la connexion (efface le cache de connexion local)';
  btn.onclick = async ()=>{
    try{
      if(window.indexedDB && indexedDB.databases){
        const dbs = await indexedDB.databases();
        await Promise.all(dbs.map(d=> new Promise(res=>{
          const req = indexedDB.deleteDatabase(d.name);
          req.onsuccess = req.onerror = req.onblocked = res;
        })));
      } else if(window.indexedDB){
        await new Promise(res=>{
          const req = indexedDB.deleteDatabase('firebaseLocalStorageDb');
          req.onsuccess = req.onerror = req.onblocked = res;
        });
      }
    }catch(e){ console.warn('reset indexedDB failed', e); }
    window.location.reload();
  };
  document.getElementById('auth-form-wrap').appendChild(btn);
}

function renderCompte(){
  let html = `<h2 class="section-title">👤 Mon compte</h2>
    <div class="card">
      <label style="font-family:'Inter',sans-serif; font-size:12px; color:var(--ink-soft); display:block; margin-bottom:4px;">Comment souhaitez-vous qu'on vous appelle ?</label>
      <div style="display:flex; gap:8px;">
        <input type="text" id="compte-name-input" value="${USER_NAME||''}" placeholder="Votre prénom">
        <button class="btn btn-gold btn-sm" id="compte-name-save">Enregistrer</button>
      </div>
    </div>`;
  if(CURRENT_USER){
    html += `<div class="card" id="account-info">
      <p class="entry-detail-text">Connecté(e) en tant que :<br><b>${CURRENT_USER.email}</b></p>
      <p class="section-desc">Vos prières, votre journal et votre progression sont sauvegardés sur ce compte et retrouvables sur n'importe quel appareil où vous vous reconnectez.</p>
      <button class="btn btn-ghost btn-sm" id="logout-btn">Se déconnecter</button>
    </div>`;
  } else {
    html += `<div class="card">
      <p class="entry-detail-text">Vous utilisez Lumen sans compte : vos données restent uniquement sur cet appareil, dans ce navigateur.</p>
      <p class="section-desc">Créez un compte pour retrouver vos données sur un autre appareil.</p>
      <button class="btn btn-primary btn-sm" id="login-now-btn">Créer un compte / Se connecter</button>
    </div>`;
  }
  document.getElementById('screen').innerHTML = html;
  document.getElementById('compte-name-save').onclick = async ()=>{
    const val = document.getElementById('compte-name-input').value.trim();
    USER_NAME = val.slice(0, 30);
    await savePrefs();
    showToast('Prénom mis à jour ✦');
  };
  const logoutBtn = document.getElementById('logout-btn');
  if(logoutBtn) logoutBtn.onclick = async ()=>{ await fbAuth.signOut(); window.location.reload(); };
  const loginNowBtn = document.getElementById('login-now-btn');
  if(loginNowBtn) loginNowBtn.onclick = ()=> window.location.reload();
}

