/* ---- reused helper functions (liturgical calendar) ---- */
function getEasterDate(year){
  const a = year % 19, b = Math.floor(year/100), c = year % 100;
  const d = Math.floor(b/4), e = b % 4, f = Math.floor((b+8)/25);
  const g = Math.floor((b-f+1)/3), h = (19*a + b - d - g + 15) % 30;
  const i = Math.floor(c/4), k = c % 4, l = (32 + 2*e + 2*i - h - k) % 7;
  const m = Math.floor((a + 11*h + 22*l) / 451);
  const month = Math.floor((h + l - 7*m + 114) / 31);
  const day = ((h + l - 7*m + 114) % 31) + 1;
  return new Date(year, month-1, day);
}
function addDays(date, n){ const d = new Date(date); d.setDate(d.getDate()+n); return d; }
function adventStart(year){
  const d = new Date(year, 10, 30);
  while(d.getDay() !== 0) d.setDate(d.getDate()-1);
  return d;
}
function formatDateFR(date){
  return date.toLocaleDateString("fr-FR", {day:"numeric", month:"long", year:"numeric"});
}
function buildFetesMobilesEntries(year){
  const easter = getEasterDate(year);
  const defs = [
    {name:"Mercredi des Cendres", offset:-46, ref:"Ouvre le Carême", summary:"Marque l'entrée en Carême : les fidèles reçoivent une croix de cendre sur le front en signe de pénitence et de mortalité."},
    {name:"Dimanche des Rameaux", offset:-7, ref:"Ouvre la Semaine sainte", summary:"Commémore l'entrée triomphale de Jésus à Jérusalem, acclamé avec des rameaux, quelques jours avant sa Passion."},
    {name:"Jeudi saint", offset:-3, ref:"Ouvre le Triduum pascal", summary:"Commémore la dernière Cène et l'institution de l'eucharistie, ainsi que le lavement des pieds des disciples par Jésus."},
    {name:"Vendredi saint", offset:-2, ref:"Jour de jeûne et d'abstinence", summary:"Commémore la Passion et la mort de Jésus sur la croix ; aucune messe n'est célébrée ce jour-là, remplacée par une liturgie de la Parole et l'adoration de la croix."},
    {name:"Pâques", offset:0, ref:"La plus grande fête chrétienne", summary:"Célèbre la résurrection de Jésus-Christ, fondement de la foi chrétienne, précédée la veille au soir par la Vigile pascale."},
    {name:"Ascension", offset:39, ref:"40 jours après Pâques (souvent déplacée au dimanche suivant)", summary:"Commémore l'élévation de Jésus ressuscité auprès de Dieu, quarante jours après Pâques, marquant la fin de ses apparitions terrestres."},
    {name:"Pentecôte", offset:49, ref:"Clôt le Temps pascal", summary:"Commémore le don de l'Esprit Saint aux apôtres, cinquante jours après Pâques, traditionnellement vue comme la naissance de l'Église."},
    {name:"Sainte Trinité", offset:56, ref:"Dimanche après la Pentecôte", summary:"Célèbre le mystère central de la foi chrétienne : un seul Dieu en trois personnes, Père, Fils et Esprit Saint."},
    {name:"Fête-Dieu (Corps et Sang du Christ)", offset:63, ref:"Souvent célébrée le dimanche suivant", summary:"Célèbre la présence du Christ dans l'eucharistie, parfois marquée par une procession du Saint-Sacrement."}
  ];
  return defs.map(d => ({
    name:d.name, dates:formatDateFR(addDays(easter, d.offset)), tag:null, ref:d.ref,
    externalUrl:"https://www.google.com/search?q=" + encodeURIComponent(d.name + " signification"),
    linkLabel:"En savoir plus ↗", summary:d.summary
  }));
}

