/* ---------- new content: glossary, sacraments, rosary, examen, bible index ---------- */
const GLOSSARY = [
  {term:"Indulgence", def:"La remise, devant Dieu, de la peine temporelle due pour des péchés déjà pardonnés. Elle ne remplace pas la confession ni le pardon lui-même — elle concerne les conséquences du péché qui demeurent après qu'il a été pardonné. L'Église l'accorde par l'intercession des mérites du Christ et des saints."},
  {term:"Indulgence plénière", def:"Remise totale de cette peine temporelle. Elle demande, le même jour : la confession, la communion, la prière aux intentions du pape, et l'accomplissement de l'œuvre indiquée (par exemple une visite, une lecture), avec un cœur détaché de tout péché, même véniel."},
  {term:"Indulgence partielle", def:"Remise partielle de la peine temporelle, accordée pour des actes de piété plus simples (une courte prière, un geste de charité accompli avec un cœur contrit)."},
  {term:"Peine temporelle", def:"Les conséquences du péché qui subsistent même après le pardon reçu en confession — à distinguer de la faute elle-même, qui est, elle, totalement effacée par le sacrement."},
  {term:"Encyclique", def:"Lettre solennelle qu'un pape adresse à toute l'Église, souvent sur un sujet doctrinal, moral ou social majeur."},
  {term:"Homélie", def:"Commentaire de la Parole de Dieu prononcé par le prêtre ou le diacre pendant la messe, après les lectures."},
  {term:"Magistère", def:"L'autorité d'enseignement de l'Église, exercée par le pape et les évêques en communion avec lui."},
  {term:"Catéchisme", def:"Un résumé organisé de la foi et de la morale catholiques, destiné à l'enseignement des croyants."},
  {term:"Liturgie", def:"L'ensemble des rites et prières officiels par lesquels l'Église célèbre le culte de Dieu."},
  {term:"Chrême", def:"Huile consacrée utilisée notamment lors du baptême, de la confirmation et de l'ordination."},
  {term:"Eucharistie", def:"Le sacrement central de la messe, dans lequel le pain et le vin deviennent le corps et le sang du Christ."},
  {term:"Diocèse", def:"Un territoire confié à la charge pastorale d'un évêque."},
  {term:"Paroisse", def:"Une communauté chrétienne locale confiée à un curé, unité de base de la vie de l'Église."},
  {term:"Concile", def:"Une assemblée solennelle d'évêques réunie pour statuer sur des questions de foi ou de discipline."},
  {term:"Dogme", def:"Une vérité de foi définie solennellement par l'Église comme faisant partie de la Révélation."},
  {term:"Grâce", def:"Un don gratuit de Dieu, non mérité, qui élève et transforme la personne qui le reçoit."},
  {term:"Rédemption", def:"L'œuvre par laquelle le Christ a racheté l'humanité de ses péchés par sa mort et sa résurrection."},
  {term:"Vocation", def:"Un appel de Dieu à un état de vie particulier — mariage, sacerdoce, vie consacrée..."},
  {term:"Discernement", def:"Le processus par lequel on cherche à reconnaître la volonté de Dieu dans une situation donnée."},
  {term:"Intercession", def:"L'action de prier pour quelqu'un d'autre, en se faisant l'intermédiaire de sa demande auprès de Dieu."},
  {term:"Communion des saints", def:"Le lien spirituel qui unit tous les fidèles, vivants et défunts, dans le Christ."},
  {term:"Purgatoire", def:"Un état de purification après la mort pour ceux qui meurent en état de grâce mais encore imparfaitement purifiés."},
  {term:"Béatification", def:"La reconnaissance officielle par l'Église qu'une personne défunte peut être vénérée localement — une étape avant la canonisation."},
  {term:"Canonisation", def:"La déclaration officielle par l'Église qu'une personne est au ciel et peut être vénérée comme sainte par toute l'Église."}
];

const SACREMENTS = [
  {name:"Baptême", avatar:"💧", tag:"1er sacrement", symbole:"L'eau (purification et vie nouvelle), le cierge (lumière du Christ), le vêtement blanc (pureté nouvelle).", conditions:"Peut être reçu à tout âge. Pour un enfant, l'accord des parents et le choix d'un parrain et d'une marraine pratiquants sont demandés ; pour un adulte, un parcours de préparation (catéchuménat) est requis.", deroulement:"Le prêtre verse de l'eau sur la tête (ou plonge la personne dedans) en disant : « Je te baptise au nom du Père, et du Fils, et du Saint-Esprit. » Suivent l'onction du saint chrême, la remise du vêtement blanc et du cierge allumé au cierge pascal.", summary:"Premier sacrement, il efface le péché originel et fait entrer dans la vie chrétienne et dans l'Église. Il peut être reçu à tout âge, souvent dès l'enfance."},
  {name:"Confirmation", avatar:"🔥", tag:"2e sacrement", symbole:"L'huile du saint chrême et l'imposition des mains, signes de la force de l'Esprit Saint.", conditions:"Réservée aux baptisés. Souvent reçue à l'adolescence après une catéchèse, mais un adulte peut aussi la recevoir ; un parrain ou une marraine de confirmation accompagne le candidat.", deroulement:"L'évêque (ou un prêtre délégué) impose la main sur le candidat, l'oint de saint chrême sur le front et prononce : « Sois marqué de l'Esprit Saint, le don de Dieu. » Elle est le plus souvent célébrée pendant une messe.", summary:"Il confirme et fortifie la grâce du baptême par le don de l'Esprit Saint, souvent reçu à l'adolescence après une préparation."},
  {name:"Eucharistie", avatar:"🍞", tag:"3e sacrement", symbole:"Le pain et le vin, devenus le Corps et le Sang du Christ.", conditions:"La première communion suit généralement le baptême et une catéchèse ; ensuite, elle peut être reçue à chaque messe par les catholiques en état de grâce (sans péché grave non confessé).", deroulement:"Pendant la prière eucharistique, le prêtre reprend les paroles de Jésus à la Cène sur le pain et le vin. Les fidèles s'avancent en procession pour recevoir l'hostie consacrée, dans la main ou sur la langue, en disant « Amen ».", summary:"Cœur de la vie chrétienne : le pain et le vin consacrés à la messe deviennent le corps et le sang du Christ, reçus en communion."},
  {name:"Réconciliation (confession)", avatar:"🕊️", tag:"4e sacrement", symbole:"Le geste d'absolution du prêtre, signe visible du pardon de Dieu.", conditions:"Ouverte à tout baptisé ayant atteint l'âge de raison. Elle suppose un examen de conscience préalable et le regret sincère des péchés commis.", deroulement:"Le pénitent confesse ses péchés au prêtre (au confessionnal ou face à face), reçoit un conseil et une pénitence, prononce un acte de contrition, puis le prêtre donne l'absolution : « Je te pardonne tes péchés, au nom du Père, et du Fils, et du Saint-Esprit. »", summary:"Le pardon des péchés commis après le baptême, reçu par la confession sincère auprès d'un prêtre et l'absolution."},
  {name:"Onction des malades", avatar:"🤲", tag:"5e sacrement", symbole:"L'huile des malades, signe de réconfort et de force dans l'épreuve.", conditions:"Destinée aux personnes gravement malades, âgées ou sur le point de subir une opération importante — pas seulement à l'article de la mort, contrairement à une idée reçue.", deroulement:"Le prêtre impose les mains, prie pour le malade, puis l'oint du saint chrême sur le front et les mains en disant une prière demandant réconfort, paix et, si Dieu le veut, la guérison.", summary:"Un sacrement de réconfort et de force donné aux personnes gravement malades ou âgées, pour les soutenir dans l'épreuve."},
  {name:"Ordre (sacerdoce)", avatar:"⛪", tag:"6e sacrement", symbole:"L'imposition des mains de l'évêque, transmission d'une mission reçue depuis les apôtres.", conditions:"Réservé aux hommes baptisés, après plusieurs années de formation au séminaire ; suppose un discernement de vocation avec l'accompagnement de l'Église.", deroulement:"L'évêque impose les mains en silence sur le candidat, prononce la prière de consécration, puis remet les insignes propres à son degré (étole, chasuble pour un prêtre ; onction des mains pour la célébration de l'eucharistie).", summary:"Le sacrement par lequel un homme devient diacre, prêtre ou évêque, consacré au service de l'Église et des sacrements."},
  {name:"Mariage", avatar:"💍", tag:"7e sacrement", symbole:"Les alliances échangées, signe d'une fidélité mutuelle et définitive.", conditions:"Réservé à un homme et une femme baptisés, libres de tout engagement, qui préparent leur union avec le prêtre ou le diacre durant plusieurs mois.", deroulement:"Devant témoins, les époux échangent leur consentement (« Je te reçois comme épouse/époux... »), reçoivent la bénédiction nuptiale, puis échangent leurs alliances, souvent au cours d'une messe.", summary:"L'union libre et définitive d'un homme et d'une femme, reconnue comme une alliance à l'image de celle du Christ avec l'Église."}
];

