function todaysRosarySet(){
  const day = new Date().getDay(); // 0=dimanche
  if(day===1||day===6) return 'joyeux';
  if(day===2||day===5) return 'douloureux';
  if(day===4) return 'lumineux';
  return 'glorieux';
}

