const LITURGICAL_COLORS = {
  violet: {label:"Violet", hex:"#6B4C7A", meaning:"Attente et pénitence — Avent et Carême"},
  blanc: {label:"Blanc / Or", hex:"#C9A857", meaning:"Joie et fête — Noël, Pâques, fêtes du Seigneur et des saints non martyrs"},
  rouge: {label:"Rouge", hex:"#A8283B", meaning:"Le feu de l'Esprit et le sang des martyrs — Pentecôte, Passion, fêtes des martyrs"},
  vert: {label:"Vert", hex:"#4C7A5A", meaning:"Espérance et croissance — le Temps ordinaire"}
};
function todaysLiturgicalColor(){
  const banner = computeLiturgicalSeasonBanner();
  if(banner.includes("Avent") || banner.includes("Carême")) return 'violet';
  if(banner.includes("Noël") || banner.includes("pascal")) return 'blanc';
  if(banner.includes("Triduum")) return 'violet';
  return 'vert';
}

