function todayKey(){
  const d = new Date();
  const mm = String(d.getMonth()+1).padStart(2,'0');
  const dd = String(d.getDate()).padStart(2,'0');
  return mm+'-'+dd;
}
function dayOfYear(){
  const d = new Date();
  const start = new Date(d.getFullYear(),0,0);
  return Math.floor((d - start) / 86400000);
}
function saintDateLabel(mmdd){
  if(!mmdd) return '';
  const [mm,dd] = mmdd.split('-').map(Number);
  return `${dd} ${MONTH_NAMES_FR[mm-1]||''}`;
}
function getSaintOfDay(){
  const key = todayKey();
  const exact = SAINTS.find(s => s.d === key);
  if(exact) return {saint: exact, isFeast:true};
  const idx = dayOfYear() % SAINTS.length;
  return {saint: SAINTS[idx], isFeast:false};
}
function frenchDate(){
  const d = new Date();
  return d.toLocaleDateString('fr-FR', {weekday:'long', day:'numeric', month:'long'});
}

/* ---------- render ---------- */
function getOrderedTabs(){
  if(!TAB_ORDER || !TAB_ORDER.length) return PRIMARY_TABS;
  const byKey = {}; PRIMARY_TABS.forEach(t=> byKey[t.key]=t);
  const ordered = TAB_ORDER.map(k=>byKey[k]).filter(Boolean);
  PRIMARY_TABS.forEach(t=>{ if(!ordered.includes(t)) ordered.push(t); });
  return ordered;
}
function renderTabbar(){
  const tabs = getOrderedTabs();
  const activeTabKey = primaryToTabKey(PRIMARY);
  document.getElementById('tabbar').innerHTML =
    `<div class="tabbar-brand"><span class="tabbar-brand-flame">🕯️</span><span class="tabbar-brand-name">Lumen</span></div>` +
    tabs.map(t =>
      `<button class="tab-btn ${activeTabKey===t.key?'active':''}" data-tab="${t.key}">${ICONS[t.key]||''}<span>${t.label}</span></button>`
    ).join('');
  document.querySelectorAll('.tab-btn').forEach(btn=>{
    btn.onclick = ()=>{
      const oldIdx = tabs.findIndex(t=>t.key===activeTabKey);
      const newIdx = tabs.findIndex(t=>t.key===btn.dataset.tab);
      TAB_SLIDE_DIR = newIdx > oldIdx ? 'left' : 'right';
      PRIMARY = btn.dataset.tab;
      /* Toucher l'onglet "Prier" ramène toujours à son accueil (où se trouve
         le lien vers Dévotions), plutôt que de rester bloqué sur le dernier
         sous-onglet visité — sans quoi Dévotions deviendrait introuvable
         après la première visite. */
      if(PRIMARY === 'prier') SUBTAB.prier = 'accueil-prier';
      if(PRIMARY === 'ecritures') SUBTAB.ecritures = 'accueil-ecritures';
      if(PRIMARY === 'espace') SUBTAB.espace = 'accueil-espace';
      ENTRY_OPEN = null; OPEN_NOVENA = null; NOVENA_OPEN_DAY = null;
      render();
    };
  });
}

function goTo(primary, sub){
  PRIMARY = primary;
  if(sub) SUBTAB[primary] = sub;
  ENTRY_OPEN = null; OPEN_NOVENA = null; NOVENA_OPEN_DAY = null;
  render();
}

