function lumenSacredArtFor(entry, opts){
  // Cherche une correspondance précise (mot entier, pas une simple sous-chaîne) entre
  // le nom/texte de l'entrée et les mots-clés de LUMEN_SACRED_ART. On garde la
  // correspondance la plus spécifique (la plus longue) pour éviter qu'un nom comme
  // « Jean-Paul II » ne matche à tort sur la seule clé « paul ». Si rien de fiable
  // n'est trouvé, on retourne null et l'entrée garde son emoji — jamais d'image au hasard.
  if(!entry) return null;
  // nameOnly : pour les figures de « Bible & Histoire », de nombreux résumés citent
  // d'autres personnages (« André, frère de Simon-Pierre », « ... selon la promesse
  // faite à Jésus »...) — chercher dans le résumé entier ferait à tort apparaître le
  // portrait d'une tout autre personne, ou l'image générique du Sacré-Cœur sur
  // presque toutes les fiches qui mentionnent Jésus. On ne regarde donc que le nom
  // propre de l'entrée elle-même dans ce contexte.
  const nameOnly = opts && opts.nameOnly;
  const rawText = nameOnly ? (entry.name||'').trim() : ((entry.name||'') + ' ' + (entry.summary||'')).trim();
  if(!rawText) return null;
  const text = ' ' + normalizeForMatch(rawText).join(' ') + ' ';
  let best = null, bestLen = 0;
  for(const item of LUMEN_SACRED_ART){
    if(nameOnly && item.generic) continue;
    // requireAlso : pour un prénom ambigu partagé par plusieurs figures (ex. « Joseph »,
    // à la fois saint époux de Marie et patriarche fils de Jacob dans l'Ancien Testament),
    // on exige la présence d'un second mot distinctif avant de retenir la correspondance,
    // plutôt que de risquer d'afficher le mauvais portrait sur la mauvaise figure.
    if(item.requireAlso){
      const normAlso = normalizeForMatch(item.requireAlso).join(' ');
      if(normAlso && !text.includes(' ' + normAlso + ' ')) continue;
    }
    for(const key of item.keys){
      const normKey = normalizeForMatch(key).join(' ');
      if(!normKey) continue;
      if(text.includes(' ' + normKey + ' ') && normKey.length > bestLen){
        bestLen = normKey.length;
        best = item;
      }
    }
  }
  return best;
}

/* Pour les neuvaines dédiées à un saint ou une figure représentés par une vraie
   œuvre/photo dans LUMEN_SACRED_ART, on préfère cette image réelle à l'illustration
   dessinée — "de vraies images" plutôt que des pictogrammes, quand une correspondance
   fiable existe. Les neuvaines plus symboliques (Esprit Saint, étoile...) gardent
   leur illustration dédiée, faute de photographie pertinente. */
const NOVENA_REAL_ART_KEY = {
  'joseph': 'joseph',
  'joseph-neuvaine-familiale': 'joseph',
  'sacre-coeur': 'sacré-cœur',
  'marie-confiance': 'marie',
  'marie-confiance-abandon': 'marie',
  'therese': 'thérèse',
  'michel': 'michel'
};
function findSacredArtByKey(key){
  return LUMEN_SACRED_ART.find(item => item.keys.includes(key)) || null;
}
function lumenNovenaDedicatedArt(entry){
  if(!entry) return null;
  const id=(entry.id||entry.key||'').toLowerCase();
  if(id && NOVENA_REAL_ART_KEY[id]){
    const real = findSacredArtByKey(NOVENA_REAL_ART_KEY[id]);
    if(real) return real;
  }
  if(id && LUMEN_NOVENA_IMAGE_MAP[id]) return LUMEN_NOVENA_IMAGE_MAP[id];
  const title=(entry.title||entry.name||'').toLowerCase();
  const aliases=[
    ['saint joseph — pour la famille','joseph-neuvaine-familiale'],
    ['saint joseph','joseph'],
    ['sacré-cœur','sacre-coeur'],['sacre-coeur','sacre-coeur'],
    ['notre-dame','marie-confiance'],['marie — la confiance','marie-confiance-abandon'],
    ['sainte thérèse','therese'],['sainte therese','therese'],
    ['saint michel','michel'],['esprit saint','esprit-saint'],
    ['sainte rita','sainte-rita'],['saint antoine','antoine-padoue'],
    ['étoile','neuvaine-etoile'],['etoile','neuvaine-etoile']
  ];
  const hit=aliases.find(([needle])=>title.includes(needle));
  return hit ? LUMEN_NOVENA_IMAGE_MAP[hit[1]] : null;
}

/* Boîtes de texte façon "le saviez-vous" : remplace l'ancien fond à lignes de
   cahier (qui se désalignait dès que la taille du texte changeait — A-/A+,
   police dyslexie...) par des cartes indépendantes de la mise en page, chacune
   surmontée d'un badge-icône. Un texte à plusieurs paragraphes (séparés par un
   saut de ligne double) devient plusieurs boîtes, chacune avec sa propre icône —
   un style plus robuste et plus vivant qu'un simple bloc de texte continu. */
const TEXT_BOX_ICONS = { prayer:['🙏','🕯️','✨'], reading:['📖','✨','💭','🕊️'] };
function carnetBoxesHTML(text, kind){
  if(!text) return '';
  const icons = TEXT_BOX_ICONS[kind] || TEXT_BOX_ICONS.reading;
  const paragraphs = String(text).split(/\n\s*\n/).map(p=>p.trim()).filter(Boolean);
  const parts = paragraphs.length ? paragraphs : [String(text)];
  const boxClass = kind==='prayer' ? 'text-box text-box--prayer' : 'text-box text-box--reading';
  return `<div class="text-box-group">` + parts.map((p,i)=>
    `<div class="${boxClass}"><span class="text-box-icon">${icons[i % icons.length]}</span><p class="text-box-text">${linkifyClassicPrayers(p)}</p></div>`
  ).join('') + `</div>`;
}

/* Carte compacte « Ma progression » de l'accueil : petite vignette carrée à
   gauche + titre, sous-titre et vraie barre de progression à droite — comme
   dans la maquette (plus compacte que les cartes-photo pleine largeur). */
function homeProgressCardHTML({img, icon, bg, title, sub, current, total, footnote, ctaLabel, extraClass, attrs}){
  const pct = total ? Math.max(4, Math.round(100*current/total)) : 0;
  return `<div class="card home-progress-card ${extraClass||''}" ${attrs||''}>
    <div class="home-progress-card-img" style="background:${bg||'var(--gold-pale)'};">
      ${img ? `<img src="${img}" alt="" loading="lazy" onerror="this.parentElement.innerHTML='${icon||'🕯️'}'">` : (icon||'🕯️')}
    </div>
    <div class="home-progress-card-body">
      <p class="home-progress-card-title">${title}</p>
      <p class="home-progress-card-sub">${sub}</p>
      ${total ? `<div class="home-progress-bar"><div class="home-progress-bar-fill" style="width:${pct}%;"></div></div>` : ''}
      ${footnote ? `<p class="home-progress-card-footnote">${footnote}</p>` : ''}
      <button class="btn btn-primary btn-sm">${ctaLabel}</button>
    </div>
  </div>`;
}
function novenaPrayerCount(n){
  let h = 0; for(const c of n.id) h = (h*31 + c.charCodeAt(0)) % 99999;
  return 300 + (h % 28000);
}

function novenaCardHTML(n, info){
  const art = lumenNovenaDedicatedArt({id:n.id, name:n.title, summary:n.sub});
  return `<div class="card novena-card hoz-card" style="--accent:${n.color};" data-id="${n.id}">
    <div class="hoz-card-img">
      ${art ? `<img src="${art.url}" alt="${n.title}" loading="lazy" onerror="this.parentElement.innerHTML='<span class=&quot;novena-icon-fallback&quot;>${NOVENA_ICONS[n.id]||'🕯️'}</span>'">` : `<span class="novena-icon-fallback">${NOVENA_ICONS[n.id]||'🕯️'}</span>`}
      <span class="novena-card-tag" style="background:${n.color};">${n.tag}</span>
      <span class="hoz-card-progress-pill ${info.done?'hoz-card-progress-done':''}">${info.done ? '✓ Terminée' : `Jour ${info.currentDay}/9`}</span>
    </div>
    <div class="hoz-card-body">
      <p class="hoz-card-title">${n.title}</p>
      <p class="hoz-card-sub">${n.sub||''}</p>
      <div class="hoz-card-stats"><span>♥ ${(novenaPrayerCount(n)/100).toFixed(1).replace('.0','')}k</span><span>·</span><span>📅 9 jours</span><span>·</span><span>${info.completedCount}/9 priés</span></div>
    </div>
  </div>`;
}

/* ===== catalogue des neuvaines : recherche + filtres (Toutes / En cours / Populaires) ===== */
let NOVENA_FILTER = 'toutes';
let NOVENA_SEARCH = '';
const NOVENA_FILTERS = [
  {key:'toutes', label:'Toutes'},
  {key:'en-cours', label:'En cours'},
  {key:'populaires', label:'Populaires'}
];
function novenasFilteredList(){
  let list = NOVENAS.map(n=>({n, info:novenaProgressInfo(n)}));
  if(NOVENA_FILTER === 'en-cours') list = list.filter(x=> x.info.completedCount>0 && !x.info.done);
  if(NOVENA_FILTER === 'populaires') list = list.slice().sort((a,b)=> novenaPrayerCount(b.n)-novenaPrayerCount(a.n)).slice(0, Math.max(6, Math.ceil(NOVENAS.length/2)));
  const q = normalizeForMatch(NOVENA_SEARCH).join(' ').trim();
  if(q) list = list.filter(x=>{
    const hay = normalizeForMatch((x.n.title||'')+' '+(x.n.sub||'')+' '+(x.n.tag||'')).join(' ');
    return hay.includes(q);
  });
  return list;
}
function renderNovenas(){
  if(OPEN_NOVENA){ renderNovenaDetail(OPEN_NOVENA); return; }
  const inProgressNovenas = NOVENAS.map(n=>({n, info:novenaProgressInfo(n)})).filter(x=>x.info.completedCount>0 && !x.info.done);
  const missedToday = inProgressNovenas.length > 0 && STREAK.lastDate !== todayISO();
  let html = `<h2 class="section-title">🕯️ Neuvaines</h2>
    <p class="section-desc">Confiez vos intentions et cheminez, neuf jours durant.</p>
    <div class="novena-search-row"><input type="search" id="novena-search-input" class="novena-search-input" placeholder="Rechercher une neuvaine…" value="${NOVENA_SEARCH.replace(/"/g,'&quot;')}"></div>
    <div class="chip-row" id="novena-filter-row">${NOVENA_FILTERS.map(f=>`<button class="chip ${NOVENA_FILTER===f.key?'active':''}" data-novena-filter="${f.key}">${f.label}</button>`).join('')}</div>`;
  if(missedToday){
    html += `<div class="card" style="border-left:4px solid var(--gold); margin-bottom:14px;">
      <p class="eyebrow" style="color:var(--gold);">🕯️ Petit rappel, sans pression</p>
      <p class="entry-detail-text" style="margin:4px 0 0;">Vous n'avez pas encore prié aujourd'hui pour ${inProgressNovenas.length>1?'vos neuvaines en cours':'votre neuvaine en cours'} (${inProgressNovenas.map(x=>x.n.title).join(', ')}). Un jour manqué ne remet rien en cause — reprenez simplement quand vous êtes prêt(e).</p>
    </div>`;
  }
  const list = novenasFilteredList();
  html += `<div class="grid">`;
  if(!list.length){
    html += `<div class="empty-state" style="grid-column:1/-1;">Aucune neuvaine ne correspond à votre recherche.</div>`;
  } else {
    list.forEach(x=> html += novenaCardHTML(x.n, x.info));
  }
  html += `</div>`;
  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('.novena-card').forEach(c=> c.onclick = ()=>{ OPEN_NOVENA=c.dataset.id; NOVENA_FULLTEXT=false; NOVENA_OPEN_DAY=null; NOVENA_DAY_DONE_SCREEN=null; render(); });
  document.querySelectorAll('[data-novena-filter]').forEach(btn=>{
    btn.onclick = ()=>{ NOVENA_FILTER = btn.dataset.novenaFilter; render(); };
  });
  const searchInput = document.getElementById('novena-search-input');
  if(searchInput){
    searchInput.oninput = ()=>{ NOVENA_SEARCH = searchInput.value; render(); setTimeout(()=>{ const el=document.getElementById('novena-search-input'); if(el){ el.focus(); el.selectionStart = el.selectionEnd = el.value.length; } }, 0); };
  }
}

