function renderCategoryHubGeneric(title, desc, categories, onGoto, heroEmoji, heroImgUrl){
  const html = `
    ${heroEmoji ? `<div class="hub-hero-banner" style="background:${categories[0].color};">
      ${heroImgUrl ? `<img class="hub-hero-banner-img" src="${heroImgUrl}" alt="" onerror="this.remove();"><div class="hub-hero-scrim"></div>` : ''}
      <span class="hub-hero-emoji">${heroEmoji}</span>
    </div>` : ''}
    <h2 class="section-title">${title}</h2>
    <p class="section-desc">${desc}</p>
    <div class="rubric-list">${categories.map((c,i)=>`
      <button type="button" class="rubric-row" data-hub-goto="${c.goto||''}" data-hub-index="${i}">
        <span class="rubric-row-icon" style="background:${c.color};">${c.icon ? c.icon : `<img src="${c.img}" alt="" onerror="this.style.display='none'">`}</span>
        <span class="rubric-row-text">
          <span class="rubric-row-title">${c.label}</span>
          <span class="rubric-row-desc">${c.desc}</span>
        </span>
        <span class="rubric-row-chevron">›</span>
      </button>`).join('')}</div>`;
  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('[data-hub-goto]').forEach(card=>{
    card.onclick = ()=>{
      const cat = categories[parseInt(card.dataset.hubIndex,10)];
      if(cat && cat.cross){
        if(cat.cross.resetJesusHub) GROUP_SEL['jesus:main'] = null;
        goTo(cat.cross.primary, cat.cross.sub);
      }
      else { onGoto(card.dataset.hubGoto); }
    };
  });
}
