let PRIERES_SEARCH = '';
let PRIERES_CATEGORY = null;
const PRIERES_CAT_META = {
  'prieres-fondamentales': {icon:'📿', short:'Notre Père, Je vous salue Marie, Angélus, Salve Regina…'},
  'neuvaines': {icon:'🕯️', short:'22 neuvaines connues, avec leur prière centrale à répéter'},
  'prieres-aux-saints': {icon:'👑', short:'Jude, Padre Pio, Jean-Paul II, Bakhita, Vincent de Paul…'},
  'prieres-archanges': {icon:'⚔️', short:'Michel, Gabriel et Raphaël'}
};
function renderPrieresHub(){
  const compKey = 'prier:prieres';
  const halo = false;

  if(ENTRY_OPEN && ENTRY_OPEN.compKey === compKey){
    const group = PRIERES.find(g=>g.id===ENTRY_OPEN.groupId);
    const entry = group.entries[ENTRY_OPEN.idx];
    let html = `<div class="detail-wrap">
      <button class="back-link" id="back-btn">← ${group.title}</button>
      ${entryDetailHTML(entry, ENTRY_OPEN.idx, group.entries.length, halo, {primary:PRIMARY, sub:SUBTAB[PRIMARY], compKey, groupId:group.id})}
    </div>`;
    document.getElementById('screen').innerHTML = html;
    document.getElementById('back-btn').onclick = ()=>{ ENTRY_OPEN=null; render(); };
    const prevBtn = document.getElementById('entry-prev');
    const nextBtn = document.getElementById('entry-next');
    if(prevBtn) prevBtn.onclick = ()=>{ ENTRY_OPEN.idx--; render(); };
    if(nextBtn) nextBtn.onclick = ()=>{ ENTRY_OPEN.idx++; render(); };
    wireEntryDetailExtras(entry, `${compKey}:${group.id}:${ENTRY_OPEN.idx}`);
    return;
  }

  const totalCount = PRIERES.reduce((s,g)=>s+g.entries.length, 0);
  const q = PRIERES_SEARCH.trim().toLowerCase();

  let html = `<h2 class="section-title">📿 Prières (${totalCount})</h2>
    <div class="ambiance-search-wrap">
      <input type="text" id="prieres-search-input" placeholder="🔍 Chercher une prière, un saint, un mot-clé…" value="${PRIERES_SEARCH.replace(/"/g,'&quot;')}">
    </div>`;

  if(q){
    const results = [];
    PRIERES.forEach(g=>{
      g.entries.forEach((e,idx)=>{
        const hay = (e.name+' '+(e.ref||'')+' '+(e.summary||'')).toLowerCase();
        if(hay.includes(q)) results.push({group:g, entry:e, idx});
      });
    });
    html += `<p class="studio-note" style="margin-bottom:8px;">${results.length} résultat${results.length>1?'s':''} pour « ${q} »</p>`;
    html += `<div class="grid">${results.map(r=>`
      <div class="entry-card" data-group="${r.group.id}" data-idx="${r.idx}">
        <div class="entry-avatar">${r.entry.avatar||'🙏'}</div>
        <div class="entry-body"><p class="entry-name">${r.entry.name}</p><p class="entry-summary">${(PRIERES_CAT_META[r.group.id]||{}).icon||''} ${r.group.title}</p></div>
      </div>`).join('')}</div>`;
    document.getElementById('screen').innerHTML = html;
    wirePrieresSearch();
    document.querySelectorAll('.entry-card[data-group]').forEach(c=>{
      c.onclick = ()=>{ ENTRY_OPEN = {compKey, groupId:c.dataset.group, idx:parseInt(c.dataset.idx,10)}; render(); };
    });
    return;
  }

  if(!PRIERES_CATEGORY){
    html += `<p class="section-desc">Choisissez une catégorie pour commencer, ou cherchez directement une prière ci-dessus.</p>
      <div class="grid">${PRIERES.map(g=>`
        <div class="card prieres-cat-card" data-cat="${g.id}" style="cursor:pointer;">
          <span style="font-size:26px;">${(PRIERES_CAT_META[g.id]||{}).icon||'📿'}</span>
          <p class="day-title" style="font-size:15px; margin:6px 0 2px;">${g.title}</p>
          <p class="studio-note" style="margin:0;">${g.entries.length} prière${g.entries.length>1?'s':''}</p>
          <p class="entry-summary" style="margin-top:4px;">${(PRIERES_CAT_META[g.id]||{}).short||''}</p>
        </div>`).join('')}</div>`;
    document.getElementById('screen').innerHTML = html;
    wirePrieresSearch();
    document.querySelectorAll('.prieres-cat-card').forEach(c=>{
      c.onclick = ()=>{ PRIERES_CATEGORY = c.dataset.cat; render(); };
    });
    return;
  }

  const group = PRIERES.find(g=>g.id===PRIERES_CATEGORY);
  html += `<div style="margin-bottom:10px;"><button class="back-link" id="cat-back-btn">← Toutes les catégories</button></div>
    <h2 class="section-title" style="font-size:17px;">${(PRIERES_CAT_META[group.id]||{}).icon||''} ${group.title}</h2>
    <p class="section-desc">${group.desc||''}</p>
    <div class="grid">${group.entries.map((e,i)=>entryCardHTML(e,i,halo)).join('')}</div>`;
  document.getElementById('screen').innerHTML = html;
  wirePrieresSearch();
  document.getElementById('cat-back-btn').onclick = ()=>{ PRIERES_CATEGORY = null; render(); };
  document.querySelectorAll('.entry-card').forEach(c=>{
    c.onclick = ()=>{ ENTRY_OPEN = {compKey, groupId:group.id, idx:parseInt(c.dataset.idx,10)}; render(); };
  });
}
function wirePrieresSearch(){
  const input = document.getElementById('prieres-search-input');
  if(!input) return;
  input.oninput = (e)=>{
    PRIERES_SEARCH = e.target.value;
    const caret = e.target.selectionStart;
    render();
    const el = document.getElementById('prieres-search-input');
    if(el){ el.focus(); el.setSelectionRange(caret, caret); }
  };
}

