/* ================= journal (mon espace) ================= */
function journalCardHTML(entry){
  const d = new Date(entry.createdAt);
  const dateStr = d.toLocaleDateString('fr-FR', {day:'numeric', month:'long', year:'numeric'});
  return `<div class="card journal-card" data-id="${entry.id}">
    <p class="journal-date">${dateStr}</p>
    <p class="journal-text">${entry.text}</p>
    <div class="journal-actions"><button class="icon-btn" data-del="${entry.id}">🗑 Supprimer</button></div>
  </div>`;
}
function renderJournal(){
  let html = `<h2 class="section-title">✍️ Mon journal</h2>
    <p class="section-desc">Un espace privé pour écrire vos réflexions, prières ou intentions personnelles. Vous seul(e) pouvez le voir.</p>
    <div class="card add-intention-box">
      <textarea id="journal-text" rows="4" placeholder="Qu'avez-vous sur le cœur aujourd'hui ?"></textarea>
      <button class="btn btn-primary btn-sm" id="add-journal-btn">Ajouter à mon journal</button>
    </div>`;
  if(JOURNAL.length === 0){
    html += `<div class="card empty-state">Votre journal est vide pour l'instant.</div>`;
  } else {
    html += `<div class="grid">${JOURNAL.slice().sort((a,b)=>b.createdAt-a.createdAt).map(journalCardHTML).join('')}</div>`;
  }
  document.getElementById('screen').innerHTML = html;
  document.getElementById('add-journal-btn').onclick = async ()=>{
    const textEl = document.getElementById('journal-text');
    const text = textEl.value.trim();
    if(!text) { textEl.focus(); return; }
    JOURNAL.unshift({id:'j-'+Date.now(), text, createdAt:Date.now()});
    await saveJournal(JOURNAL);
    render();
  };
  document.querySelectorAll('[data-del]').forEach(btn=>{
    btn.onclick = async ()=>{
      JOURNAL = JOURNAL.filter(e=>e.id!==btn.dataset.del);
      await saveJournal(JOURNAL);
      render();
    };
  });
}

