/* ================= studio (ambient loops, mon espace) ================= */
let AUDIO_CTX = null;
let MASTER_GAIN = null;
let AUDIO_READY = false;
let LOOP_TIMER = null;
let CURRENT_LOOP = null;

function ensureAudio(){
  try{
    if(!AUDIO_CTX){
      const AC = window.AudioContext || window.webkitAudioContext;
      if(!AC){ showToast("Ce navigateur ne supporte pas l'audio Web Audio API"); return null; }
      AUDIO_CTX = new AC();
      MASTER_GAIN = AUDIO_CTX.createGain();
      MASTER_GAIN.gain.value = 0.9;
      MASTER_GAIN.connect(AUDIO_CTX.destination);
    }
    if(AUDIO_CTX.state === 'suspended'){
      AUDIO_CTX.resume().then(()=>{ AUDIO_READY = true; }).catch(()=>{
        showToast("Impossible d'activer le son — touchez à nouveau l'écran");
      });
    } else {
      AUDIO_READY = true;
    }
    return AUDIO_CTX;
  }catch(e){
    console.error('ensureAudio error', e);
    showToast("Erreur audio : " + (e.message||e));
    return null;
  }
}
function testSound(){
  const ctx = ensureAudio();
  if(!ctx) return;
  tone(ctx, 523.25, ctx.currentTime, 0.35, 'sine', 0.25);
  tone(ctx, 659.25, ctx.currentTime+0.12, 0.35, 'sine', 0.25);
  showToast('🔊 Si vous entendez deux notes, le son fonctionne !');
}
function tone(ctx, freq, t, dur, type, gain){
  const o = ctx.createOscillator(); const g = ctx.createGain();
  o.type = type || 'sine'; o.frequency.value = freq;
  g.gain.setValueAtTime(0, t);
  g.gain.linearRampToValueAtTime(gain||0.15, t+0.03);
  g.gain.exponentialRampToValueAtTime(0.0001, t+dur);
  o.connect(g); g.connect(MASTER_GAIN || ctx.destination);
  o.start(t); o.stop(t+dur+0.05);
}
function noiseHit(ctx, t, dur, gain, lp){
  const bufSize = Math.max(1, Math.floor(ctx.sampleRate*dur));
  const buffer = ctx.createBuffer(1, bufSize, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  for(let i=0;i<bufSize;i++) data[i] = (Math.random()*2-1) * (1 - i/bufSize);
  const src = ctx.createBufferSource(); src.buffer = buffer;
  const g = ctx.createGain(); g.gain.setValueAtTime(gain||0.2, t); g.gain.exponentialRampToValueAtTime(0.0001, t+dur);
  if(lp){ const f = ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value = lp; src.connect(f); f.connect(g); }
  else src.connect(g);
  g.connect(MASTER_GAIN || ctx.destination);
  src.start(t);
}
const LOOP_DEFS = {
  piano: {bar:2.0, fn:(ctx,t0)=>{ [261.6,329.6,392.0,523.3].forEach((f,i)=> tone(ctx,f,t0+i*0.5,0.9,'sine',0.12)); }},
  lofi: {bar:2.4, fn:(ctx,t0)=>{ [220,261.6,329.6].forEach((f,i)=> tone(ctx,f,t0+i*0.7,1.3,'triangle',0.08)); noiseHit(ctx,t0,2.2,0.02,4000); }},
  ambient: {bar:4.0, fn:(ctx,t0)=>{ tone(ctx,196,t0,3.8,'sine',0.09); tone(ctx,199,t0,3.8,'sine',0.07); tone(ctx,294,t0+0.4,3.2,'sine',0.06); }},
  basse: {bar:1.2, fn:(ctx,t0)=>{ tone(ctx,98,t0,0.5,'sine',0.18); tone(ctx,98,t0+0.6,0.4,'sine',0.14); }},
  tamtam: {bar:0.6, fn:(ctx,t0)=>{ noiseHit(ctx,t0,0.18,0.22,900); }},
  chorale: {bar:3.0, fn:(ctx,t0)=>{ [220,277.2,329.6].forEach(f=> tone(ctx,f,t0,2.8,'sine',0.07)); }},
  acapella: {bar:2.5, fn:(ctx,t0)=>{ tone(ctx,261.6,t0,2.3,'sine',0.13); }},
  rap: {bar:1.33, fn:(ctx,t0)=>{ noiseHit(ctx,t0,0.15,0.22,150); noiseHit(ctx,t0+0.66,0.06,0.1,6000); noiseHit(ctx,t0+1.0,0.06,0.1,6000); }},
  drill: {bar:0.857, fn:(ctx,t0)=>{ noiseHit(ctx,t0,0.12,0.2,150); noiseHit(ctx,t0+0.21,0.04,0.08,7000); noiseHit(ctx,t0+0.43,0.12,0.16,150); noiseHit(ctx,t0+0.64,0.04,0.08,7000); }},
  sabar: {bar:0.5, fn:(ctx,t0)=>{ noiseHit(ctx,t0,0.08,0.2,1200); noiseHit(ctx,t0+0.25,0.06,0.14,1600); }}
};
function stopLoop(){
  if(LOOP_TIMER){ clearInterval(LOOP_TIMER); LOOP_TIMER = null; }
  CURRENT_LOOP = null;
}
function startLoop(key){
  stopLoop();
  const ctx = ensureAudio();
  if(!ctx) return;
  const def = LOOP_DEFS[key];
  if(!def) return;
  CURRENT_LOOP = key;
  const playBar = ()=> def.fn(ctx, ctx.currentTime + 0.05);
  playBar();
  LOOP_TIMER = setInterval(playBar, def.bar*1000);
}
let LOUANGE_FILTER = 'Toutes';

