/* ================= favoris (étoile) ================= */
function favKey(f){
  if(!f) return '';
  if(f.type === 'novena') return 'novena|' + f.id;
  if(f.type === 'bible-chapter') return 'bible|' + f.code + '|' + f.chapter;
  if(f.type === 'office') return 'office|' + f.key;
  if(f.type === 'vreader-text') return 'vreader|' + (f.title||'') + '|' + (f.reference||f.subtitle||'');
  return 'entry|' + (f.compKey||'') + '|' + (f.groupId||'') + '|' + (f.idx!=null?f.idx:'');
}
const OFFICE_KEY_TO_SUB = {laudes:'laudes', tierce:'tierce', sexte:'sexte', none:'none', vepres:'vepres', complies:'compline', lectures:'lectures-office'};
function isFavorited(f){
  const key = favKey(f);
  return FAVORITES.some(x=>favKey(x)===key);
}
function favStarHTML(f){
  const active = isFavorited(f);
  return `<button type="button" class="fav-star ${active?'active':''}" data-fav='${JSON.stringify(f).replace(/'/g,"&apos;")}' title="${active?'Retirer des favoris':'Ajouter aux favoris'}">${active?'★':'☆'}</button>`;
}
function wireFavStars(){
  document.querySelectorAll('.fav-star').forEach(btn=>{
    btn.onclick = async (e)=>{
      e.stopPropagation();
      let f;
      try{ f = JSON.parse(btn.dataset.fav.replace(/&apos;/g,"'")); }catch(err){ return; }
      const key = favKey(f);
      const idx = FAVORITES.findIndex(x=>favKey(x)===key);
      if(idx >= 0){
        FAVORITES.splice(idx,1);
        btn.classList.remove('active'); btn.textContent = '☆'; btn.title = 'Ajouter aux favoris';
      } else {
        FAVORITES.unshift(f);
        btn.classList.add('active'); btn.textContent = '★'; btn.title = 'Retirer des favoris';
      }
      await savePrefs();
      if(PRIMARY === 'espace' && SUBTAB.espace === 'favoris') render();
    };
  });
}
function renderFavoris(){
  let html = `<h2 class="section-title">⭐ Mes favoris</h2>`;
  if(FAVORITES.length === 0){
    html += `<div class="card empty-state">Vous n'avez encore rien épinglé. L'étoile ☆ à côté d'un psaume, d'une prière ou d'un saint permet de le retrouver ici.</div>`;
  } else {
    html += `<div class="grid">${FAVORITES.map(f=>`
      <div class="card entry-card" data-fav-open='${JSON.stringify(f).replace(/'/g,"&apos;")}'>
        <div class="entry-avatar">${f.avatar||'⭐'}</div>
        <div class="entry-body">
          <p class="entry-name">${f.name}</p>
          <p class="entry-summary">${f.summary||''}</p>
        </div>
        ${favStarHTML(f)}
      </div>`).join('')}</div>`;
  }
  html += `<h2 class="section-title" style="margin-top:26px;">🕰️ Consultés récemment</h2>`;
  if(RECENT.length === 0){
    html += `<div class="card empty-state">Rien de récent pour l'instant.</div>`;
  } else {
    html += `<div class="grid">${RECENT.slice(0,12).map(f=>`
      <div class="card entry-card" data-fav-open='${JSON.stringify(f).replace(/'/g,"&apos;")}'>
        <div class="entry-avatar">${f.avatar||'📖'}</div>
        <div class="entry-body">
          <p class="entry-name">${f.name}</p>
          <p class="entry-summary">${f.summary||''}</p>
        </div>
      </div>`).join('')}</div>`;
  }
  document.getElementById('screen').innerHTML = html;
  wireFavStars();
  document.querySelectorAll('[data-fav-open]').forEach(c=>{
    c.onclick = (e)=>{
      if(e.target.closest('.fav-star')) return;
      const f = JSON.parse(c.dataset.favOpen.replace(/&apos;/g,"'"));
      if(f.type==='entry'){ PRIMARY = f.primary; SUBTAB[f.primary] = f.sub; GROUP_SEL[f.compKey] = f.groupId; ENTRY_OPEN = {compKey:f.compKey, groupId:f.groupId, idx:f.idx}; render(); }
      else if(f.type==='novena'){ goTo('prier','neuvaines'); OPEN_NOVENA = f.id; NOVENA_OPEN_DAY = null; NOVENA_FULLTEXT = false; NOVENA_DAY_DONE_SCREEN = null; render(); }
      else if(f.type==='bible-chapter'){ AELF_BIBLE_CURRENT = {code:f.code, name:f.name, chapter:f.chapter}; goTo('ecritures','aelf-bible-chapter'); }
      else if(f.type==='office'){ AELF_OFFICE_VIEW = f.key; AELF_OFFICE_TAB = 'texte'; goTo('prier', OFFICE_KEY_TO_SUB[f.key]||'laudes'); }
      else if(f.type==='vreader-text'){ openVerseReader({title:f.title, subtitle:f.subtitle, text:f.text, reference:f.reference}); }
    };
  });
}

function addToRecent(f){
  RECENT = RECENT.filter(x=>favKey(x)!==favKey(f));
  RECENT.unshift(f);
  RECENT = RECENT.slice(0,20);
  savePrefs();
}

