/* ================= streak ================= */
function todayISO(){ const d=new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
async function markPrayedToday(type, label){
  const t = todayISO();
  logActivity(type || 'priere', label || 'Prière');
  if(STREAK.lastDate === t){
    if(!PRAYED_DATES.includes(t)){ PRAYED_DATES.push(t); await savePrayedDates(PRAYED_DATES); }
    return;
  }
  const yest = new Date(); yest.setDate(yest.getDate()-1);
  const yestISO = yest.getFullYear()+'-'+String(yest.getMonth()+1).padStart(2,'0')+'-'+String(yest.getDate()).padStart(2,'0');
  STREAK.count = (STREAK.lastDate === yestISO) ? STREAK.count+1 : 1;
  STREAK.lastDate = t;
  if(!PRAYED_DATES.includes(t)) PRAYED_DATES.push(t);
  PRAYED_DATES = PRAYED_DATES.slice(-370);
  await savePrefs();
  await savePrayedDates(PRAYED_DATES);
  checkStreakMilestone();
  checkBadges();
}
function streakCardHTML(){
  const prayedToday = STREAK.lastDate === todayISO();
  let tier = 'spark';
  if(STREAK.count >= 100) tier = 'blaze';
  else if(STREAK.count >= 40) tier = 'strong';
  else if(STREAK.count >= 7) tier = 'steady';
  return `<div class="card streak-card">
    <div class="lumen-flame lumen-flame-${tier} ${STREAK.count>0?'lit':''}">
      <div class="lumen-flame-glow"></div>
      <div class="lumen-flame-body"></div>
      <div class="lumen-flame-core"></div>
    </div>
    <span class="streak-num">${STREAK.count}</span>
    <div class="streak-label">${STREAK.count>1?'jours de suite':'jour'}</div>
    <button class="btn ${prayedToday?'btn-ghost':'btn-primary'} btn-sm" id="prayed-today-btn" style="margin-top:10px;" ${prayedToday?'disabled':''}>${prayedToday?"Prié aujourd'hui ✓":"🕯️ J'ai prié aujourd'hui"}</button>
  </div>`;
}
function wireStreakButton(){
  const btn = document.getElementById('prayed-today-btn');
  if(btn) btn.onclick = async ()=>{ await markPrayedToday('priere', 'Prière'); render(); };
}

/* ================= text-to-speech & share ================= */
let BEST_FR_VOICE_CACHE = null;
function getBestFrenchVoice(){
  if(!window.speechSynthesis) return null;
  const voices = window.speechSynthesis.getVoices();
  if(!voices.length) return null;
  const frVoices = voices.filter(v=> v.lang && v.lang.toLowerCase().startsWith('fr'));
  if(!frVoices.length) return null;
  // préférence : voix "naturelles"/neurales connues avant les voix robotiques par défaut
  const preferredNames = ['Google français','Microsoft Denise','Microsoft Henri','Microsoft Vivienne','Audrey','Thomas','Amélie'];
  for(const name of preferredNames){
    const match = frVoices.find(v=> v.name.includes(name));
    if(match) return match;
  }
  // sinon, une voix non locale (souvent plus naturelle que les voix embarquées "compact")
  const nonLocal = frVoices.find(v=> !v.localService);
  return nonLocal || frVoices[0];
}
function applyNaturalVoice(u){
  const voice = getBestFrenchVoice();
  if(voice) u.voice = voice;
  u.lang = 'fr-FR';
  u.rate = 0.96;
  u.pitch = 1.03;
}
if(window.speechSynthesis){
  window.speechSynthesis.onvoiceschanged = ()=>{ BEST_FR_VOICE_CACHE = getBestFrenchVoice(); };
}
function speakText(text){
  try{
    if(!window.speechSynthesis){ showToast("Lecture vocale indisponible sur ce navigateur"); return; }
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    applyNaturalVoice(u);
    window.speechSynthesis.speak(u);
  }catch(e){ showToast("Lecture vocale indisponible"); }
}

/* ================= lecture vocale de la page entière ================= */
let READING_PAGE = false;
function extractScreenText(){
  const screen = document.getElementById('screen');
  if(!screen) return '';
  const clone = screen.cloneNode(true);
  clone.querySelectorAll('button, input, select, textarea, .chip-row, .subnav-row, iframe, audio, .loop-grid, .seq-transport, .preset-row').forEach(el=> el.remove());
  return clone.innerText.replace(/\s+/g,' ').trim();
}
function toggleReadPage(){
  const btn = document.getElementById('read-page-btn');
  if(!window.speechSynthesis){ showToast("Lecture vocale indisponible sur ce navigateur"); return; }
  if(READING_PAGE){
    window.speechSynthesis.cancel();
    READING_PAGE = false;
    if(btn){ const ic=btn.querySelector('.tool-btn-icon'); if(ic) ic.textContent='🔊'; else btn.textContent='🔊'; btn.classList.remove('tool-active'); }
    return;
  }
  const text = extractScreenText();
  if(!text){ showToast("Rien à lire sur cet écran"); return; }
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text.slice(0, 6000));
  applyNaturalVoice(u);
  u.onend = ()=>{ READING_PAGE = false; if(btn){ const ic=btn.querySelector('.tool-btn-icon'); if(ic) ic.textContent='🔊'; else btn.textContent='🔊'; btn.classList.remove('tool-active'); } };
  u.onerror = u.onend;
  window.speechSynthesis.speak(u);
  READING_PAGE = true;
  if(btn){ const ic=btn.querySelector('.tool-btn-icon'); if(ic) ic.textContent='⏹'; else btn.textContent='⏹'; btn.classList.add('tool-active'); }
  showToast('🔊 Lecture de la page…');
}

/* ================= ambiance sonore de fond =================
   La vidéo YouTube ne joue plus dans un cadre intégré (iframe/API JS) à
   l'intérieur de l'appli : ces lecteurs intégrés se heurtaient sans arrêt
   aux politiques anti-autoplay des navigateurs (« ça charge mais le son
   ne vient pas »). La musique s'ouvre maintenant directement sur la vraie
   page YouTube, dans une fenêtre à part (une popup dédiée, pas un nouvel
   onglet plein écran) : c'est youtube.com lui-même qui joue le son, donc
   plus aucun blocage possible. Le petit cadre flottant dans l'appli ne
   sert plus qu'à garder trace du titre en cours et à passer au suivant. */
let BG_YT_VIDEO_ID = null;
let BG_SPOTIFY_ACTIVE = false;
let AMBIANCE_SHUFFLE_MODE = false;
let AMBIANCE_SHUFFLE_LAST = null;
let AMBIANCE_VIDEO_OPEN = false;
let AMBIANCE_VIDEO_LABEL = '';
let AMBIANCE_CURRENT_POOL = null;
let AMBIANCE_YT_WINDOW = null;
function openAmbianceYoutubeWindow(videoId){
  const url = 'https://www.youtube.com/watch?v=' + encodeURIComponent(videoId) + '&autoplay=1';
  try{
    if(AMBIANCE_YT_WINDOW && !AMBIANCE_YT_WINDOW.closed){
      AMBIANCE_YT_WINDOW.location.href = url;
      try{ AMBIANCE_YT_WINDOW.focus(); }catch(e){}
      return;
    }
    AMBIANCE_YT_WINDOW = window.open(url, 'lumen_ambiance_yt', 'width=420,height=760,noopener,noreferrer');
    if(AMBIANCE_YT_WINDOW){ try{ AMBIANCE_YT_WINDOW.focus(); }catch(e){} }
  }catch(err){ AMBIANCE_YT_WINDOW = null; }
  if(!AMBIANCE_YT_WINDOW){
    showToast('🎵 Les fenêtres pop-up semblent bloquées — autorisez-les pour ce site, ou touchez « Ouvrir sur YouTube » dans le cadre.');
  }
}
function destroyAmbianceYoutubePlayer(){
  if(AMBIANCE_YT_WINDOW && !AMBIANCE_YT_WINDOW.closed){
    try{ AMBIANCE_YT_WINDOW.close(); }catch(err){}
  }
  AMBIANCE_YT_WINDOW = null;
}
function isBgAmbiancePlaying(){ return !!CURRENT_LOOP || !!BG_YT_VIDEO_ID || BG_SPOTIFY_ACTIVE; }
function syncBgAmbianceIcon(){
  const btn = document.getElementById('bg-ambiance-btn');
  if(btn) btn.classList.toggle('tool-active', isBgAmbiancePlaying());
}
function stopAllAmbiance(){
  stopLoop();
  destroyAmbianceYoutubePlayer();
  AMBIANCE_CURRENT_POOL = null;
  BG_YT_VIDEO_ID = null;
  BG_SPOTIFY_ACTIVE = false;
  AMBIANCE_SHUFFLE_MODE = false;
  AMBIANCE_VIDEO_OPEN = false;
  const host = document.getElementById('ambiance-player-overlay');
  if(host){ host.classList.add('hidden'); host.innerHTML = ''; }
  renderLumenPlayer();
  syncBgAmbianceIcon();
}
let LUMEN_PLAYER_STATE = {active:false, label:'', kind:null, paused:false};
function lumenPlayerShow(label, kind){
  LUMEN_PLAYER_STATE = {active:true, label, kind, paused:false};
  renderLumenPlayer();
}
function lumenPlayerHide(){
  LUMEN_PLAYER_STATE = {active:false, label:'', kind:null, paused:false};
  renderLumenPlayer();
}
/* La petite barre persistante ne sert plus qu'au fond sonore local en boucle
   (pluie, chant...), qui continue réellement pendant la navigation. Pour la
   vidéo YouTube et Spotify, la fenêtre elle-même (ambiance-player-overlay)
   est l'unique interface, comme avant : pas de miniature à repositionner. */
function renderLumenPlayer(){
  const bar = document.getElementById('lumen-player-bar');
  if(!bar) return;
  if(!LUMEN_PLAYER_STATE.active || LUMEN_PLAYER_STATE.kind !== 'loop'){ bar.classList.add('hidden'); return; }
  bar.classList.remove('hidden');
  bar.innerHTML = `
    <div class="lumen-player-handle" id="lumen-player-handle"></div>
    <div class="lumen-player-row">
      <span class="lumen-player-icon">${LUMEN_PLAYER_STATE.paused ? '⏸' : '🎵'}</span>
      <span class="lumen-player-label">${LUMEN_PLAYER_STATE.label}</span>
      <button class="icon-btn" id="lumen-player-toggle" title="${LUMEN_PLAYER_STATE.paused?'Reprendre':'Pause'}">${LUMEN_PLAYER_STATE.paused?'▶':'⏸'}</button>
      <button class="icon-btn" id="lumen-player-close" title="Arrêter">✕</button>
    </div>
  `;
  wireLumenPlayer();
}
function wireLumenPlayer(){
  const toggleBtn = document.getElementById('lumen-player-toggle');
  if(toggleBtn) toggleBtn.onclick = ()=>{
    LUMEN_PLAYER_STATE.paused = !LUMEN_PLAYER_STATE.paused;
    if(LUMEN_PLAYER_STATE.paused && LOOP_TIMER){ clearInterval(LOOP_TIMER); LOOP_TIMER = null; }
    else if(!LUMEN_PLAYER_STATE.paused && CURRENT_LOOP){ startLoop(CURRENT_LOOP); LUMEN_PLAYER_STATE.paused=false; }
    renderLumenPlayer();
  };
  const closeBtn = document.getElementById('lumen-player-close');
  if(closeBtn) closeBtn.onclick = ()=>{ stopAllAmbiance(); lumenPlayerHide(); };
  const handle = document.getElementById('lumen-player-handle');
  const bar = document.getElementById('lumen-player-bar');
  if(handle && bar){
    let dragging = false, startY = 0, startBottom = 0;
    const onDown = (e)=>{
      dragging = true;
      startY = (e.touches?e.touches[0].clientY:e.clientY);
      startBottom = parseInt(getComputedStyle(bar).bottom, 10) || 0;
      bar.style.transition = 'none';
    };
    const onMove = (e)=>{
      if(!dragging) return;
      const y = (e.touches?e.touches[0].clientY:e.clientY);
      const delta = startY - y;
      let newBottom = Math.max(70, Math.min(window.innerHeight - 80, startBottom + delta));
      bar.style.bottom = newBottom + 'px';
    };
    const onUp = ()=>{ dragging = false; bar.style.transition = ''; };
    handle.addEventListener('mousedown', onDown);
    handle.addEventListener('touchstart', onDown, {passive:true});
    window.addEventListener('mousemove', onMove);
    window.addEventListener('touchmove', onMove, {passive:true});
    window.addEventListener('mouseup', onUp);
    window.addEventListener('touchend', onUp);
  }
}
/* La fenêtre qui affiche directement la vidéo YouTube (ou l'intégration
   Spotify). Un <iframe> standard avec ses propres contrôles natifs — fermer
   la fenêtre (✕ ou « Arrêter ») coupe le son en retirant le cadre. */
function renderAmbianceVideoWindow(){
  const host = document.getElementById('ambiance-player-overlay');
  if(!host) return;
  if(!AMBIANCE_VIDEO_OPEN){ destroyAmbianceYoutubePlayer(); host.classList.add('hidden'); host.innerHTML = ''; return; }
  host.classList.remove('hidden');
  if(BG_SPOTIFY_ACTIVE){
    destroyAmbianceYoutubePlayer();
    host.innerHTML = `
      <div class="ambiance-player-panel">
        <div class="ambiance-player-top" id="ambiance-player-drag">
          <span class="ambiance-player-drag-hint" aria-hidden="true">⠿</span>
          <p class="ambiance-player-title">🟢 Spotify</p>
          <button class="icon-btn" id="ambiance-player-back" aria-label="Fermer">✕</button>
        </div>
        <p class="ambiance-player-label">${AMBIANCE_VIDEO_LABEL}</p>
        <div class="ambiance-player-embed"><iframe src="${BG_SPOTIFY_ACTIVE}" style="width:100%; height:100%; border:none; border-radius:10px;" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe></div>
        <div class="ambiance-player-controls"><button class="btn btn-ghost btn-sm" id="ambiance-player-stop">⏹ Fermer</button></div>
      </div>`;
  } else if(BG_YT_VIDEO_ID){
    host.innerHTML = `
      <div class="ambiance-player-panel">
        <div class="ambiance-player-top" id="ambiance-player-drag">
          <span class="ambiance-player-drag-hint" aria-hidden="true">⠿</span>
          <p class="ambiance-player-title">🎵 Ambiance</p>
          <button class="icon-btn" id="ambiance-player-back" aria-label="Fermer">✕</button>
        </div>
        <p class="ambiance-player-label">${AMBIANCE_VIDEO_LABEL}</p>
        <p class="studio-note" style="text-align:center;">🔊 Le son joue dans une fenêtre YouTube séparée.</p>
        <div class="ambiance-player-controls">
          <button class="btn btn-gold btn-sm" id="ambiance-player-reopen">↗ Rouvrir la fenêtre</button>
          ${(AMBIANCE_SHUFFLE_MODE || AMBIANCE_CURRENT_POOL) ? `<button class="btn btn-ghost btn-sm" id="ambiance-player-next">⏭ Suivant</button>` : ''}
          <button class="btn btn-ghost btn-sm" id="ambiance-player-stop">⏹ Arrêter</button>
        </div>
      </div>`;
  }
  const backBtn = document.getElementById('ambiance-player-back');
  if(backBtn) backBtn.onclick = ()=>{ stopAllAmbiance(); };
  const reopenBtn = document.getElementById('ambiance-player-reopen');
  if(reopenBtn) reopenBtn.onclick = ()=>{ if(BG_YT_VIDEO_ID) openAmbianceYoutubeWindow(BG_YT_VIDEO_ID); };
  const nextBtn = document.getElementById('ambiance-player-next');
  if(nextBtn) nextBtn.onclick = ()=>{
    if(AMBIANCE_SHUFFLE_MODE) playRandomAmbiance(true);
    else if(AMBIANCE_CURRENT_POOL && AMBIANCE_CURRENT_POOL.length){
      const pool = AMBIANCE_CURRENT_POOL;
      let pick, tries=0;
      do { pick = pool[Math.floor(Math.random()*pool.length)]; tries++; }
      while(pick.videoId === BG_YT_VIDEO_ID && tries < 10 && pool.length > 1);
      playBgYoutube(pick.videoId, pick.title + ' — ' + pick.artist, {pool});
    }
  };
  const stopBtn = document.getElementById('ambiance-player-stop');
  if(stopBtn) stopBtn.onclick = ()=>{ stopAllAmbiance(); showToast('Ambiance arrêtée'); };
  wireAmbianceFloatDrag();
}
/* Fenêtre flottante déplaçable : on saisit la petite poignée ⠿ en haut du
   cadre pour la glisser n'importe où sur l'écran plutôt que de rester bloqué
   au centre — l'appli reste utilisable et navigable pendant ce temps, puisque
   ce n'est plus une fenêtre modale plein écran. */
function wireAmbianceFloatDrag(){
  const host = document.getElementById('ambiance-player-overlay');
  const handle = document.getElementById('ambiance-player-drag');
  if(!host || !handle || handle.dataset.dragWired) return;
  handle.dataset.dragWired = '1';
  let dragging = false, startX = 0, startY = 0, startLeft = 0, startTop = 0;
  const onDown = (e)=>{
    if(e.target.closest('.icon-btn')) return;
    dragging = true;
    const pt = e.touches ? e.touches[0] : e;
    startX = pt.clientX; startY = pt.clientY;
    const rect = host.getBoundingClientRect();
    startLeft = rect.left; startTop = rect.top;
    host.style.right = 'auto'; host.style.bottom = 'auto';
    host.style.left = startLeft + 'px'; host.style.top = startTop + 'px';
  };
  const onMove = (e)=>{
    if(!dragging) return;
    const pt = e.touches ? e.touches[0] : e;
    const dx = pt.clientX - startX, dy = pt.clientY - startY;
    const w = host.offsetWidth, h = host.offsetHeight;
    let newLeft = Math.max(6, Math.min(window.innerWidth - w - 6, startLeft + dx));
    let newTop = Math.max(6, Math.min(window.innerHeight - h - 6, startTop + dy));
    host.style.left = newLeft + 'px';
    host.style.top = newTop + 'px';
  };
  const onUp = ()=>{ dragging = false; };
  handle.addEventListener('mousedown', onDown);
  handle.addEventListener('touchstart', onDown, {passive:true});
  window.addEventListener('mousemove', onMove);
  window.addEventListener('touchmove', onMove, {passive:true});
  window.addEventListener('mouseup', onUp);
  window.addEventListener('touchend', onUp);
}
function playBgYoutube(videoId, label, opts){
  opts = opts || {};
  stopLoop();
  AMBIANCE_SHUFFLE_MODE = false;
  AMBIANCE_CURRENT_POOL = opts.pool || null;
  BG_YT_VIDEO_ID = videoId;
  BG_SPOTIFY_ACTIVE = false;
  AMBIANCE_VIDEO_OPEN = true;
  AMBIANCE_VIDEO_LABEL = label;
  lumenPlayerHide();
  renderAmbianceVideoWindow();
  syncBgAmbianceIcon();
  openAmbianceYoutubeWindow(videoId);
  if(!opts.silent) showToast('🎵 ' + label + '…');
}
function pickRandomAmbianceTrack(){
  if(!LOUANGES_VIDEOS.length) return null;
  if(LOUANGES_VIDEOS.length === 1) return LOUANGES_VIDEOS[0];
  let pick;
  do { pick = LOUANGES_VIDEOS[Math.floor(Math.random()*LOUANGES_VIDEOS.length)]; }
  while(AMBIANCE_SHUFFLE_LAST && pick.videoId === AMBIANCE_SHUFFLE_LAST.videoId);
  return pick;
}
function playRandomAmbiance(isAutoAdvance){
  const pick = pickRandomAmbianceTrack();
  if(!pick) return;
  AMBIANCE_SHUFFLE_LAST = pick;
  stopLoop();
  AMBIANCE_CURRENT_POOL = LOUANGES_VIDEOS;
  BG_SPOTIFY_ACTIVE = false;
  BG_YT_VIDEO_ID = pick.videoId;
  AMBIANCE_VIDEO_OPEN = true;
  AMBIANCE_VIDEO_LABEL = '🔀 ' + pick.title + ' — ' + pick.artist;
  lumenPlayerHide();
  renderAmbianceVideoWindow();
  syncBgAmbianceIcon();
  openAmbianceYoutubeWindow(pick.videoId);
  if(!isAutoAdvance) showToast('🔀 Lecture aléatoire — touchez « Titre suivant » pour changer de morceau.');
}
function startAmbianceShuffle(){
  AMBIANCE_SHUFFLE_MODE = true;
  playRandomAmbiance(false);
}
function playBgSpotify(spotifyArtistId, label){
  stopLoop();
  AMBIANCE_SHUFFLE_MODE = false;
  BG_YT_VIDEO_ID = null;
  BG_SPOTIFY_ACTIVE = `https://open.spotify.com/embed/artist/${spotifyArtistId}?utm_source=generator&theme=0`;
  AMBIANCE_VIDEO_OPEN = true;
  AMBIANCE_VIDEO_LABEL = label;
  lumenPlayerHide();
  renderAmbianceVideoWindow();
  syncBgAmbianceIcon();
}
function playBgLoop(key, label){
  destroyAmbianceYoutubePlayer();
  BG_YT_VIDEO_ID = null;
  BG_SPOTIFY_ACTIVE = false;
  AMBIANCE_VIDEO_OPEN = false;
  const host = document.getElementById('ambiance-player-overlay');
  if(host){ host.classList.add('hidden'); host.innerHTML = ''; }
  startLoop(key);
  lumenPlayerShow('🎵 ' + label, 'loop');
  syncBgAmbianceIcon();
  showToast('🎵 ' + label + ' — continue en fond pendant la navigation');
}
function toggleBgAmbiance(){
  openAmbiancePicker();
}
const ARTIST_COLORS = ['#7C1F2E','#B8863B','#3F6B2E','#1F6F8B','#8A4B8A','#B85C10','#4E6E7A','#A9556A','#5C6E45','#E07A1F'];
function artistInitial(name){ return name.trim()[0].toUpperCase(); }
const SPOTIFY_ARTIST_IDS = {
  'KS Bloom': '0iSX5EqjPdp2xkU7fgw7bp',
  'David Okit': '2TNEke8iPCbFBj8Tp9KlnJ',
  'Dena Mwana': '3hI9YP4rI93GyoPk5E9zT3'
};
function artistColor(name){
  let hash = 0;
  for(let i=0;i<name.length;i++) hash = name.charCodeAt(i) + ((hash<<5)-hash);
  return ARTIST_COLORS[Math.abs(hash) % ARTIST_COLORS.length];
}
let AMBIANCE_SEARCH = '';
let AMBIANCE_TAG_FILTER = '';
function renderAmbianceList(){
  const list = document.getElementById('ambiance-picker-list');
  const q = AMBIANCE_SEARCH.trim().toLowerCase();
  const tagFilter = AMBIANCE_TAG_FILTER;
  let filtered = !q ? LOUANGES_VIDEOS : LOUANGES_VIDEOS.filter(v =>
    v.title.toLowerCase().includes(q) || v.artist.toLowerCase().includes(q) || v.tag.toLowerCase().includes(q));
  if(tagFilter) filtered = filtered.filter(v => v.tag === tagFilter);

  const allTags = [...new Set(LOUANGES_VIDEOS.map(v=>v.tag))].sort();
  const tagChipsHTML = `<div class="chip-row" style="margin-bottom:10px;">
    <button class="chip ${!tagFilter?'active':''}" data-tag="">Tous (${LOUANGES_VIDEOS.length})</button>
    ${allTags.map(t=>`<button class="chip ${tagFilter===t?'active':''}" data-tag="${t}">${t} (${LOUANGES_VIDEOS.filter(v=>v.tag===t).length})</button>`).join('')}
  </div>`;

  const byArtist = {};
  filtered.forEach(v => { (byArtist[v.artist] = byArtist[v.artist] || []).push(v); });
  const artistNames = Object.keys(byArtist).sort();

  const heroPick = LOUANGES_VIDEOS[Math.floor(Math.random()*LOUANGES_VIDEOS.length)];
  const heroHTML = (!q && !tagFilter) ? `
    <div class="ambiance-hero" style="background:linear-gradient(135deg, ${artistColor(heroPick.artist)}, var(--wine-dark));">
      <p class="ambiance-hero-eyebrow">✨ Suggestion du moment</p>
      <p class="ambiance-hero-title">${heroPick.title}</p>
      <p class="ambiance-hero-artist">${heroPick.artist}</p>
      <button class="btn btn-gold btn-sm" id="ambiance-hero-play">▶️ Écouter</button>
    </div>` : '';

  const artistHTML = artistNames.length ? `
    <p class="eyebrow" style="color:var(--gold); margin:14px 0 6px;">🎶 ${filtered.length} morceau${filtered.length>1?'x':''}${(q||tagFilter)?' trouvé'+(filtered.length>1?'s':''):', par artiste'}</p>
    <div class="artist-groups">${artistNames.map(artist => `
      <div class="artist-group" style="border-left:4px solid ${artistColor(artist)};">
        <div class="artist-group-header">
          <span class="artist-avatar" style="background:${artistColor(artist)};">${artistInitial(artist)}</span>
          <span class="artist-group-name">${artist}</span>
          <span class="artist-group-count">${byArtist[artist].length}</span>
          ${SPOTIFY_ARTIST_IDS[artist]
            ? `<button class="spotify-link-btn" data-spotify-artist="${SPOTIFY_ARTIST_IDS[artist]}" data-spotify-label="${artist.replace(/"/g,'&quot;')}" title="Écouter ${artist} sur Spotify">🟢</button>`
            : `<a class="spotify-link-btn" href="https://open.spotify.com/search/${encodeURIComponent(artist)}" target="_blank" rel="noopener" title="Chercher ${artist} sur Spotify">🟢</a>`
          }
        </div>
        <div class="artist-tracks">${byArtist[artist].map(v => `
          <div class="track-row" data-yt-id="${v.videoId}" data-yt-label="${v.title.replace(/"/g,'&quot;')}">
            <span class="track-play-icon">${BG_YT_VIDEO_ID===v.videoId?'🔊':'▶️'}</span>
            <div class="track-info"><p class="track-title">${v.title}</p><p class="track-tag">${v.tag}</p></div>
          </div>`).join('')}
        </div>
      </div>`).join('')}
    </div>` : `<p class="section-desc">Aucun résultat.</p>`;

  const spotifySearchHTML = `<div class="card" style="margin-top:14px;">
    <p class="eyebrow" style="color:#1DB954;">🟢 Chercher n'importe quoi sur Spotify</p>
    <p class="studio-note" style="margin:4px 0 8px;">Tape un artiste ou un titre — ça ouvre Spotify directement (hors de l'application).</p>
    <div style="display:flex; gap:8px;">
      <input type="text" id="spotify-free-search" placeholder="Ex. Moïse Mbiye, un titre précis...">
      <button class="btn btn-gold btn-sm" id="spotify-free-search-btn" style="flex-shrink:0;">🔍 Ouvrir</button>
    </div>
  </div>`;

  const synthHTML = `<details class="synth-collapse">
    <summary>🎧 Sons générés (boucles douces)</summary>
    <div class="loop-grid" style="margin-top:10px;">${STUDIO_LOOPS.map(l=>
      `<button class="loop-btn ${CURRENT_LOOP===l.key?'playing':''}" data-loop-key="${l.key}" data-loop-label="${l.label}">${l.label}${CURRENT_LOOP===l.key?'<span class="eq-bars"><span></span><span></span><span></span></span>':''}</button>`
    ).join('')}</div>
  </details>`;

  const stopHTML = `<div style="display:flex; gap:8px; justify-content:center; margin-top:14px; flex-wrap:wrap;">
    <button class="btn btn-gold btn-sm" id="ambiance-shuffle-btn">${AMBIANCE_SHUFFLE_MODE ? '🔀 Aléatoire en cours…' : '🔀 Lecture aléatoire'}</button>
    <button class="btn btn-ghost btn-sm" id="ambiance-stop-all-btn">⏹ Tout arrêter</button>
  </div>
  ${AMBIANCE_SHUFFLE_MODE ? `<p class="studio-note" style="text-align:center; margin-top:6px;">La musique enchaîne toute seule un morceau au hasard après l'autre. Arrêtez à tout moment avec ✕ dans le petit lecteur.</p>` : ''}`;

  list.innerHTML = `
    <div class="ambiance-search-wrap">
      <input type="text" id="ambiance-search-input" placeholder="🔍 Chercher un artiste, un titre..." value="${AMBIANCE_SEARCH.replace(/"/g,'&quot;')}">
    </div>
    ${tagChipsHTML}
    ${heroHTML}${artistHTML}${spotifySearchHTML}${synthHTML}${stopHTML}
  `;

  document.getElementById('ambiance-search-input').oninput = (e)=>{
    AMBIANCE_SEARCH = e.target.value;
    const caret = e.target.selectionStart;
    renderAmbianceList();
    const el = document.getElementById('ambiance-search-input');
    el.focus(); el.setSelectionRange(caret, caret);
  };
  list.querySelectorAll('[data-tag]').forEach(chip=>{
    chip.onclick = ()=>{ AMBIANCE_TAG_FILTER = chip.dataset.tag; renderAmbianceList(); };
  });
  list.querySelectorAll('[data-spotify-artist]').forEach(btn=>{
    btn.onclick = ()=>{ playBgSpotify(btn.dataset.spotifyArtist, btn.dataset.spotifyLabel); closeAmbiancePicker(); };
  });
  document.getElementById('spotify-free-search-btn').onclick = ()=>{
    const q = document.getElementById('spotify-free-search').value.trim();
    if(!q) return;
    window.open('https://open.spotify.com/search/' + encodeURIComponent(q), '_blank');
  };
  const heroBtn = document.getElementById('ambiance-hero-play');
  if(heroBtn) heroBtn.onclick = ()=>{ playBgYoutube(heroPick.videoId, heroPick.title + ' — ' + heroPick.artist, {pool: LOUANGES_VIDEOS}); closeAmbiancePicker(); };
  list.querySelectorAll('[data-loop-key]').forEach(btn=>{
    btn.onclick = ()=>{ playBgLoop(btn.dataset.loopKey, btn.dataset.loopLabel); closeAmbiancePicker(); };
  });
  list.querySelectorAll('[data-yt-id]').forEach(el=>{
    el.onclick = ()=>{ playBgYoutube(el.dataset.ytId, el.dataset.ytLabel, {pool: LOUANGES_VIDEOS}); closeAmbiancePicker(); };
  });
  document.getElementById('ambiance-shuffle-btn').onclick = ()=>{
    if(AMBIANCE_SHUFFLE_MODE){ stopAllAmbiance(); lumenPlayerHide(); showToast('Lecture aléatoire arrêtée'); renderAmbianceList(); return; }
    startAmbianceShuffle();
    closeAmbiancePicker();
  };
  document.getElementById('ambiance-stop-all-btn').onclick = ()=>{ stopAllAmbiance(); showToast('Ambiance arrêtée'); closeAmbiancePicker(); };
}
function openAmbiancePicker(){
  const overlay = document.getElementById('ambiance-picker-overlay');
  const titleEl = overlay.querySelector('.search-input-row p');
  const descEl = document.getElementById('ambiance-picker-desc');
  if(titleEl) titleEl.textContent = '🎵 Ambiance de fond';
  if(descEl) descEl.textContent = "Choisissez un son qui continuera de jouer pendant que vous naviguez dans l'application.";
  AMBIANCE_SEARCH = '';
  renderAmbianceList();

  document.getElementById('ambiance-picker-overlay').classList.remove('hidden');
}
function closeAmbiancePicker(){
  document.getElementById('ambiance-picker-overlay').classList.add('hidden');
}

/* ================= lecteur vidéo intégré, réutilisable partout ================= */
function openVideoModal(videoId, title, caption){
  document.getElementById('video-modal-title').textContent = title || 'Vidéo';
  document.getElementById('video-modal-caption').textContent = caption || '';
  document.getElementById('video-modal-body').innerHTML =
    `<iframe src="https://www.youtube.com/embed/${videoId}?autoplay=1" style="width:100%; height:100%; border:none;" allow="autoplay; encrypted-media; fullscreen" allowfullscreen title="${(title||'').replace(/"/g,'&quot;')}"></iframe>`;
  document.getElementById('video-modal-overlay').classList.remove('hidden');
}
function closeVideoModal(){
  document.getElementById('video-modal-overlay').classList.add('hidden');
  document.getElementById('video-modal-body').innerHTML = '';
}
/* extrait un ID YouTube depuis une URL classique, pour convertir les liens externes existants */
function extractYoutubeId(url){
  if(!url) return null;
  const m = url.match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([\w-]{11})/);
  return m ? m[1] : null;
}
function wireVideoLinks(){
  document.querySelectorAll('[data-video-id]').forEach(el=>{
    el.onclick = (e)=>{
      e.preventDefault();
      openVideoModal(el.dataset.videoId, el.dataset.videoTitle || '', el.dataset.videoCaption || '');
    };
  });
}

async function shareText(title, text){
  try{
    if(navigator.share){ await navigator.share({title, text}); return; }
  }catch(e){}
  try{ await navigator.clipboard.writeText(title+'\n\n'+text); showToast('Copié dans le presse-papiers 📋'); }
  catch(e){ showToast("Impossible de copier"); }
}
function wrapCanvasText(ctx, text, x, y, maxWidth, lineHeight){
  const words = text.split(' ');
  let line = '';
  let curY = y;
  const lines = [];
  words.forEach(word=>{
    const test = line + word + ' ';
    if(ctx.measureText(test).width > maxWidth && line !== ''){
      lines.push(line); line = word + ' ';
    } else { line = test; }
  });
  lines.push(line);
  lines.forEach(l=>{ ctx.fillText(l.trim(), x, curY); curY += lineHeight; });
  return curY;
}
function generateShareImage(title, text){
  const canvas = document.createElement('canvas');
  canvas.width = 800; canvas.height = 800;
  const ctx = canvas.getContext('2d');
  const styles = getComputedStyle(document.body);
  const wine = styles.getPropertyValue('--wine-dark').trim() || '#5E1622';
  const wine2 = styles.getPropertyValue('--wine').trim() || '#7C1F2E';
  const gold = styles.getPropertyValue('--gold-light').trim() || '#E4C77E';
  const cream = styles.getPropertyValue('--vellum-light').trim() || '#FBF7EC';

  const grad = ctx.createLinearGradient(0,0,800,800);
  grad.addColorStop(0, wine); grad.addColorStop(1, wine2);
  ctx.fillStyle = grad; ctx.fillRect(0,0,800,800);

  // double decorative border
  ctx.strokeStyle = gold; ctx.lineWidth = 2;
  ctx.strokeRect(26,26,748,748);
  ctx.globalAlpha = 0.5;
  ctx.strokeRect(38,38,724,724);
  ctx.globalAlpha = 1;

  // corner flourishes
  ctx.fillStyle = gold; ctx.font = '22px Georgia, serif';
  ctx.fillText('✦', 55, 68); ctx.fillText('✦', 745, 68);
  ctx.fillText('✦', 55, 748); ctx.fillText('✦', 745, 748);

  // flame emblem
  ctx.beginPath();
  ctx.fillStyle = gold;
  ctx.moveTo(400,110); ctx.quadraticCurveTo(370,160,400,200); ctx.quadraticCurveTo(430,160,400,110);
  ctx.fill();

  ctx.fillStyle = cream; ctx.font = 'italic 30px Georgia, serif'; ctx.textAlign = 'center';
  wrapCanvasText(ctx, '« '+text+' »', 400, 300, 620, 42);
  ctx.fillStyle = gold; ctx.font = 'bold 22px Georgia, serif';
  ctx.fillText('— ' + title, 400, 680);
  ctx.fillStyle = cream; ctx.globalAlpha = 0.6; ctx.font = '16px Arial, sans-serif';
  ctx.fillText('✦ Lumen — prier chaque jour ✦', 400, 750);
  ctx.globalAlpha = 1;
  return canvas;
}
function openShareImage(title, text){
  const canvas = generateShareImage(title, text);
  const overlay = document.getElementById('share-image-overlay');
  const holder = document.getElementById('share-canvas-holder');
  holder.innerHTML = '';
  canvas.id = 'share-canvas';
  holder.appendChild(canvas);
  overlay.classList.remove('hidden');
  document.getElementById('download-image-btn').onclick = ()=>{
    canvas.toBlob(blob=>{
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = 'lumen-'+todayISO()+'.png';
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      URL.revokeObjectURL(url);
    });
  };
}
/* Rangée d'actions unifiée pour tout texte affiché dans l'app : on ne garde
   que ce qui est vraiment utile (le lecteur plein écran couvre déjà l'écoute,
   l'image et le partage internes ; inutile de dupliquer imprimer/copier). */
function textActionsRowHTML(theme, title, subtitle, text, reference, images){
  const safeText = text.replace(/'/g,"&apos;").replace(/"/g,"&quot;");
  const safeTitle = (title||'').replace(/'/g,"&apos;").replace(/"/g,"&quot;");
  const safeSub = (subtitle||'').replace(/'/g,"&apos;").replace(/"/g,"&quot;");
  const safeRef = (reference||'').replace(/'/g,"&apos;").replace(/"/g,"&quot;");
  const imgsAttr = images && images.length ? images.join(',').replace(/"/g,'&quot;') : '';
  return `<div class="entry-link-row" style="gap:8px; flex-wrap:wrap;">
    <button class="btn btn-ghost btn-sm tdisplay-btn" data-theme="${theme||'candle'}" data-title="${safeTitle}" data-subtitle="${safeSub}" data-text="${safeText}" data-reference="${safeRef}" data-images="${imgsAttr}">🎨 Modes d'affichage</button>
    <button class="btn btn-ghost btn-sm treading-btn">🕯️ Mode lecture</button>
    <button class="btn btn-ghost btn-sm share-btn" data-title="${safeTitle}" data-text="${safeText}">📤 Partager</button>
  </div>`;
}
function speakShareRowHTML(title, text){ return textActionsRowHTML('candle', title, '', text, ''); }
function wireSpeakShare(){
  document.querySelectorAll('.speak-btn').forEach(b=> b.onclick = ()=> speakText(b.dataset.text));
  document.querySelectorAll('.share-btn').forEach(b=> b.onclick = ()=> shareText(b.dataset.title, b.dataset.text));
  document.querySelectorAll('.treading-btn').forEach(b=> b.onclick = enableReadingMode);
  document.querySelectorAll('.tdisplay-btn').forEach(b=>{
    b.onclick = ()=>{
      const theme = b.dataset.theme || 'candle';
      const title = b.dataset.title || '';
      const subtitle = b.dataset.subtitle || '';
      const text = b.dataset.text || '';
      const reference = b.dataset.reference || '';
      const images = b.dataset.images ? b.dataset.images.split(',').filter(Boolean) : [];
      openTextCover(theme, title, subtitle, ()=>{
        openVerseReader({ title, subtitle, text, reference, images });
      });
    };
  });
  wirePrayerRefLinks();
}

/* ================= rosary (chapelet tactile et immersif) ================= */
const ROSARY_BEAD_COLORS = { wine:'#6B2545', gold:'#C08A3E', navy:'#2C4A6B', olive:'#5C6E58' };
const ROSARY_CRUCIFIX_IMG = "https://commons.wikimedia.org/wiki/Special:Redirect/file/Cristo%20crucificado.jpg?width=500";
const ROSARY_MARIE_IMG = "https://commons.wikimedia.org/wiki/Special:Redirect/file/Bartolom%C3%A9%20Esteban%20Murillo%20-%20The%20Immaculate%20Conception%20of%20the%20Escorial.jpg?width=600";
const ROSARY_PATERNOSTER_IMG = "https://commons.wikimedia.org/wiki/Special:Redirect/file/Brooklyn%20Museum%20-%20The%20Lord%27s%20Prayer%20%28Le%20Pater%20Noster%29%20-%20James%20Tissot.jpg?width=600";
let CHAPLET_CAT_TAB = 'tous';
let ROSARY_SETTINGS_OPEN = false;
let ROSARY_SETTINGS = { audio:true, speed:1, guided:true, vibration:false, showText:true, textScale:1, beadColor:'wine', mode:'classique' };
function rosaryBuzz(){ try{ if(ROSARY_SETTINGS.vibration && navigator.vibrate) navigator.vibrate(18); }catch(e){} }
function realChapletArcHTML(litCount, total){
  // dispose les 10 petites perles (Ave) en arc, avec la grosse perle (Pater) au centre bas
  const beads = [];
  const r = 85, cx = 150, cy = 140;
  for(let i=0;i<total;i++){
    const angle = Math.PI * (0.12 + 0.76 * (i/(total-1)));
    const x = cx - r*Math.cos(angle);
    const y = cy - r*Math.sin(angle)*0.85;
    beads.push({x, y, big:false});
  }
  const col = ROSARY_BEAD_COLORS[ROSARY_SETTINGS.beadColor] || ROSARY_BEAD_COLORS.wine;
  return `<svg viewBox="0 0 300 190" class="real-chaplet-svg" style="--rosary-bead-color:${col};">
    <path d="M${cx-r*Math.cos(Math.PI*0.12)} ${cy-r*Math.sin(Math.PI*0.12)*0.85} A ${r} ${r*0.85} 0 0 1 ${cx-r*Math.cos(Math.PI*0.88)} ${cy-r*Math.sin(Math.PI*0.88)*0.85}" fill="none" stroke="#C9A876" stroke-width="2" opacity="0.5"/>
    ${beads.map((b,i)=>`<circle cx="${b.x}" cy="${b.y}" r="9" class="real-chaplet-bead ${i<litCount?'lit':''} ${i===litCount?'next':''}" data-bead-idx="${i}"/>`).join('')}
    <circle cx="${cx}" cy="${cy+58}" r="13" class="real-chaplet-bead real-chaplet-pater ${litCount>=total?'lit':''}"/>
    <line x1="${cx}" y1="${cy+71}" x2="${cx}" y2="${cy+95}" stroke="#8A6A2E" stroke-width="3"/>
    <line x1="${cx-10}" y1="${cy+82}" x2="${cx+10}" y2="${cy+82}" stroke="#8A6A2E" stroke-width="3"/>
  </svg>`;
}
function rosaryTopIconsHTML(opts){
  opts = opts || {};
  const fav = {type:'vreader-text', title:'Chapelet — '+(opts.title||''), reference:opts.sub||'', text:opts.text||''};
  return `<div class="rosary-top-icons">
    ${opts.noBack ? '' : `<button type="button" class="rosary-icon-btn" id="rosary-back-btn" title="Étape précédente" aria-label="Revenir à l'étape précédente">←</button>`}
    ${opts.noFav ? '' : favStarHTML(fav).replace('fav-star', 'fav-star rosary-icon-btn')}
    <button type="button" class="rosary-icon-btn" id="rosary-mode-btn" title="Mode d'affichage" aria-label="Changer le mode d'affichage">🕯️</button>
    <button type="button" class="rosary-icon-btn" id="rosary-settings-btn" title="Réglages" aria-label="Réglages du chapelet">⚙️</button>
    ${opts.noQuit ? '' : `<button type="button" class="rosary-icon-btn" id="rosary-quit-btn" title="Quitter le chapelet" aria-label="Quitter le chapelet">✕</button>`}
  </div>`;
}
function rosaryVariantMeta(id){
  return CHAPLET_CATALOGUE.find(c=>c.id===id) || CHAPLET_CATALOGUE[0];
}
function rosaryCurrentSet(){
  if(ROSARY_STATE.variantId === 'defunts') return ROSARY_SETS.glorieux;
  return ROSARY_SETS[ROSARY_STATE.setKey] || ROSARY_SETS.joyeux;
}
