/* ---- écran 4 : récitation guidée (Ave Maria) ---- */
function chapletAveHTML(){
  const set = rosaryCurrentSet();
  const mi = ROSARY_STATE.mysteryIdx;
  const n = ROSARY_STATE.aveCount||0;
  return `<div class="rosary-head-row"><span class="rosary-set-pill">🔗 ${set.label}</span>${rosaryTopIconsHTML({title:'Je vous salue Marie', noFav:true})}</div>
  <p class="eyebrow" style="color:var(--gold); text-align:center;">${mi+1}${mi===0?'er':'e'} mystère · ${set.mysteres[mi].title}</p>
  <h1 class="day-title" style="text-align:center;">Je vous salue Marie</h1>
  <p class="section-desc" style="text-align:center;">${n+1} sur 10</p>
  ${ROSARY_SETTINGS.showText ? `<div class="card"><p class="entry-detail-text" style="font-size:${13.5*ROSARY_SETTINGS.textScale}px;">${CHAPLET_PRAYER_TEXTS['Je vous salue Marie']}</p></div>` : ''}
  <div class="real-chaplet-wrap" role="group" aria-label="Dizaine en cours">${realChapletArcHTML(n, 10)}</div>
  <p class="studio-note" style="text-align:center;">${n} / 10${ROSARY_SETTINGS.guided ? ' — touchez la perle suivante pour avancer' : ''}</p>
  ${rosaryAudioBlockHTML(CHAPLET_PRAYER_TEXTS['Je vous salue Marie'], 'ave')}`;
}
/* ---- écran 5 : fin de dizaine (Gloire au Père) ---- */
function chapletGloriaHTML(){
  const set = rosaryCurrentSet();
  const mi = ROSARY_STATE.mysteryIdx;
  const isDefunts = ROSARY_STATE.variantId === 'defunts';
  const text = isDefunts ? ROSARY_ETERNAL_REST : CHAPLET_PRAYER_TEXTS['Gloire au Père'];
  return `<div class="rosary-head-row"><span class="rosary-set-pill">🔗 ${set.label}</span>${rosaryTopIconsHTML({title: isDefunts?'Éternel repos':'Gloire au Père', noFav:true})}</div>
  <figure class="rosary-gloria-figure">
    <img src="${ROSARY_CRUCIFIX_IMG}" alt="" loading="lazy" onerror="this.outerHTML='&lt;div class=&quot;rosary-gloria-cross&quot;&gt;✝&lt;/div&gt;';">
  </figure>
  <h1 class="day-title" style="text-align:center;">${isDefunts ? 'Éternel repos' : 'Gloire au Père'}</h1>
  ${ROSARY_SETTINGS.showText ? `<div class="card"><p class="entry-detail-text" style="text-align:center; font-size:${13.5*ROSARY_SETTINGS.textScale}px;">${text}</p></div>` : ''}
  <div class="card" style="text-align:center;">
    <p class="day-title" style="margin:0;">✓ Dizaine terminée !</p>
    <button class="btn btn-primary btn-sm" id="rosary-after-gloria" style="margin-top:10px;">${mi<4 ? 'Passer à la méditation' : 'Terminer le chapelet →'}</button>
  </div>`;
}
/* ---- écran 7 : fin du chapelet ---- */
function chapletDoneHTML(){
  return `<div class="rosary-done-hero">
    <img src="${ROSARY_MARIE_IMG}" alt="" loading="lazy" onerror="this.style.display='none'">
    <div class="rosary-done-hero-scrim"></div>
    <button type="button" class="rosary-done-close" id="rosary-done-close" aria-label="Fermer">✕</button>
    <div class="rosary-done-hero-content">
      <p class="day-title" style="color:#fff; margin:0;">Chapelet terminé !</p>
      <p class="section-desc" style="color:#F0E6D8;">Merci, Marie, pour ce temps de prière. Que ces mystères portent du fruit dans ma vie et dans le monde.</p>
    </div>
  </div>
  <div style="display:flex; flex-direction:column; gap:8px; margin-top:14px;">
    <button class="btn btn-primary btn-sm" id="rosary-restart">↻ Recommencer</button>
    <button class="btn btn-ghost btn-sm" id="rosary-change-chaplet">Choisir un autre chapelet</button>
    <button class="btn btn-ghost btn-sm" id="rosary-share">⤴ Partager cette prière</button>
  </div>`;
}
function rosaryAudioBlockHTML(text, key){
  if(!ROSARY_SETTINGS.audio) return '';
  const playing = ROSARY_AUDIO_PLAYING === key;
  return `<div class="hoz-podcast-card" style="margin-top:10px;">
    <button class="hoz-podcast-btn" id="rosary-audio-btn" data-audio-key="${key}" data-audio-text="${text.replace(/"/g,'&quot;')}">
      <span class="hoz-podcast-play-icon">${playing?'⏸':'▶'}</span>
      <span>${playing?'Pause':'Écouter cette prière'} (${ROSARY_SETTINGS.speed}x)</span>
    </button>
  </div>`;
}
/* ---- panneau réglages (contrôles et options) ---- */
function rosarySettingsPanelHTML(){
  const speeds = [0.75,1,1.25,1.5];
  const modes = [['classique','Classique'],['lumineux','Lumineux'],['sombre','Sombre']];
  const colors = Object.keys(ROSARY_BEAD_COLORS);
  return `<div class="rosary-settings-overlay" id="rosary-settings-overlay">
    <div class="rosary-settings-panel">
      <div class="rosary-settings-head">
        <p class="day-title" style="margin:0;">Contrôles et options</p>
        <button class="back-link" id="rosary-settings-close">✕</button>
      </div>
      <p class="eyebrow" style="color:var(--gold); margin-top:10px;">Mode d'affichage</p>
      <div class="chip-row">${modes.map(([k,l])=>`<button class="chip ${ROSARY_SETTINGS.mode===k?'active':''}" data-rmode="${k}">${l}</button>`).join('')}</div>
      <div class="rosary-settings-row"><span>Audio de la prière</span><button class="rosary-toggle ${ROSARY_SETTINGS.audio?'on':''}" data-toggle="audio"></button></div>
      <div class="rosary-settings-row"><span>Vitesse de lecture</span><button class="btn btn-ghost btn-sm" id="rosary-speed-btn">${ROSARY_SETTINGS.speed}x</button></div>
      <div class="rosary-settings-row"><span>Instructions guidées</span><button class="rosary-toggle ${ROSARY_SETTINGS.guided?'on':''}" data-toggle="guided"></button></div>
      <div class="rosary-settings-row"><span>Vibration (optionnelle)</span><button class="rosary-toggle ${ROSARY_SETTINGS.vibration?'on':''}" data-toggle="vibration"></button></div>
      <div class="rosary-settings-row"><span>Affichage du texte</span><button class="rosary-toggle ${ROSARY_SETTINGS.showText?'on':''}" data-toggle="showText"></button></div>
      <div class="rosary-settings-row"><span>Taille du texte</span>
        <span class="rosary-text-size-ctl"><button class="btn btn-ghost btn-sm" id="rosary-text-minus">A-</button><button class="btn btn-ghost btn-sm" id="rosary-text-plus">A+</button></span>
      </div>
      <p class="eyebrow" style="color:var(--gold); margin-top:12px;">Couleur des grains</p>
      <div class="rosary-color-row">${colors.map(c=>`<button class="rosary-color-dot ${ROSARY_SETTINGS.beadColor===c?'active':''}" data-beadcolor="${c}" style="background:${ROSARY_BEAD_COLORS[c]};"></button>`).join('')}</div>
    </div>
  </div>`;
}
function renderRosary(){
  if(!ROSARY_STATE){
    ROSARY_STATE = { variantId:null, setKey: todaysRosarySet(), phase:'catalogue', mysteryIdx:0, aveCount:0, openExpand:false, showList:false, previewIdx:0 };
  }
  let html = (ROSARY_STATE.phase==='catalogue') ? chapletCatalogueHTML()
    : (ROSARY_STATE.phase==='select') ? chapletSelectHTML()
    : (ROSARY_STATE.phase==='overview') ? chapletOverviewHTML()
    : (ROSARY_STATE.phase==='medit') ? chapletMeditHTML()
    : (ROSARY_STATE.phase==='pater') ? chapletPaterHTML()
    : (ROSARY_STATE.phase==='ave') ? chapletAveHTML()
    : (ROSARY_STATE.phase==='gloria') ? chapletGloriaHTML()
    : chapletDoneHTML();
  if(ROSARY_SETTINGS_OPEN) html += rosarySettingsPanelHTML();
  document.getElementById('screen').innerHTML = `<div class="rosary-wrap rosary-mode-${ROSARY_SETTINGS.mode}">${html}</div>`;
  wireRosaryEvents();
  saveRosaryState(ROSARY_STATE);
}
function wireRosaryEvents(){
  wireFavStars();
  document.querySelectorAll('[data-cattab]').forEach(b=> b.onclick = ()=>{ CHAPLET_CAT_TAB = b.dataset.cattab; render(); });
  document.querySelectorAll('[data-chaplet]').forEach(b=>{
    b.onclick = ()=>{
      const id = b.dataset.chaplet;
      const meta = rosaryVariantMeta(id);
      if(meta.gotoSub){ ROSARY_STATE = null; goTo('devotions', meta.gotoSub); return; }
      ROSARY_STATE = { variantId:id, setKey: todaysRosarySet(), phase: id==='defunts' ? 'overview' : 'select', mysteryIdx:0, aveCount:0, openExpand:false, showList:false, previewIdx:0 };
      render();
    };
  });
  const backCat = document.getElementById('rosary-back-catalogue');
  if(backCat) backCat.onclick = ()=>{ ROSARY_STATE.phase='catalogue'; render(); };
  const rosaryBackBtn = document.getElementById('rosary-back-btn');
  if(rosaryBackBtn) rosaryBackBtn.onclick = ()=>{
    const mi = ROSARY_STATE.mysteryIdx;
    if(ROSARY_STATE.phase==='overview'){ ROSARY_STATE.phase = ROSARY_STATE.variantId==='defunts' ? 'catalogue' : 'select'; }
    else if(ROSARY_STATE.phase==='medit'){
      if(mi>0){ ROSARY_STATE.mysteryIdx = mi-1; ROSARY_STATE.aveCount = 10; ROSARY_STATE.phase='gloria'; }
      else { ROSARY_STATE.phase='overview'; }
    }
    else if(ROSARY_STATE.phase==='pater'){ ROSARY_STATE.phase='medit'; }
    else if(ROSARY_STATE.phase==='ave'){ ROSARY_STATE.phase='pater'; }
    else if(ROSARY_STATE.phase==='gloria'){ ROSARY_STATE.aveCount = 9; ROSARY_STATE.phase='ave'; }
    try{ window.speechSynthesis.cancel(); }catch(e){}
    render();
  };
  const rosaryQuitBtn = document.getElementById('rosary-quit-btn');
  if(rosaryQuitBtn) rosaryQuitBtn.onclick = ()=>{
    try{ window.speechSynthesis.cancel(); }catch(e){}
    goTo('devotions','accueil-devotions');
  };
  document.querySelectorAll('.chip[data-set]').forEach(c=> c.onclick = ()=>{ ROSARY_STATE.setKey = c.dataset.set; render(); });
  const listBtn = document.getElementById('rosary-list-btn');
  if(listBtn) listBtn.onclick = ()=>{ ROSARY_STATE.showList = !ROSARY_STATE.showList; render(); };
  const startBtn = document.getElementById('rosary-start-btn');
  if(startBtn) startBtn.onclick = ()=>{ ROSARY_STATE.phase='overview'; render(); };
  const openExpandBtn = document.getElementById('rosary-open-expand');
  if(openExpandBtn) openExpandBtn.onclick = ()=>{ ROSARY_STATE.openExpand = !ROSARY_STATE.openExpand; render(); };
  const previewPrev = document.getElementById('rosary-preview-prev');
  const previewNext = document.getElementById('rosary-preview-next');
  if(previewPrev || previewNext){
    const total = rosaryCurrentSet().mysteres.length;
    if(previewPrev) previewPrev.onclick = ()=>{ ROSARY_STATE.previewIdx = ((ROSARY_STATE.previewIdx||0) - 1 + total) % total; render(); };
    if(previewNext) previewNext.onclick = ()=>{ ROSARY_STATE.previewIdx = ((ROSARY_STATE.previewIdx||0) + 1) % total; render(); };
  }
  document.querySelectorAll('.rosary-preview-dot[data-preview-idx]').forEach(dot=>{
    dot.onclick = ()=>{ ROSARY_STATE.previewIdx = parseInt(dot.dataset.previewIdx,10); render(); };
  });
  const doneCloseBtn = document.getElementById('rosary-done-close');
  if(doneCloseBtn) doneCloseBtn.onclick = ()=>{ ROSARY_STATE = null; render(); };
  const beginMysteries = document.getElementById('rosary-begin-mysteries');
  if(beginMysteries) beginMysteries.onclick = ()=>{ ROSARY_STATE.phase='medit'; ROSARY_TAB='meditation'; render(); };
  document.querySelectorAll('.bible-reader-tab[data-rtab]').forEach(btn=>{
    btn.onclick = ()=>{ ROSARY_TAB = btn.dataset.rtab; try{ window.speechSynthesis.cancel(); }catch(e){} render(); };
  });
  const afterMedit = document.getElementById('rosary-after-medit');
  if(afterMedit) afterMedit.onclick = ()=>{ ROSARY_STATE.phase='pater'; try{ window.speechSynthesis.cancel(); }catch(e){} render(); };
  const afterPater = document.getElementById('rosary-after-pater');
  if(afterPater) afterPater.onclick = ()=>{ ROSARY_STATE.phase='ave'; ROSARY_STATE.aveCount=0; try{ window.speechSynthesis.cancel(); }catch(e){} render(); };
  document.querySelectorAll('.real-chaplet-bead[data-bead-idx]').forEach(bead=>{
    bead.onclick = ()=>{
      const idx = parseInt(bead.dataset.beadIdx,10);
      if(idx === (ROSARY_STATE.aveCount||0) && ROSARY_STATE.aveCount < 10){
        ROSARY_STATE.aveCount++; rosaryBuzz();
        if(ROSARY_STATE.aveCount>=10){ ROSARY_STATE.phase='gloria'; try{ window.speechSynthesis.cancel(); }catch(e){} }
        render();
      }
    };
  });
  const afterGloria = document.getElementById('rosary-after-gloria');
  if(afterGloria) afterGloria.onclick = async ()=>{
    const set = rosaryCurrentSet();
    if(ROSARY_STATE.mysteryIdx < 4){ ROSARY_STATE.mysteryIdx++; ROSARY_STATE.aveCount=0; ROSARY_TAB='meditation'; ROSARY_STATE.phase='medit'; }
    else { ROSARY_STATE.phase='done'; await markPrayedToday('chapelet', 'Chapelet'); fireCelebration(); }
    render();
  };
  const restartBtn = document.getElementById('rosary-restart');
  if(restartBtn) restartBtn.onclick = ()=>{ const v=ROSARY_STATE.variantId; ROSARY_STATE = { variantId:v, setKey: todaysRosarySet(), phase: v==='defunts'?'overview':'select', mysteryIdx:0, aveCount:0, openExpand:false, showList:false, previewIdx:0 }; ROSARY_TAB='meditation'; render(); };
  const changeChapletBtn = document.getElementById('rosary-change-chaplet');
  if(changeChapletBtn) changeChapletBtn.onclick = ()=>{ ROSARY_STATE = null; render(); };
  const shareBtn = document.getElementById('rosary-share');
  if(shareBtn) shareBtn.onclick = ()=>{
    const text = `J'ai prié le chapelet (${rosaryCurrentSet().label}) sur Lumen 📿`;
    if(navigator.share){ navigator.share({text}).catch(()=>{}); } else { showToast('Partage non disponible sur cet appareil'); }
  };
  /* icônes du haut */
  const modeBtn = document.getElementById('rosary-mode-btn');
  if(modeBtn) modeBtn.onclick = ()=>{
    const order = ['classique','lumineux','sombre'];
    ROSARY_SETTINGS.mode = order[(order.indexOf(ROSARY_SETTINGS.mode)+1)%order.length];
    render();
  };
  const settingsBtn = document.getElementById('rosary-settings-btn');
  if(settingsBtn) settingsBtn.onclick = ()=>{ ROSARY_SETTINGS_OPEN = true; render(); };
  const settingsClose = document.getElementById('rosary-settings-close');
  if(settingsClose) settingsClose.onclick = ()=>{ ROSARY_SETTINGS_OPEN = false; render(); };
  const overlay = document.getElementById('rosary-settings-overlay');
  if(overlay) overlay.onclick = (e)=>{ if(e.target===overlay){ ROSARY_SETTINGS_OPEN=false; render(); } };
  document.querySelectorAll('[data-rmode]').forEach(b=> b.onclick = ()=>{ ROSARY_SETTINGS.mode = b.dataset.rmode; render(); });
  document.querySelectorAll('[data-toggle]').forEach(b=> b.onclick = ()=>{ const k=b.dataset.toggle; ROSARY_SETTINGS[k] = !ROSARY_SETTINGS[k]; render(); });
  const speedBtn = document.getElementById('rosary-speed-btn');
  if(speedBtn) speedBtn.onclick = ()=>{
    const speeds=[0.75,1,1.25,1.5];
    ROSARY_SETTINGS.speed = speeds[(speeds.indexOf(ROSARY_SETTINGS.speed)+1)%speeds.length];
    render();
  };
  const textMinus = document.getElementById('rosary-text-minus');
  if(textMinus) textMinus.onclick = ()=>{ ROSARY_SETTINGS.textScale = Math.max(0.8, +(ROSARY_SETTINGS.textScale-0.1).toFixed(2)); render(); };
  const textPlus = document.getElementById('rosary-text-plus');
  if(textPlus) textPlus.onclick = ()=>{ ROSARY_SETTINGS.textScale = Math.min(1.4, +(ROSARY_SETTINGS.textScale+0.1).toFixed(2)); render(); };
  document.querySelectorAll('[data-beadcolor]').forEach(b=> b.onclick = ()=>{ ROSARY_SETTINGS.beadColor = b.dataset.beadcolor; render(); });
  /* lecture audio */
  const audioBtn = document.getElementById('rosary-audio-btn');
  if(audioBtn){
    const key = audioBtn.dataset.audioKey;
    const text = audioBtn.dataset.audioText;
    audioBtn.onclick = ()=>{
      if(ROSARY_AUDIO_PLAYING === key){ try{ window.speechSynthesis.cancel(); }catch(e){} ROSARY_AUDIO_PLAYING = null; render(); return; }
      try{ window.speechSynthesis.cancel(); }catch(e){}
      const u = new SpeechSynthesisUtterance(text);
      u.lang = 'fr-FR'; u.rate = ROSARY_SETTINGS.speed; applyNaturalVoice(u);
      u.onend = ()=>{ if(ROSARY_AUDIO_PLAYING===key){ ROSARY_AUDIO_PLAYING=null; render(); } };
      ROSARY_AUDIO_PLAYING = key;
      window.speechSynthesis.speak(u);
      render();
    };
  }
}

/* ================= examen du soir ================= */
let EXAMEN_MODE = 'soir';
function renderExamen(){
  if(!EXAMEN_STATE){ EXAMEN_STATE = { step:0, notes:'' }; }
  const steps = EXAMEN_MODE==='matin' ? EXAMEN_MORNING_STEPS : EXAMEN_STEPS;
  const step = steps[EXAMEN_STATE.step] || steps[0];
  if(EXAMEN_STATE.step >= steps.length) EXAMEN_STATE.step = 0;
  let html = `<h2 class="section-title">${EXAMEN_MODE==='matin'?'☀️ Examen du matin':'🌙 Examen du soir'}</h2>
    <div class="cal-toggle">
      <button data-mode="matin" class="${EXAMEN_MODE==='matin'?'active':''}">☀️ Le matin</button>
      <button data-mode="soir" class="${EXAMEN_MODE==='soir'?'active':''}">🌙 Le soir</button>
    </div>
    <p class="section-desc">${EXAMEN_MODE==='matin' ? "Une brève offrande de la journée à venir." : "Une relecture priante de la journée, en cinq étapes, inspirée de la tradition ignatienne."}</p>
    <div class="step-progress">${steps.map((_,i)=>`<span class="${i<EXAMEN_STATE.step?'done':i===EXAMEN_STATE.step?'current':''}"></span>`).join('')}</div>
    <div class="card">
      <p class="eyebrow" style="color:var(--gold);">Étape ${EXAMEN_STATE.step+1} / ${steps.length}</p>
      <p class="day-title">${step.title}</p>
      <p class="entry-detail-text">${step.text}</p>`;
  if(EXAMEN_STATE.step === steps.length-1){
    html += `<textarea id="examen-notes" rows="3" placeholder="${EXAMEN_MODE==='matin'?"Une intention pour aujourd'hui (optionnel)":"Votre résolution pour demain (optionnel)"}">${EXAMEN_STATE.notes}</textarea>`;
  }
  html += `<div style="text-align:center; margin-top:8px;">
        ${EXAMEN_STATE.step>0?'<button class="btn btn-ghost btn-sm" id="examen-prev" style="margin-right:8px;">← Précédent</button>':''}
        <button class="btn btn-primary btn-sm" id="examen-next">${EXAMEN_STATE.step<steps.length-1?'Suivant →':'Terminer'}</button>
      </div>
    </div>`;
  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('.cal-toggle button').forEach(b=>{
    b.onclick = ()=>{ EXAMEN_MODE = b.dataset.mode; EXAMEN_STATE = {step:0, notes:''}; render(); };
  });
  const prevBtn = document.getElementById('examen-prev');
  if(prevBtn) prevBtn.onclick = ()=>{ EXAMEN_STATE.step--; render(); };
  document.getElementById('examen-next').onclick = async ()=>{
    const notesEl = document.getElementById('examen-notes');
    if(notesEl) EXAMEN_STATE.notes = notesEl.value;
    if(EXAMEN_STATE.step < steps.length-1){ EXAMEN_STATE.step++; render(); }
    else {
      await markPrayedToday('examen', 'Examen de conscience');
      if(EXAMEN_STATE.notes.trim()){
        const label = EXAMEN_MODE==='matin' ? "☀️ Examen du matin — " : "🌙 Examen du soir — ";
        JOURNAL.unshift({id:'j-'+Date.now(), text:label+EXAMEN_STATE.notes.trim(), createdAt:Date.now()});
        await saveJournal(JOURNAL);
      }
      EXAMEN_STATE = { step:0, notes:'' };
      showToast(EXAMEN_MODE==='matin' ? 'Journée offerte ☀️' : 'Examen terminé 🌙');
      goTo('espace','journal');
    }
  };
}

/* ================= lectio divina ================= */
let LECTIO_STATE = null;
const LECTIO_STEPS_LABELS = ["Lecture","Méditation","Prière","Contemplation"];
function renderLectio(){
  if(!LECTIO_STATE){
    const idx = Math.floor(Math.random()*LECTIO_PASSAGES.length);
    LECTIO_STATE = { passageIdx: idx, step: 0 };
  }
  const passage = LECTIO_PASSAGES[LECTIO_STATE.passageIdx];
  const stepLabel = LECTIO_STEPS_LABELS[LECTIO_STATE.step];
  let html = `<h2 class="section-title">📕 Lectio Divina</h2>
    <p class="section-desc">Une lecture priante en quatre temps : lire, méditer, prier, contempler.</p>
    <div class="step-progress">${LECTIO_STEPS_LABELS.map((_,i)=>`<span class="${i<LECTIO_STATE.step?'done':i===LECTIO_STATE.step?'current':''}"></span>`).join('')}</div>
    <div class="card">
      <p class="eyebrow" style="color:var(--gold);">${stepLabel} — ${passage.ref}</p>`;
  if(LECTIO_STATE.step===0){
    html += `<p class="day-title">Lecture (Lectio)</p><p class="entry-detail-text">${passage.text}</p><p class="section-desc">Lisez ce texte lentement, une ou deux fois, sans chercher à l'analyser — juste à l'entendre.</p>`;
  } else if(LECTIO_STATE.step===1){
    html += `<p class="day-title">Méditation (Meditatio)</p><p class="entry-detail-text">${passage.meditation}</p><p class="section-desc">Laissez cette question résonner en vous, sans vous presser d'y répondre.</p>`;
  } else if(LECTIO_STATE.step===2){
    html += `<p class="day-title">Prière (Oratio)</p><p class="entry-detail-text">Répondez maintenant à Dieu avec vos propres mots, à partir de ce que ce texte a fait naître en vous — une demande, une action de grâce, un cri, un silence.</p>`;
  } else {
    html += `<p class="day-title">Contemplation (Contemplatio)</p><p class="entry-detail-text">Reposez-vous simplement en présence de Dieu, sans mots, quelques instants, avant de reprendre votre journée.</p>`;
  }
  html += `<div style="text-align:center; margin-top:10px;">
      ${LECTIO_STATE.step>0?'<button class="btn btn-ghost btn-sm" id="lectio-prev" style="margin-right:8px;">← Précédent</button>':''}
      <button class="btn btn-primary btn-sm" id="lectio-next">${LECTIO_STATE.step<3?'Suivant →':'Terminer'}</button>
    </div>
    </div>
    <div style="text-align:center;"><button class="btn btn-ghost btn-sm" id="lectio-new">🔀 Changer de passage</button></div>`;
  document.getElementById('screen').innerHTML = html;
  const prevBtn = document.getElementById('lectio-prev');
  if(prevBtn) prevBtn.onclick = ()=>{ LECTIO_STATE.step--; render(); };
  document.getElementById('lectio-next').onclick = async ()=>{
    if(LECTIO_STATE.step<3){ LECTIO_STATE.step++; render(); }
    else { await markPrayedToday('lectio', 'Lectio Divina'); showToast('Lectio Divina terminée 📕'); LECTIO_STATE=null; render(); }
  };
  document.getElementById('lectio-new').onclick = ()=>{ LECTIO_STATE=null; render(); };
}

/* ================= chapelet de la Divine Miséricorde ================= */
let MISERICORDE_STATE = null;
const MISERICORDE_IMG = "https://commons.wikimedia.org/wiki/Special:FilePath/Kazimirowski_Eugeniusz,_Divine_Mercy,_1934.jpg?width=600";
function renderMisericorde(){
  if(!MISERICORDE_STATE){ MISERICORDE_STATE = { phase:'intro', decadeIdx:0, beadCount:0 }; }
  let html = `<div class="rosary-head-row">
      <span class="rosary-set-pill">❤️ Miséricorde</span>
      <div class="rosary-top-icons">
        ${MISERICORDE_STATE.phase==='intro' ? '' : `<button type="button" class="rosary-icon-btn" id="misericorde-back-btn" title="Étape précédente" aria-label="Revenir à l'étape précédente">←</button>`}
        <button type="button" class="rosary-icon-btn" id="misericorde-quit-btn" title="Quitter le chapelet" aria-label="Quitter le chapelet">✕</button>
      </div>
    </div>
    <h2 class="section-title">❤️ Chapelet de la Miséricorde</h2>
    <p class="section-desc">Traditionnellement prié à 15h, l'heure de la miséricorde, sur un chapelet ordinaire.</p>
    <figure class="rosary-gloria-figure"><img src="${MISERICORDE_IMG}" alt="" loading="lazy" onerror="this.style.display='none'"></figure>`;
  if(MISERICORDE_STATE.phase === 'intro'){
    html += `<div class="card">
      <p class="entry-detail-text">Signe de croix, un Notre Père, un Je vous salue Marie, le Je crois en Dieu. Puis, sur les gros grains : « ${MISERICORDE_TEXTS.eternel} »</p>
      <div style="text-align:center; margin-top:10px;"><button class="btn btn-primary btn-sm" id="misericorde-start">Commencer les dizaines →</button></div>
    </div>`;
  } else if(MISERICORDE_STATE.phase === 'decade'){
    const di = MISERICORDE_STATE.decadeIdx;
    html += `<div class="step-progress">${Array.from({length:5}).map((_,i)=>`<span class="${i<di?'done':i===di?'current':''}"></span>`).join('')}</div>`;
    html += `<div class="card">
      <p class="eyebrow" style="color:var(--gold);">${di+1}${di===0?'re':'e'} dizaine sur 5</p>
      <p class="entry-detail-text">Sur les dix petits grains, répétez dix fois : « ${MISERICORDE_TEXTS.decade} »</p>
      <div class="bead-counter">
        <button class="btn btn-ghost btn-sm" id="bead-minus">−</button>
        <span class="bead-num">${MISERICORDE_STATE.beadCount}<span style="font-size:16px;color:var(--ink-soft);">/10</span></span>
        <button class="btn btn-ghost btn-sm" id="bead-plus">+</button>
      </div>
      <div class="bead-dots">${Array.from({length:10}).map((_,i)=>`<span class="bead-dot ${i<MISERICORDE_STATE.beadCount?'done':''}"></span>`).join('')}</div>
      <div style="text-align:center;"><button class="btn btn-primary btn-sm" id="decade-next">${di<4?'Dizaine suivante →':'Terminer →'}</button></div>
    </div>`;
  } else {
    html += `<div class="card" style="text-align:center;">
      <p class="day-title">Chapelet achevé ✦</p>
      <p class="entry-detail-text">Concluez trois fois par : « ${MISERICORDE_TEXTS.final} »</p>
      <button class="btn btn-ghost btn-sm" id="misericorde-restart">Recommencer</button>
    </div>`;
  }
  document.getElementById('screen').innerHTML = html;
  const startBtn = document.getElementById('misericorde-start');
  if(startBtn) startBtn.onclick = ()=>{ MISERICORDE_STATE.phase='decade'; render(); };
  const minusBtn = document.getElementById('bead-minus');
  if(minusBtn) minusBtn.onclick = ()=>{ if(MISERICORDE_STATE.beadCount>0) MISERICORDE_STATE.beadCount--; render(); };
  const plusBtn = document.getElementById('bead-plus');
  if(plusBtn) plusBtn.onclick = ()=>{ if(MISERICORDE_STATE.beadCount<10) MISERICORDE_STATE.beadCount++; render(); };
  const nextBtn = document.getElementById('decade-next');
  if(nextBtn) nextBtn.onclick = async ()=>{
    if(MISERICORDE_STATE.decadeIdx<4){ MISERICORDE_STATE.decadeIdx++; MISERICORDE_STATE.beadCount=0; }
    else { MISERICORDE_STATE.phase='done'; await markPrayedToday('chapelet', 'Chapelet de la Miséricorde'); }
    render();
  };
  const restartBtn = document.getElementById('misericorde-restart');
  if(restartBtn) restartBtn.onclick = ()=>{ MISERICORDE_STATE = { phase:'intro', decadeIdx:0, beadCount:0 }; render(); };
  const backBtn = document.getElementById('misericorde-back-btn');
  if(backBtn) backBtn.onclick = ()=>{
    if(MISERICORDE_STATE.phase==='decade'){
      if(MISERICORDE_STATE.decadeIdx>0){ MISERICORDE_STATE.decadeIdx--; MISERICORDE_STATE.beadCount=10; }
      else { MISERICORDE_STATE.phase='intro'; }
    } else if(MISERICORDE_STATE.phase==='done'){
      MISERICORDE_STATE.phase='decade'; MISERICORDE_STATE.decadeIdx=4; MISERICORDE_STATE.beadCount=10;
    }
    render();
  };
  const quitBtn = document.getElementById('misericorde-quit-btn');
  if(quitBtn) quitBtn.onclick = ()=>{ goTo('devotions','accueil-devotions'); };
}

