/* ================= stats dashboard ================= */
function renderStats(){
  const totalNovenaDays = Object.values(PROGRESS).reduce((sum,p)=> sum + (p.completed? p.completed.filter(Boolean).length : 0), 0);
  const novenaCompleted = Object.values(PROGRESS).filter(p=>p.completed && p.completed.every(Boolean)).length;
  const unlockedBadges = BADGES.filter(b=>{ try{ return b.test(); }catch(e){ return false; } });
  const engagementScore = STREAK.count + totalNovenaDays*2 + novenaCompleted*10 + JOURNAL.length + GRATITUDE_ENTRIES.length + (HISTOIRE_ENTRIES||[]).length*2;
  let html = `<h2 class="section-title">📊 Mes statistiques</h2>
    ${spiritualTreeHTML(engagementScore)}
    ${journeyTimelineHTML()}
    <div class="stat-grid">
      <div class="card stat-card"><span class="stat-num">${STREAK.count}</span><span class="stat-label">jours de suite</span></div>
      <div class="card stat-card"><span class="stat-num">${totalNovenaDays}</span><span class="stat-label">jours de neuvaine priés</span></div>
      <div class="card stat-card"><span class="stat-num">${novenaCompleted}</span><span class="stat-label">neuvaines terminées</span></div>
      <div class="card stat-card"><span class="stat-num">${JOURNAL.length}</span><span class="stat-label">écrits dans le journal</span></div>
      <div class="card stat-card"><span class="stat-num">${FAVORITES.length}</span><span class="stat-label">favoris épinglés</span></div>
      <div class="card stat-card"><span class="stat-num">${INTENTIONS.length + PRIVATE_INTENTIONS.length}</span><span class="stat-label">intentions déposées</span></div>
    </div>

    <h2 class="section-title">📅 Les 30 derniers jours</h2>
    ${prayerHeatmapHTML()}
    <div style="text-align:center; margin:4px 0 18px;"><button class="btn btn-gold btn-sm" id="goto-activite-btn">🗓️ Voir le récapitulatif détaillé (jour / semaine / mois / année)</button></div>

    <h2 class="section-title">🏆 Mes succès (${unlockedBadges.length}/${BADGES.length})</h2>
    <div class="badge-grid">${BADGES.map(b=>{
      let unlocked = false; try{ unlocked = b.test(); }catch(e){}
      return `<div class="card badge-card ${unlocked?'badge-unlocked':'badge-locked'}">
        <span class="badge-icon">${unlocked ? b.icon : '🔒'}</span>
        <p class="badge-title">${b.title}</p>
        <p class="badge-desc">${b.desc}</p>
      </div>`;
    }).join('')}</div>

    <h2 class="section-title">💾 Sauvegarder mes données</h2>
    <div class="card">
      <p class="section-desc" style="margin-top:0;">Exportez votre journal, vos favoris et votre progression dans un fichier, pour les garder en cas de changement d'appareil.</p>
      <button class="btn btn-primary btn-sm" id="export-btn">⬇️ Exporter mes données</button>
    </div>
    <div class="card">
      <p class="section-desc" style="margin-top:0;">Réimportez un fichier exporté précédemment, pour retrouver votre journal, vos favoris et votre progression sur un nouvel appareil (sans compte).</p>
      <input type="file" id="import-file-input" accept="application/json" style="margin-bottom:10px;">
      <button class="btn btn-gold btn-sm" id="import-btn">⬆️ Réimporter mes données</button>
    </div>`;
  document.getElementById('screen').innerHTML = html;
  document.getElementById('goto-activite-btn').onclick = ()=>{ SUBTAB.espace = 'activite'; render(); };
  document.getElementById('export-btn').onclick = ()=>{
    const data = { journal:JOURNAL, favorites:FAVORITES, progress:PROGRESS, streak:STREAK, privateIntentions:PRIVATE_INTENTIONS, activityLog:ACTIVITY_LOG, exportedAt:new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data,null,2)], {type:'application/json'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'lumen-export-'+todayISO()+'.json';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast('Export téléchargé ⬇️');
  };
  document.getElementById('import-btn').onclick = async ()=>{
    const fileInput = document.getElementById('import-file-input');
    const file = fileInput.files[0];
    if(!file){ showToast('Choisissez un fichier à importer'); return; }
    try{
      const text = await file.text();
      const data = JSON.parse(text);
      if(Array.isArray(data.journal)){ JOURNAL = data.journal; await saveJournal(JOURNAL); }
      if(Array.isArray(data.favorites)){ FAVORITES = data.favorites; await savePrefs(); }
      if(data.progress){ PROGRESS = data.progress; await saveProgress(PROGRESS); }
      if(data.streak){ STREAK = data.streak; await savePrefs(); }
      if(Array.isArray(data.privateIntentions)){ PRIVATE_INTENTIONS = data.privateIntentions; await savePrivateIntentions(PRIVATE_INTENTIONS); }
      if(Array.isArray(data.activityLog)){ ACTIVITY_LOG = data.activityLog; await saveActivityLog(ACTIVITY_LOG); }
      showToast('Données réimportées ⬆️');
      renderStats();
    }catch(e){
      showToast("Fichier invalide ou corrompu");
    }
  };
}
function spiritualTreeHTML(score){
  let tier = 0, label = 'Une graine plantée', desc = "Chaque prière est une graine — la vôtre vient d'être semée.";
  if(score >= 150){ tier = 3; label = 'Un arbre fleuri'; desc = "Votre engagement porte des fruits visibles — continuez à en prendre soin."; }
  else if(score >= 60){ tier = 2; label = 'Un jeune arbre'; desc = "Les racines sont bien installées — l'arbre commence à s'élever."; }
  else if(score >= 20){ tier = 1; label = 'Une jeune pousse'; desc = "Les premières feuilles apparaissent — continuez, ça grandit."; }

  const trunkH = [18, 34, 56, 70][tier];
  const trunkW = [5, 7, 10, 12][tier];
  const foliage = [
    `<circle cx="100" cy="${132-trunkH}" r="7" fill="var(--gold-light)" fill-opacity="0.7"/>`,
    `<circle cx="100" cy="${132-trunkH}" r="16" fill="var(--sage,#8FA13F)" fill-opacity="0.55"/><circle cx="88" cy="${140-trunkH}" r="11" fill="var(--sage,#8FA13F)" fill-opacity="0.5"/><circle cx="112" cy="${140-trunkH}" r="11" fill="var(--sage,#8FA13F)" fill-opacity="0.5"/>`,
    `<circle cx="100" cy="${128-trunkH}" r="26" fill="var(--sage,#8FA13F)" fill-opacity="0.55"/><circle cx="76" cy="${142-trunkH}" r="18" fill="var(--sage,#8FA13F)" fill-opacity="0.5"/><circle cx="124" cy="${142-trunkH}" r="18" fill="var(--sage,#8FA13F)" fill-opacity="0.5"/>`,
    `<circle cx="100" cy="${122-trunkH}" r="34" fill="var(--sage,#8FA13F)" fill-opacity="0.55"/><circle cx="68" cy="${140-trunkH}" r="22" fill="var(--sage,#8FA13F)" fill-opacity="0.5"/><circle cx="132" cy="${140-trunkH}" r="22" fill="var(--sage,#8FA13F)" fill-opacity="0.5"/>
     <circle cx="80" cy="${110-trunkH}" r="4" fill="var(--gold)"/><circle cx="120" cy="${115-trunkH}" r="4" fill="var(--gold)"/><circle cx="100" cy="${95-trunkH}" r="4" fill="var(--gold)"/><circle cx="60" cy="${130-trunkH}" r="4" fill="var(--gold)"/><circle cx="140" cy="${130-trunkH}" r="4" fill="var(--gold)"/>`
  ][tier];

  return `<div class="card" style="text-align:center;">
    <p class="eyebrow" style="color:var(--gold);">🌳 Mon arbre spirituel</p>
    <svg width="200" height="150" viewBox="0 0 200 150" style="margin:6px auto; display:block;">
      <ellipse cx="100" cy="140" rx="50" ry="6" fill="var(--hairline)" opacity="0.5"/>
      <rect x="${100-trunkW/2}" y="${132-trunkH}" width="${trunkW}" height="${trunkH}" rx="3" fill="var(--wine-dark)" fill-opacity="0.6"/>
      ${foliage}
    </svg>
    <p class="day-title" style="font-size:15px; margin:2px 0;">${label}</p>
    <p class="section-desc" style="margin:0;">${desc}</p>
  </div>`;
}
function journeyTimelineHTML(){
  const events = [];
  (JOURNAL||[]).forEach(e=> events.push({date:e.createdAt||e.date, icon:'✍️', label:'Écrit dans le journal'}));
  (GRATITUDE_ENTRIES||[]).forEach(e=> events.push({date:new Date(e.date).getTime(), icon:'✨', label:'Carnet de grâces rempli'}));
  (HISTOIRE_ENTRIES||[]).forEach(e=> events.push({date:e.createdAt, icon:'📖', label:e.titre ? 'Récit : '+e.titre : 'Récit ajouté à mon histoire'}));
  Object.keys(PROGRESS||{}).forEach(id=>{
    const p = PROGRESS[id];
    if(p.completed && p.completed.every(Boolean)){
      const n = NOVENAS.find(x=>x.id===id);
      events.push({date: Date.now(), icon:'🕯️', label: n ? 'Neuvaine terminée : '+n.title : 'Neuvaine terminée'});
    }
  });
  const sorted = events.filter(e=>e.date).sort((a,b)=>b.date-a.date).slice(0,10);
  if(sorted.length === 0){
    return `<div class="card empty-state">Votre frise se remplira au fil de vos pas — journal, gratitude, neuvaines...</div>`;
  }
  return `<div class="card">
    <p class="eyebrow" style="color:var(--gold); margin-bottom:10px;">🗺️ Ma frise du parcours</p>
    <div class="journey-timeline">${sorted.map(e=>`
      <div class="journey-event">
        <span class="journey-dot">${e.icon}</span>
        <div>
          <p class="entry-summary" style="-webkit-line-clamp:unset; margin:0;">${e.label}</p>
          <p class="studio-note" style="margin:0;">${new Date(e.date).toLocaleDateString('fr-FR', {day:'numeric', month:'long', year:'numeric'})}</p>
        </div>
      </div>`).join('')}
    </div>
  </div>`;
}
function prayerHeatmapHTML(){
  const days = [];
  for(let i=29;i>=0;i--){
    const d = new Date(); d.setDate(d.getDate()-i);
    const iso = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
    days.push({ iso, prayed: PRAYED_DATES.includes(iso), label: d.getDate() });
  }
  return `<div class="card">
    <div class="heatmap-grid">${days.map(d=>`<div class="heatmap-cell ${d.prayed?'heatmap-on':''}" title="${d.iso}">${d.label}</div>`).join('')}</div>
    <p class="studio-note" style="margin-top:8px;">${PRAYED_DATES.filter(d=>days.some(x=>x.iso===d)).length} jour(s) de prière sur les 30 derniers.</p>
  </div>`;
}

/* ================= récapitulatif d'activité (jour / semaine / mois / année) =================
   S'appuie sur ACTIVITY_LOG, alimenté par logActivity() à chaque action marquante
   (prière, chapelet, office, lecture, journal...) — voir markPrayedToday(). */
let ACTIVITY_PERIOD = 'semaine';
let ACTIVITY_OFFSET = 0;
function isoFromDate(d){ return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function startOfWeekDate(d){
  const r = new Date(d);
  const day = (r.getDay()+6)%7; // lundi = 0
  r.setDate(r.getDate()-day);
  r.setHours(0,0,0,0);
  return r;
}
function activityEntriesInRange(fromKey, toKey){
  return ACTIVITY_LOG.filter(e=> e.date >= fromKey && e.date <= toKey);
}
function activityBreakdownHTML(entries){
  if(!entries.length) return `<div class="card"><p class="studio-note" style="text-align:center; margin:4px 0;">Aucune activité sur cette période.</p></div>`;
  const counts = {};
  entries.forEach(e=>{ counts[e.type] = (counts[e.type]||0)+1; });
  const rows = Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([type,n])=>{
    const meta = ACTIVITY_TYPE_META[type] || {icon:'🙏', label:type};
    return `<div class="activity-breakdown-row">
      <span class="activity-breakdown-icon">${meta.icon}</span>
      <span class="activity-breakdown-label">${meta.label}</span>
      <span class="activity-breakdown-num">${n}</span>
    </div>`;
  }).join('');
  return `<div class="card activity-breakdown">${rows}</div>`;
}
function activityListHTML(entries, cap){
  if(!entries.length) return '';
  const sorted = [...entries].sort((a,b)=> b.ts - a.ts);
  const shown = cap ? sorted.slice(0, cap) : sorted;
  const rows = shown.map(e=>{
    const meta = ACTIVITY_TYPE_META[e.type] || {icon:'🙏'};
    const time = new Date(e.ts).toLocaleTimeString('fr-FR', {hour:'2-digit', minute:'2-digit'});
    const dateLabel = new Date(e.ts).toLocaleDateString('fr-FR', {day:'numeric', month:'short'});
    return `<div class="activity-day-row">
      <span class="activity-day-icon">${meta.icon}</span>
      <span class="activity-day-label">${e.label}</span>
      <span class="activity-day-time">${cap!==undefined ? dateLabel+' · ' : ''}${time}</span>
    </div>`;
  }).join('');
  const more = cap && sorted.length > cap ? `<p class="studio-note" style="text-align:center; margin-top:6px;">+ ${sorted.length-cap} autre(s)</p>` : '';
  return `<div class="card activity-day-list">${rows}</div>${more}`;
}
function renderActivite(){
  const now = new Date();
  const periodTabs = [['jour','Jour'],['semaine','Semaine'],['mois','Mois'],['annee','Année']];
  let html = `<h2 class="section-title">🗓️ Mon activité</h2>
    <p class="section-desc">Tout ce que vous avez prié, lu ou écrit dans Lumen — jour par jour, semaine par semaine, mois par mois, année par année.</p>
    <div class="chip-row" id="activity-period-tabs">${periodTabs.map(([p,l])=>
      `<button class="chip ${ACTIVITY_PERIOD===p?'active':''}" data-period="${p}">${l}</button>`).join('')}</div>`;

  let periodLabel = '', entries = [], extraHTML = '';

  if(ACTIVITY_PERIOD === 'jour'){
    const d = new Date(now); d.setDate(d.getDate()+ACTIVITY_OFFSET);
    const key = isoFromDate(d);
    entries = ACTIVITY_LOG.filter(e=>e.date===key);
    periodLabel = d.toLocaleDateString('fr-FR', {weekday:'long', day:'numeric', month:'long', year:'numeric'});
  } else if(ACTIVITY_PERIOD === 'semaine'){
    const base = new Date(now); base.setDate(base.getDate()+ACTIVITY_OFFSET*7);
    const start = startOfWeekDate(base);
    const end = new Date(start); end.setDate(end.getDate()+6);
    const fromKey = isoFromDate(start), toKey = isoFromDate(end);
    entries = activityEntriesInRange(fromKey, toKey);
    periodLabel = `Semaine du ${start.toLocaleDateString('fr-FR',{day:'numeric',month:'long'})} au ${end.toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'})}`;
    const days = [];
    for(let i=0;i<7;i++){
      const dd = new Date(start); dd.setDate(dd.getDate()+i);
      const k = isoFromDate(dd);
      days.push({label: dd.toLocaleDateString('fr-FR',{weekday:'short'}).replace('.',''), n: entries.filter(e=>e.date===k).length, isToday: k===isoFromDate(now)});
    }
    const maxN = Math.max(1, ...days.map(d=>d.n));
    extraHTML = `<div class="card activity-bars">
      <div class="activity-bar-row">${days.map(d=>`
        <div class="activity-bar-col">
          <div class="activity-bar-track"><div class="activity-bar-fill" style="height:${d.n?Math.max(10,(d.n/maxN)*100):0}%"></div></div>
          <span class="activity-bar-num">${d.n||''}</span>
          <span class="activity-bar-label ${d.isToday?'activity-bar-today':''}">${d.label}</span>
        </div>`).join('')}</div>
    </div>`;
  } else if(ACTIVITY_PERIOD === 'mois'){
    const base = new Date(now.getFullYear(), now.getMonth()+ACTIVITY_OFFSET, 1);
    const year = base.getFullYear(), month = base.getMonth();
    const first = new Date(year, month, 1);
    const last = new Date(year, month+1, 0);
    const fromKey = isoFromDate(first), toKey = isoFromDate(last);
    entries = activityEntriesInRange(fromKey, toKey);
    periodLabel = base.toLocaleDateString('fr-FR', {month:'long', year:'numeric'});
    const leading = (first.getDay()+6)%7;
    const cells = [];
    for(let i=0;i<leading;i++) cells.push(null);
    for(let day=1; day<=last.getDate(); day++){
      const dd = new Date(year, month, day);
      const k = isoFromDate(dd);
      const n = entries.filter(e=>e.date===k).length;
      cells.push({day, n, isToday:k===isoFromDate(now)});
    }
    extraHTML = `<div class="card">
      <div class="activity-month-weekdays">${['L','M','M','J','V','S','D'].map(w=>`<span>${w}</span>`).join('')}</div>
      <div class="heatmap-grid activity-month-grid">${cells.map(c=> c ? `<div class="heatmap-cell ${c.n?'heatmap-on':''} ${c.isToday?'activity-cell-today':''}" title="${c.n} activité(s)">${c.day}</div>` : `<div class="heatmap-cell activity-cell-empty"></div>`).join('')}</div>
    </div>`;
  } else {
    const year = now.getFullYear()+ACTIVITY_OFFSET;
    const fromKey = year+'-01-01', toKey = year+'-12-31';
    entries = activityEntriesInRange(fromKey, toKey);
    periodLabel = String(year);
    const months = [];
    for(let m=0;m<12;m++){
      const mk = year+'-'+String(m+1).padStart(2,'0');
      months.push({label: MONTH_NAMES_FR[m].slice(0,3), n: entries.filter(e=>e.date.startsWith(mk)).length});
    }
    const maxN = Math.max(1, ...months.map(m=>m.n));
    extraHTML = `<div class="card activity-bars">
      <div class="activity-bar-row activity-bar-row-year">${months.map(m=>`
        <div class="activity-bar-col">
          <div class="activity-bar-track"><div class="activity-bar-fill" style="height:${m.n?Math.max(10,(m.n/maxN)*100):0}%"></div></div>
          <span class="activity-bar-num">${m.n||''}</span>
          <span class="activity-bar-label">${m.label}</span>
        </div>`).join('')}</div>
    </div>`;
  }

  const totalCount = entries.length;
  html += `<div class="activity-nav-row">
      <button class="icon-btn" id="activity-prev" aria-label="Période précédente">‹</button>
      <div class="activity-nav-label">
        <p class="activity-period-title">${periodLabel.charAt(0).toUpperCase()+periodLabel.slice(1)}</p>
        <p class="studio-note" style="margin:2px 0 0;">${totalCount} activité${totalCount>1?'s':''}</p>
      </div>
      <button class="icon-btn" id="activity-next" aria-label="Période suivante" ${ACTIVITY_OFFSET>=0?'disabled':''}>›</button>
    </div>
    ${extraHTML}
    <h2 class="section-title" style="margin-top:18px;">Répartition</h2>
    ${activityBreakdownHTML(entries)}`;

  if(ACTIVITY_PERIOD === 'jour'){
    html += `<h2 class="section-title" style="margin-top:18px;">Détail</h2>${activityListHTML(entries) || '<div class="card"><p class="studio-note" style="text-align:center; margin:4px 0;">Rien enregistré ce jour-là.</p></div>'}`;
  } else if(totalCount){
    html += `<h2 class="section-title" style="margin-top:18px;">Détail</h2>${activityListHTML(entries, 60)}`;
  }

  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('#activity-period-tabs .chip').forEach(c=>{
    c.onclick = ()=>{ ACTIVITY_PERIOD = c.dataset.period; ACTIVITY_OFFSET = 0; render(); };
  });
  const prevBtn = document.getElementById('activity-prev');
  if(prevBtn) prevBtn.onclick = ()=>{ ACTIVITY_OFFSET--; render(); };
  const nextBtn = document.getElementById('activity-next');
  if(nextBtn) nextBtn.onclick = ()=>{ if(ACTIVITY_OFFSET<0){ ACTIVITY_OFFSET++; render(); } };
}

/* ================= upcoming novenas & liturgical color (home helpers) ================= */
function daysUntil(mmdd){
  const [mm,dd] = mmdd.split('-').map(Number);
  const now = new Date(); now.setHours(0,0,0,0);
  let target = new Date(now.getFullYear(), mm-1, dd);
  if(target < now) target = new Date(now.getFullYear()+1, mm-1, dd);
  return Math.round((target-now)/86400000);
}
function upcomingNovenasHTML(){
  const items = Object.entries(NOVENA_FEASTS).map(([id,mmdd])=>{
    const nov = NOVENAS.find(n=>n.id===id);
    if(!nov) return null;
    const daysToFeast = daysUntil(mmdd);
    const startIn = daysToFeast - 9;
    return {nov, daysToFeast, startIn};
  }).filter(Boolean).sort((a,b)=>a.daysToFeast-b.daysToFeast).slice(0,3);
  if(items.length===0) return '';
  return `<h2 class="section-title">📅 Neuvaines à venir</h2><div class="card" style="padding:6px 14px;">` +
    items.map(it => {
      const art = lumenNovenaDedicatedArt(it.nov);
      const emoji = (NOVENA_ICONS[it.nov.id] || '🕯️').replace(/'/g,"\\'");
      const thumbHTML = art ? `<img src="${art.url}" alt="" loading="lazy" onerror="this.parentElement.innerHTML='${emoji}'">` : emoji;
      const startingNow = it.startIn <= 0;
      return `<div class="upcoming-item" data-novena-id="${it.nov.id}">
        <div class="upcoming-thumb">${thumbHTML}</div>
        <div class="upcoming-info">
          <span class="upcoming-title">${it.nov.title}</span>
          ${it.nov.sub ? `<span class="upcoming-sub">${it.nov.sub}</span>` : ''}
        </div>
        <span class="upcoming-days${startingNow ? ' upcoming-days--now' : ''}">${startingNow ? 'À commencer' : `dans ${it.startIn} j.`}</span>
      </div>`;
    }).join('') + `</div>`;
}
