let AELF_BIBLE_CHAPTER_CACHE = {};
async function fetchAelfBibleChapter(code, chapter){
  const key = code+'|'+chapter;
  if(AELF_BIBLE_CHAPTER_CACHE[key] !== undefined) return AELF_BIBLE_CHAPTER_CACHE[key];
  try{
    const res = await fetch(`https://api.aelf.org/v1/bible/${code}/${chapter}`);
    if(!res.ok) throw new Error('aelf http '+res.status);
    const json = await res.json();
    AELF_BIBLE_CHAPTER_CACHE[key] = json;
    return json;
  }catch(e){
    AELF_BIBLE_CHAPTER_CACHE[key] = null;
    return null;
  }
}
function renderAelfBibleBooks(){
  const html = `<h2 class="section-title">📖 La Bible</h2>
    <p class="section-desc">Traduction liturgique officielle en français, le texte complet de l'AELF — comme sur aelf.org/bible.</p>
    <p class="eyebrow" style="color:var(--gold);">Ancien Testament</p>
    <div class="aelf-bible-list">${AELF_BIBLE_AT.map((b,i)=>`<button class="aelf-bible-row" data-aelf-book="${b.code}" data-aelf-name="${b.name.replace(/"/g,'&quot;')}">${i+1}. ${b.name}</button>`).join('')}</div>
    <p class="eyebrow" style="color:var(--gold); margin-top:16px;">Nouveau Testament</p>
    <div class="aelf-bible-list">${AELF_BIBLE_NT.map((b,i)=>`<button class="aelf-bible-row" data-aelf-book="${b.code}" data-aelf-name="${b.name.replace(/"/g,'&quot;')}">${i+1}. ${b.name}</button>`).join('')}</div>
    <p class="eyebrow" style="color:var(--gold); margin-top:16px;">Psaumes</p>
    <div class="aelf-bible-list">${Array.from({length:150},(_,i)=>i+1).map(n=>`<button class="aelf-bible-row" data-aelf-book="Ps" data-aelf-name="Psaume ${n}" data-aelf-chapter="${n}">Psaume ${n}</button>`).join('')}</div>`;
  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('[data-aelf-book]').forEach(btn=>{
    btn.onclick = ()=>{
      AELF_BIBLE_CURRENT = {code:btn.dataset.aelfBook, name:btn.dataset.aelfName, chapter: parseInt(btn.dataset.aelfChapter||'1',10)};
      goTo('ecritures','aelf-bible-chapter');
    };
  });
}
let AELF_BIBLE_CURRENT = null;
let AELF_BIBLE_TAB = 'texte';
let AELF_BIBLE_FONT_BIG = false;
const AELF_BIBLE_HERO_IMG = 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Bible-706641.jpg?width=900';
/* Essaie plusieurs formes possibles de la réponse de l'API AELF (le format
   exact n'étant pas garanti) pour en extraire une liste {number, text} —
   sinon on revient sans casser à l'ancien embed AELF.org. */
function parseAelfBibleVerses(json){
  if(!json) return null;
  let raw = json.content ?? json.verses ?? json.data ?? json.chapitre ?? json.texte ?? null;
  if(!raw && Array.isArray(json)) raw = json;
  if(!raw) return null;
  if(Array.isArray(raw)){
    const out = raw.map(v=>{
      if(typeof v === 'string') return {number:'', text: aelfCleanText(v)};
      const number = v.number ?? v.numero ?? v.verse ?? v.num ?? v.verset ?? '';
      const text = aelfCleanText(v.content ?? v.text ?? v.texte ?? '');
      return {number, text};
    }).filter(v=>v.text);
    return out.length ? out : null;
  }
  if(typeof raw === 'object'){
    const out = Object.keys(raw).map(k=>({number:k, text:aelfCleanText(raw[k])})).filter(v=>v.text);
    return out.length ? out : null;
  }
  return null;
}
function renderAelfBibleChapter(){
  if(!AELF_BIBLE_CURRENT){ renderAelfBibleBooks(); return; }
  const {code, name, chapter} = AELF_BIBLE_CURRENT;
  document.getElementById('screen').innerHTML = `
    <div class="bible-reader">
      <figure class="bible-reader-hero">
        <img src="${AELF_BIBLE_HERO_IMG}" alt="" onerror="this.style.display='none'">
        <div class="bible-reader-hero-scrim"></div>
        <button class="bible-reader-hero-btn bible-reader-hero-back" id="aelf-bible-back" aria-label="Retour">←</button>
        <button class="bible-reader-hero-btn bible-reader-hero-fav" id="aelf-bible-fav" aria-label="Enregistrer">${isFavorited({type:'bible-chapter', code, chapter})?'✓':'🔖'}</button>
      </figure>
      <div class="bible-reader-nav">
        <button class="bible-reader-nav-arrow" id="aelf-chap-prev" ${chapter<=1?'disabled':''} aria-label="Chapitre précédent">‹</button>
        <div class="bible-reader-nav-title">
          <p class="bible-reader-book">${name}</p>
          ${code!=='Ps' ? `<p class="bible-reader-chapter">Chapitre ${chapter}</p>` : ''}
        </div>
        <button class="bible-reader-nav-arrow" id="aelf-chap-next" aria-label="Chapitre suivant">›</button>
      </div>
      <div class="bible-reader-tabs">
        ${['texte','meditation','audio'].map(t=>`<button class="bible-reader-tab ${AELF_BIBLE_TAB===t?'active':''}" data-tab="${t}">${t==='texte'?'Texte':t==='meditation'?'Méditation':'Audio'}</button>`).join('')}
      </div>
      <div class="bible-reader-body ${AELF_BIBLE_FONT_BIG?'bible-reader-body--big':''}" id="aelf-bible-body">
        <p class="studio-note" style="text-align:center;">Chargement du texte…</p>
      </div>
      <div class="bible-reader-toolbar">
        <button class="vreader-icon-btn" id="aelf-font-minus" aria-label="Diminuer la taille">A-</button>
        <button class="vreader-icon-btn" id="aelf-font-plus" aria-label="Augmenter la taille">A+</button>
        <button class="vreader-icon-btn" id="aelf-share" aria-label="Partager">📤</button>
        <button class="vreader-icon-btn" id="aelf-bookmark" aria-label="Signet">${isFavorited({type:'bible-chapter', code, chapter})?'✓':'🔖'}</button>
        <button class="vreader-icon-btn" id="aelf-listen" aria-label="Écouter">🔊</button>
      </div>
    </div>`;
  document.getElementById('aelf-bible-back').onclick = ()=>{ AELF_BIBLE_CURRENT = null; goTo('ecritures','aelf-bible-books'); };
  const bibleFavObj = {type:'bible-chapter', code, chapter, name, avatar:'📖', summary:`${name}${code!=='Ps'?' — chapitre '+chapter:''}`};
  const toggleBibleFav = async ()=>{
    const key = favKey(bibleFavObj);
    const idx = FAVORITES.findIndex(x=>favKey(x)===key);
    if(idx>=0){ FAVORITES.splice(idx,1); showToast('Retiré de vos favoris'); }
    else { FAVORITES.unshift(bibleFavObj); showToast('Ajouté à vos favoris ✦'); }
    await savePrefs();
    const active = isFavorited(bibleFavObj);
    const heroBtn = document.getElementById('aelf-bible-fav');
    const toolbarBtn = document.getElementById('aelf-bookmark');
    if(heroBtn) heroBtn.textContent = active ? '✓' : '🔖';
    if(toolbarBtn) toolbarBtn.textContent = active ? '✓' : '🔖';
  };
  document.getElementById('aelf-bible-fav').onclick = toggleBibleFav;
  document.getElementById('aelf-chap-prev').onclick = ()=>{ AELF_BIBLE_CURRENT.chapter--; renderAelfBibleChapter(); };
  document.getElementById('aelf-chap-next').onclick = ()=>{ AELF_BIBLE_CURRENT.chapter++; renderAelfBibleChapter(); };
  document.querySelectorAll('.bible-reader-tab').forEach(btn=>{
    btn.onclick = ()=>{ AELF_BIBLE_TAB = btn.dataset.tab; try{ window.speechSynthesis.cancel(); }catch(e){} renderAelfBibleBody(); document.querySelectorAll('.bible-reader-tab').forEach(b=> b.classList.toggle('active', b===btn)); };
  });
  document.getElementById('aelf-font-minus').onclick = ()=>{ AELF_BIBLE_FONT_BIG=false; document.getElementById('aelf-bible-body').classList.remove('bible-reader-body--big'); };
  document.getElementById('aelf-font-plus').onclick = ()=>{ AELF_BIBLE_FONT_BIG=true; document.getElementById('aelf-bible-body').classList.add('bible-reader-body--big'); };
  document.getElementById('aelf-share').onclick = ()=> copyForSocial(`${name}${code!=='Ps'?' '+chapter:''}`, AELF_BIBLE_LAST_PLAIN_TEXT||name);
  document.getElementById('aelf-bookmark').onclick = toggleBibleFav;
  document.getElementById('aelf-listen').onclick = ()=>{ AELF_BIBLE_TAB='audio'; renderAelfBibleChapter(); };
  renderAelfBibleBody();
}
let AELF_BIBLE_LAST_PLAIN_TEXT = '';
async function renderAelfBibleBody(){
  const body = document.getElementById('aelf-bible-body');
  if(!body || !AELF_BIBLE_CURRENT) return;
  const {code, name, chapter} = AELF_BIBLE_CURRENT;
  const aelfUrl = `https://www.aelf.org/bible/${code}/${chapter}`;
  body.innerHTML = `<p class="studio-note" style="text-align:center;">Chargement du texte…</p>`;
  const json = await fetchAelfBibleChapter(code, chapter);
  const verses = parseAelfBibleVerses(json);
  if(!verses){
    // Repli : le format de réponse n'a pas pu être lu — on garde l'ancien
    // embed AELF.org plutôt que de montrer un écran vide.
    body.innerHTML = `
      <p style="text-align:center; margin:4px 0 10px;"><a href="${aelfUrl}" target="_blank" rel="noopener" class="btn btn-gold btn-sm">Ouvrir ce chapitre sur AELF.org ↗</a></p>
      <div class="aelf-embed-wrap"><iframe src="${aelfUrl}" title="Texte AELF" loading="lazy"></iframe></div>
      <p class="studio-note" style="text-align:center; margin-top:8px;">Si le texte ne s'affiche pas ci-dessus (selon votre navigateur), utilisez le bouton au-dessus pour l'ouvrir directement.</p>`;
    AELF_BIBLE_LAST_PLAIN_TEXT = `${name}${code!=='Ps'?' '+chapter:''} — à lire sur aelf.org`;
    return;
  }
  AELF_BIBLE_LAST_PLAIN_TEXT = verses.map(v=>v.text).join(' ');
  if(AELF_BIBLE_TAB === 'texte'){
    body.innerHTML = `<div class="bible-verses">${verses.map(v=>
      `<p class="bible-verse">${v.number?`<span class="bible-verse-num">${v.number}</span>`:''}${v.text}</p>`
    ).join('')}</div>`;
  } else if(AELF_BIBLE_TAB === 'meditation'){
    const first = verses[0];
    body.innerHTML = `<div class="bible-meditation">
      <p class="eyebrow" style="color:var(--gold);">Pour méditer</p>
      <p class="vreader-text" style="font-style:italic;">« ${first ? first.text : ''} »</p>
      <p class="section-desc" style="margin-top:14px;">Relisez lentement ce chapitre, verset après verset. Qu'est-ce qui vous touche aujourd'hui ? À quoi ce texte vous invite-t-il concrètement ?</p>
    </div>`;
  } else {
    const total = estimateReadSeconds(AELF_BIBLE_LAST_PLAIN_TEXT);
    body.innerHTML = `<div class="bible-audio-pane">
      <p class="eyebrow" style="color:var(--gold); text-align:center;">${name}${code!=='Ps'?' — chapitre '+chapter:''}</p>
      <div class="vreader-audio-row" style="margin:14px 0;">
        <span class="vreader-audio-time" id="bible-audio-elapsed">0:00</span>
        <div class="vreader-audio-track"><div class="vreader-audio-fill" id="bible-audio-fill" style="width:0%"></div></div>
        <span class="vreader-audio-time">${formatMinSec(total)}</span>
      </div>
      <div style="text-align:center;"><button class="vreader-play-btn" id="bible-audio-play" aria-label="Écouter">▶</button></div>
      <p class="studio-note" style="text-align:center; margin-top:10px;">Lecture vocale générée par votre navigateur.</p>
    </div>`;
    const playBtn = document.getElementById('bible-audio-play');
    if(playBtn){
      let playing = false;
      playBtn.onclick = ()=>{
        if(playing){ try{ window.speechSynthesis.cancel(); }catch(e){} playing=false; playBtn.textContent='▶'; return; }
        playing = true; playBtn.textContent = '❚❚';
        speakWithProgress(AELF_BIBLE_LAST_PLAIN_TEXT, total, (ratio)=>{
          const fill = document.getElementById('bible-audio-fill');
          const elapsed = document.getElementById('bible-audio-elapsed');
          if(fill) fill.style.width = Math.round(ratio*100)+'%';
          if(elapsed) elapsed.textContent = formatMinSec(ratio*total);
        }, ()=>{ playing=false; if(playBtn) playBtn.textContent='▶'; });
      };
    }
  }
}
function renderBibleReader(){
  if(BIBLE_VIEW_MODE === 'plan'){ renderBiblePlan(); return; }
  const readAT = BIBLE_BOOKS_AT.filter(b=>BIBLE_PROGRESS.includes(b.split('|')[0])).length;
  const readNT = BIBLE_BOOKS_NT.filter(b=>BIBLE_PROGRESS.includes(b.split('|')[0])).length;
  let html = `<h2 class="section-title">📗 Lire la Bible</h2>
    <div style="text-align:right; margin-bottom:8px; display:flex; gap:8px; justify-content:flex-end; flex-wrap:wrap;">
      <button class="btn btn-gold btn-sm" id="goto-bible-plan-btn">📅 Suivre le plan sur un an</button>
      <button class="btn btn-gold btn-sm" id="goto-aelf-bible-btn">📖 Texte intégral AELF</button>
    </div>
    <p class="section-desc">L'index complet des 73 livres de la Bible. Chaque livre ouvre une lecture complète (traduction Louis Segond, domaine public) sur Bible Gateway. Cochez un livre une fois lu pour suivre votre progression.</p>`;
  BIBLE_TESTAMENTS.forEach(t=>{
    const readCount = t.id==='ancien' ? readAT : readNT;
    const pct = Math.round(readCount/t.books.length*100);
    html += `<h2 class="section-title" style="font-size:16px;">${t.title} — ${readCount}/${t.books.length}</h2>
      <div class="bible-progress-bar"><div class="bible-progress-fill" style="width:${pct}%;"></div></div>
      <div class="rubric-list book-toc-list">`;
    t.books.forEach((b,i)=>{
      const [fr, en] = b.split('|');
      const url = "https://www.biblegateway.com/passage/?search=" + encodeURIComponent(en+" 1") + "&version=LSG";
      const isRead = BIBLE_PROGRESS.includes(fr);
      html += `<div class="rubric-row book-toc-row">
        <label class="book-toc-check" title="Marquer comme lu">
          <input type="checkbox" class="bible-check" data-book="${fr}" ${isRead?'checked':''}>
        </label>
        <a href="${url}" target="_blank" rel="noopener" class="rubric-row-text book-toc-link">
          <span class="rubric-row-title">${i+1}. ${fr}</span>
          <span class="rubric-row-desc">Lire sur Bible Gateway (Louis Segond)</span>
        </a>
        <span class="rubric-row-chevron">↗</span>
      </div>`;
    });
    html += `</div>`;
  });
  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('.bible-check').forEach(cb=>{
    cb.onclick = async ()=>{
      const book = cb.dataset.book;
      if(cb.checked){ if(!BIBLE_PROGRESS.includes(book)) BIBLE_PROGRESS.push(book); }
      else { BIBLE_PROGRESS = BIBLE_PROGRESS.filter(b=>b!==book); }
      await saveBibleProgress(BIBLE_PROGRESS);
      render();
    };
  });
  const gotoAelfBtn = document.getElementById('goto-aelf-bible-btn');
  if(gotoAelfBtn) gotoAelfBtn.onclick = ()=> goTo('ecritures','aelf-bible-books');
  const gotoPlanBtn = document.getElementById('goto-bible-plan-btn');
  if(gotoPlanBtn) gotoPlanBtn.onclick = ()=>{ BIBLE_VIEW_MODE = 'plan'; render(); };
}

function renderBiblePlan(){
  const completed = BIBLE_PLAN_PROGRESS.completedDays || [];
  const nextIdx = BIBLE_PLAN_365.findIndex((_,i)=> !completed.includes(i));
  const activeIdx = nextIdx === -1 ? BIBLE_PLAN_365.length-1 : nextIdx;
  const day = BIBLE_PLAN_365[activeIdx];
  const allDone = completed.length >= BIBLE_PLAN_365.length;
  const url = "https://www.biblegateway.com/passage/?search=" + encodeURIComponent(day.book+" "+day.chapter) + "&version=LSG";

  let html = `<button class="back-link" id="back-to-index-btn">← Retour à l'index des livres</button>
    <h2 class="section-title">📅 Plan de lecture sur un an</h2>
    <p class="section-desc">Un chapitre suggéré chaque jour, à lire sur Bible Gateway (Louis Segond). Ce plan est indicatif — l'important est la régularité, pas l'exactitude du calendrier.</p>
    <div class="long-progress-track"><div class="long-progress-fill" style="width:${(completed.length/BIBLE_PLAN_365.length*100)}%;"></div></div>
    <p class="studio-note" style="text-align:center; margin-bottom:14px;">${completed.length} / ${BIBLE_PLAN_365.length} jours (${Math.round(completed.length/BIBLE_PLAN_365.length*100)}%)</p>`;

  if(allDone){
    html += `<div class="card" style="text-align:center;">
      <p class="day-title">Plan terminé ✦</p>
      <p class="entry-detail-text">Vous avez parcouru l'ensemble du plan sur un an. Vous pouvez le recommencer, ou continuer votre lecture librement dans l'index.</p>
      <button class="btn btn-ghost btn-sm" id="restart-bible-plan-btn" style="margin-top:10px;">Recommencer le plan</button>
    </div>`;
  } else {
    html += `<div class="card" style="text-align:center;">
      <p class="eyebrow" style="color:var(--gold);">Jour ${activeIdx+1}</p>
      <p class="day-title" style="font-size:20px;">${day.book} ${day.chapter}</p>
      <a href="${url}" target="_blank" rel="noopener" class="btn btn-gold btn-sm" style="margin-top:8px; display:inline-block;">Lire ce chapitre ↗</a>
      <div style="margin-top:14px;"><button class="btn btn-primary btn-sm" id="bible-plan-done-btn">✓ J'ai lu ce chapitre</button></div>
    </div>`;
  }
  document.getElementById('screen').innerHTML = html;
  document.getElementById('back-to-index-btn').onclick = ()=>{ BIBLE_VIEW_MODE = 'index'; render(); };
  const doneBtn = document.getElementById('bible-plan-done-btn');
  if(doneBtn){
    doneBtn.onclick = async ()=>{
      if(!completed.includes(activeIdx)) completed.push(activeIdx);
      BIBLE_PLAN_PROGRESS.completedDays = completed;
      await saveBiblePlanProgress(BIBLE_PLAN_PROGRESS);
      await markPrayedToday('lecture', 'Plan de lecture biblique');
      if(completed.length >= BIBLE_PLAN_365.length) fireCelebration();
      showToast('Un chapitre de plus 📖');
      renderBiblePlan();
    };
  }
  const restartBtn = document.getElementById('restart-bible-plan-btn');
  if(restartBtn){
    restartBtn.onclick = async ()=>{
      BIBLE_PLAN_PROGRESS = { completedDays: [] };
      await saveBiblePlanProgress(BIBLE_PLAN_PROGRESS);
      renderBiblePlan();
    };
  }
}

/* ================= prières selon l'état ================= */
let ETAT_SELECTED = null;
function renderEtatSelector(){
  let html = `<h2 class="section-title">🧭 Selon mon état</h2>
    <p class="section-desc">Choisissez ce qui décrit le mieux votre état du moment : des psaumes et des prières adaptés vous seront proposés.</p>
    <div class="etat-grid">${ETATS_PRIERE.map(e=>
      `<button class="etat-btn ${ETAT_SELECTED===e.key?'active':''}" data-key="${e.key}"><span class="e-emoji">${e.emoji}</span>${e.label}</button>`
    ).join('')}</div>`;

  if(ETAT_SELECTED){
    const etat = ETATS_PRIERE.find(e=>e.key===ETAT_SELECTED);
    const psalmGroup = PSALM_GROUPS.find(g=>g.id===etat.themeId);
    html += `<h2 class="section-title" style="font-size:16px;">📜 Psaumes qui peuvent aider</h2>`;
    if(psalmGroup){
      html += `<div class="grid">${psalmGroup.entries.slice(0,3).map((e,i)=>{
        const idx = psalmGroup.entries.indexOf(e);
        return `<div class="card entry-card" data-nav-psalm="${idx}">
          <div class="entry-avatar">${e.avatar}</div>
          <div class="entry-body"><p class="entry-name">${e.name}</p><p class="entry-summary">${e.summary}</p></div>
        </div>`;
      }).join('')}</div>`;
    }
    html += `<h2 class="section-title" style="font-size:16px;">📿 Prières suggérées</h2><div class="grid">`;
    etat.prieres.forEach(prayerName=>{
      let found = null, foundGroupId = null, foundIdx = null;
      PRIERES.forEach(g=>{ g.entries.forEach((e,i)=>{ if(e.name===prayerName){ found=e; foundGroupId=g.id; foundIdx=i; } }); });
      if(found){
        html += `<div class="card entry-card" data-nav-priere="${foundGroupId}|${foundIdx}">
          <div class="entry-avatar">${found.avatar||'📿'}</div>
          <div class="entry-body"><p class="entry-name">${found.name}</p><p class="entry-summary">${found.summary}</p></div>
        </div>`;
      }
    });
    html += `</div>`;
  }

  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('.etat-btn').forEach(b=>{
    b.onclick = ()=>{ ETAT_SELECTED = b.dataset.key; render(); };
  });
  document.querySelectorAll('[data-nav-psalm]').forEach(c=>{
    c.onclick = ()=>{
      const etat = ETATS_PRIERE.find(e=>e.key===ETAT_SELECTED);
      const psalmGroup = PSALM_GROUPS.find(g=>g.id===etat.themeId);
      PRIMARY='ecritures'; SUBTAB.ecritures='psaumes'; GROUP_SEL['ecritures:psaumes']=psalmGroup.id;
      ENTRY_OPEN = {compKey:'ecritures:psaumes', groupId:psalmGroup.id, idx:parseInt(c.dataset.navPsalm,10)};
      render();
    };
  });
  document.querySelectorAll('[data-nav-priere]').forEach(c=>{
    c.onclick = ()=>{
      const [groupId, idx] = c.dataset.navPriere.split('|');
      PRIMARY='prier'; SUBTAB.prier='prieres'; GROUP_SEL['prier:prieres']=groupId;
      ENTRY_OPEN = {compKey:'prier:prieres', groupId, idx:parseInt(idx,10)};
      render();
    };
  });
}

/* ================= confession guide ================= */
function renderConfessionGuide(){
  let daysSince = null;
  if(LAST_CONFESSION){
    daysSince = Math.floor((new Date(todayISO()) - new Date(LAST_CONFESSION)) / 86400000);
  }
  let html = `<h2 class="section-title">🕊️ Préparer sa confession</h2>
    <div class="card" style="border-left:4px solid var(--gold); margin-bottom:14px;">
      <p class="eyebrow" style="color:var(--gold);">Ma dernière confession</p>
      ${LAST_CONFESSION
        ? `<p class="day-title" style="font-size:15px; margin:4px 0;">${new Date(LAST_CONFESSION).toLocaleDateString('fr-FR', {day:'numeric', month:'long', year:'numeric'})} — il y a ${daysSince} jour${daysSince>1?'s':''}</p>
           ${daysSince>60 ? `<p class="section-desc" style="margin:4px 0 8px;">Cela commence à faire un moment. Se confesser régulièrement, même sans faute grave, fait du bien à l'âme.</p>` : ''}`
        : `<p class="section-desc" style="margin:4px 0 8px;">Vous n'avez pas encore renseigné de date.</p>`
      }
      <div style="display:flex; gap:8px; align-items:center; flex-wrap:wrap;">
        <input type="date" id="confession-date-input" value="${LAST_CONFESSION||''}" max="${todayISO()}" style="flex:1; min-width:140px;">
        <button class="btn btn-gold btn-sm" id="save-confession-date-btn">Enregistrer</button>
      </div>
    </div>
    <p class="section-desc">Un temps d'examen de conscience organisé en trois thèmes, à parcourir en silence avant de vous confesser.</p>
    <div class="card">`;
  CONFESSION_EXAM.forEach(section=>{
    html += `<p class="confession-theme">${section.theme}</p>`;
    section.questions.forEach(q=>{
      html += `<label class="confession-q"><input type="checkbox">${q}</label>`;
    });
  });
  html += `</div>
    <h2 class="section-title" style="font-size:16px;">Les étapes de la confession</h2>
    <div class="card">
      <p class="entry-detail-text">1. Le prêtre vous accueille, vous pouvez faire le signe de croix.<br>
      2. Vous confessez vos péchés simplement, sans les justifier.<br>
      3. Le prêtre peut vous donner un conseil et une pénitence.<br>
      4. Vous récitez un acte de contrition.<br>
      5. Le prêtre donne l'absolution : vos péchés sont pardonnés.</p>
    </div>
    <h2 class="section-title" style="font-size:16px;">Acte de contrition</h2>
    <div class="card"><p class="entry-detail-text">Mon Dieu, j'ai un très grand regret de vous avoir offensé, parce que vous êtes infiniment bon et que le péché vous déplaît. Je prends la ferme résolution, avec le secours de votre sainte grâce, de ne plus vous offenser et de faire pénitence. Amen.</p></div>`;
  document.getElementById('screen').innerHTML = html;
  document.getElementById('save-confession-date-btn').onclick = async ()=>{
    const val = document.getElementById('confession-date-input').value;
    if(!val) return;
    LAST_CONFESSION = val;
    await saveConfessionDate(val);
    showToast('Date enregistrée 🕊️');
    renderConfessionGuide();
  };
}

/* ================= mémorial des défunts ================= */
function renderMemorial(){
  let html = `<h2 class="section-title">🕯️ Mémorial des défunts</h2>
    <p class="section-desc">Gardez ici les prénoms de proches défunts, pour les porter dans votre prière.</p>
    <div class="card add-intention-box">
      <input type="text" id="memorial-name" placeholder="Prénom du défunt">
      <button class="btn btn-primary btn-sm" id="add-memorial-btn" style="margin-top:8px;">Ajouter</button>
    </div>`;
  if(MEMORIAL.length===0){
    html += `<div class="card empty-state">Aucun nom pour l'instant.</div>`;
  } else {
    html += `<div class="grid">${MEMORIAL.map(m=>`
      <div class="card memorial-card">
        <span class="memorial-name">🕯️ ${m.name}</span>
        <button class="icon-btn" data-del-memorial="${m.id}">🗑</button>
      </div>`).join('')}</div>
      <div class="card" style="margin-top:14px;">
        <p class="eyebrow" style="color:var(--gold);">Prière pour eux</p>
        <p class="entry-detail-text">Donnez-leur, Seigneur, le repos éternel, et que la lumière sans déclin luise pour eux. Qu'ils reposent en paix. Amen.</p>
      </div>`;
  }
  document.getElementById('screen').innerHTML = html;
  document.getElementById('add-memorial-btn').onclick = async ()=>{
    const input = document.getElementById('memorial-name');
    const name = input.value.trim();
    if(!name) { input.focus(); return; }
    MEMORIAL.unshift({id:'m-'+Date.now(), name});
    await saveMemorial(MEMORIAL);
    render();
  };
  document.querySelectorAll('[data-del-memorial]').forEach(btn=>{
    btn.onclick = async ()=>{
      MEMORIAL = MEMORIAL.filter(m=>m.id!==btn.dataset.delMemorial);
      await saveMemorial(MEMORIAL);
      render();
    };
  });
}

/* ================= office du jour (parcours unique) ================= */
let OFFICE_STATE = null;
/* ================= prières par heure de la journée ================= */
function renderPrieresParHeure(){
  const hour = new Date().getHours();
  let currentSlot = 'soir';
  if(hour >= 3 && hour < 6) currentSlot = 'nuit3h';
  else if(hour >= 6 && hour < 9) currentSlot = 'aube6h';
  else if(hour >= 9 && hour < 14) currentSlot = 'matin';
  else if(hour >= 14 && hour < 17) currentSlot = 'midi15h';
  else if(hour >= 17 && hour < 22) currentSlot = 'soir';
  else currentSlot = 'minuit';

  const slotBox = (key, icon, title, color, prayers, buttons)=>`
    <div class="card" style="border-left:4px solid ${color}; margin-top:14px; ${currentSlot===key?'box-shadow:var(--glow-gold);':''}">
      <p class="eyebrow" style="color:${color};">${icon} ${title} ${currentSlot===key?"— c'est maintenant":""}</p>
      ${prayers.map(p=>`<p class="day-title" style="font-size:15px; margin-top:10px;">${p.t}</p><p class="entry-detail-text">${linkifyClassicPrayers(p.x)}</p>`).join('')}
      ${buttons ? `<div style="display:flex; gap:8px; flex-wrap:wrap; margin-top:10px;">${buttons}</div>` : ''}
    </div>`;

  const html = `<h2 class="section-title">🕰️ Prières par heure</h2>
    <p class="section-desc">La tradition chrétienne rythme la journée et la nuit par la prière. Six moments, avec plusieurs prières pour chacun — le moment actuel est mis en évidence.</p>

    ${moisPrayerHTML()}

    <div class="card" style="text-align:center; border-left:4px solid var(--wine);">
      <p class="eyebrow" style="color:var(--wine);">🎲 Prière express</p>
      <p class="section-desc" style="margin:2px 0 10px;">Une minute à peine, sans avoir à choisir — pour une pause rapide dans une journée chargée.</p>
      <button class="btn btn-primary btn-sm" id="express-prayer-btn">✦ Me proposer une prière</button>
    </div>

    <div class="card" style="text-align:center; border-left:4px solid var(--gold);">
      <p class="eyebrow" style="color:var(--gold);">🕯️ Minuteur de prière silencieuse</p>
      <p class="section-desc" style="margin:2px 0 10px;">Pour un temps de silence, de méditation ou d'adoration, sans distraction.</p>
      <div style="display:flex; gap:8px; justify-content:center; flex-wrap:wrap;">
        <button class="btn btn-ghost btn-sm" data-timer-min="3">3 min</button>
        <button class="btn btn-ghost btn-sm" data-timer-min="5">5 min</button>
        <button class="btn btn-ghost btn-sm" data-timer-min="10">10 min</button>
        <button class="btn btn-ghost btn-sm" data-timer-min="15">15 min</button>
        <button class="btn btn-ghost btn-sm" data-timer-min="20">20 min</button>
      </div>
    </div>

    ${slotBox('aube6h','🌅','6h — Prime, l\u2019aube', 'var(--gold)', [
      {t:"Prière du réveil", x:"Seigneur, avant que le jour ne commence vraiment, je viens à toi. Que cette journée nouvelle porte ta lumière, et que je marche aujourd'hui à ta suite, pas après pas."},
      {t:"Consécration de la journée", x:"Je t'offre, Seigneur, tout ce que sera cette journée : mes réussites et mes échecs, mes joies et mes fatigues, ceux que je croiserai et ceux que j'oublierai de saluer. Que tout devienne prière."},
      {t:"Béni soit Dieu pour ce nouveau jour", x:"Béni soit Dieu qui nous a réveillés ce matin et nous a donné l'opportunité de recommencer. La vie est un miracle, et chaque réveil ressemble à Dieu me disant de recommencer, qu'il est avec moi. Chaque aube, je me sens béni(e) d'avoir la chance d'écrire un nouveau chapitre sous la protection divine. Amen."}
    ], `<button class="btn btn-gold btn-sm" data-goto-primary="prier" data-goto-sub="laudes">☀️ Prier les Laudes</button>`)}

    ${slotBox('matin','☀️','Le matin', 'var(--gold)', [
      {t:"Offrande de la journée", x:"Seigneur, je t'offre cette journée qui commence : mes joies, mes peines, mes rencontres et mes tâches. Que tout ce que je vivrai aujourd'hui te soit offert."},
      {t:"Prière avant le travail", x:"Bénis, Seigneur, le travail de mes mains aujourd'hui. Donne-moi la patience dans l'effort, l'honnêteté dans ce que je fais, et le repos du cœur même au milieu de l'agitation."}
    ], `<button class="btn btn-ghost btn-sm" data-goto-primary="prier" data-goto-sub="laudes">☀️ Laudes complètes</button>`)}

    ${slotBox('midi15h','🔔','Midi et 15h', 'var(--wine)', [
      {t:"L'Angélus (midi)", x:"L'ange du Seigneur apporta l'annonce à Marie, et elle conçut du Saint-Esprit. <i>Je vous salue Marie...</i> Voici la servante du Seigneur, qu'il me soit fait selon votre parole. <i>Je vous salue Marie...</i> Et le Verbe s'est fait chair, et il a habité parmi nous. <i>Je vous salue Marie...</i>"},
      {t:"La Miséricorde (15h)", x:"Éternel Père, je vous offre le Corps et le Sang, l'Âme et la Divinité de votre Fils bien-aimé, Notre-Seigneur Jésus-Christ, en propitiation pour nos péchés et pour ceux du monde entier. Pour sa douloureuse Passion, ayez pitié de nous et du monde entier."},
      {t:"Prière de la mi-journée", x:"Seigneur, la journée est à moitié passée. Ce qui a été fait est fait ; ce qui reste à faire, je te le confie. Donne-moi un second souffle pour continuer avec le cœur que j'avais ce matin."},
      {t:"Prière de la Croix et de la miséricorde", x:"Seigneur Jésus, à l'heure où tu as remis ton esprit entre les mains du Père, je me souviens de ton amour infini (cf. Mt 27, 50). Par ta Croix, la peur est vaincue, la culpabilité est brisée, et l'espérance est rendue possible. Je dépose à tes pieds mes fautes, mes blessures, mes fatigues. Lave mon cœur, renouvelle mes forces, et remplis-moi de ta miséricorde. Que ta victoire soit vivante en moi aujourd'hui. Amen."},
      {t:"Invocation du Précieux Sang de Jésus", x:"Sang de Jésus, sauve-moi, purifie-moi, lave-moi, délivre-moi et libère-moi. Sang de Jésus, donne-moi la paix, aide-moi à prier, sanctifie-moi, guéris-moi, relève-moi. Sang de Jésus, libère-moi de tout ce qui m'éloigne de Dieu, éloigne de moi tout esprit contraire à ton nom, et viens demeurer en moi. Que ce Sang me recouvre, m'accompagne partout où je vais, et me préserve de tout danger et de tout piège de l'ennemi. Que ce Sang soit ma forteresse, mon bouclier et mon rempart, et qu'il reste à jamais mon salut. Seigneur Jésus, tu as été crucifié injustement, et c'est pour moi que tu l'as été. Aujourd'hui, je m'incline devant ta Croix et je te demande pardon pour tous mes péchés. Verse ce Sang sur moi, qu'il demeure à jamais mon salut. Amen."}
    ], `<button class="btn btn-ghost btn-sm" data-goto-primary="prier" data-goto-sub="angelus">🔔 Angélus complet</button><button class="btn btn-gold btn-sm" data-goto-primary="devotions" data-goto-sub="misericorde">❤️ Chapelet de la Miséricorde</button>`)}

    ${slotBox('soir','🌙','Le soir', 'var(--wine-dark)', [
      {t:"Examen du soir", x:"Repassez votre journée en présence de Dieu : ce qui a été bon, ce qui a manqué, ce dont vous voulez demander pardon — avant de vous en remettre à lui pour la nuit."},
      {t:"Prière de gratitude du soir", x:"Merci, Seigneur, pour cette journée, même imparfaite. Merci pour ce qui a été beau, et même pour ce qui a été difficile, car tu étais présent dans les deux. Garde ceux que j'aime cette nuit."},
      {t:"Compline (fin de journée)", x:"Que le Seigneur tout-puissant nous accorde une nuit paisible et une fin parfaite. Amen."}
    ], `<button class="btn btn-ghost btn-sm" data-goto-primary="prier" data-goto-sub="examen">🌙 Faire mon examen</button><button class="btn btn-gold btn-sm" data-goto-primary="prier" data-goto-sub="compline">🌌 Prier la Compline</button>`)}

    ${slotBox('minuit','🌑','Minuit (00h)', 'var(--wine-dark)', [
      {t:"Prière de la nuit qui commence", x:"Seigneur, la maison est silencieuse, et je te confie ce silence. Veille sur ceux qui dorment, console ceux qui ne trouvent pas le sommeil, et garde du danger ceux qui travaillent cette nuit."},
      {t:"Pour ceux qui ne dorment pas", x:"Pour les malades qui souffrent cette nuit, pour ceux qui veillent un proche, pour ceux que l'angoisse tient éveillés : Seigneur, sois leur compagnie invisible jusqu'au matin."}
    ], null)}

    ${slotBox('nuit3h','✨','3h — l\u2019heure des veilleurs', 'var(--gold-light)', [
      {t:"Prière de veille", x:"Comme les veilleurs attendent l'aurore, mon âme attend le Seigneur (cf. Ps 130). Dans cette heure profonde de la nuit, je choisis de croire que la lumière revient toujours, même quand elle semble loin."},
      {t:"Pour les âmes en peine", x:"Seigneur, en cette heure où beaucoup luttent en silence contre leurs peurs, envoie ta lumière à ceux qui se sentent seuls dans l'obscurité. Que ton Esprit veille avec eux jusqu'au jour."}
    ], null)}

    <p class="studio-note" style="margin-top:14px;">Le moment actuel (${String(hour).padStart(2,'0')}h) est mis en valeur automatiquement ci-dessus.</p>
  `;
  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('[data-goto-primary]').forEach(btn=>{
    btn.onclick = ()=> goTo(btn.dataset.gotoPrimary, btn.dataset.gotoSub);
  });
  document.getElementById('express-prayer-btn').onclick = ()=>{
    const group = PRIERES[Math.floor(Math.random()*PRIERES.length)];
    const idx = Math.floor(Math.random()*group.entries.length);
    ENTRY_OPEN = {compKey:'prier:prieres', groupId:group.id, idx};
    goTo('devotions','prieres');
  };
  document.querySelectorAll('[data-timer-min]').forEach(btn=>{
    btn.onclick = ()=> openPrayerTimer(parseInt(btn.dataset.timerMin,10));
  });
}


function renderOfficeDuJour(){
  if(!OFFICE_STATE){ OFFICE_STATE = { step:0 }; }
  const steps = ['verset','psaume','examen','intention','fin'];
  const cur = steps[OFFICE_STATE.step];
  let html = `<h2 class="section-title">🕯️ Office du jour</h2>
    <p class="section-desc">Un parcours court qui enchaîne verset, psaume, examen éclair et intention — pour prier sans avoir à choisir où aller.</p>
    <div class="step-progress">${steps.slice(0,4).map((_,i)=>`<span class="${i<OFFICE_STATE.step?'done':i===OFFICE_STATE.step?'current':''}"></span>`).join('')}</div>
    <div class="card">`;
  if(cur==='verset'){
    const v = VERSETS_DU_JOUR[dayOfYear() % VERSETS_DU_JOUR.length];
    html += `<p class="eyebrow" style="color:var(--gold);">1. Verset du jour</p><p class="verset-text">« ${v.text} »</p><p class="verset-ref">${v.ref}</p>`;
  } else if(cur==='psaume'){
    const themeIdx = dayOfYear() % PSALM_GROUPS.length;
    const group = PSALM_GROUPS[themeIdx];
    const p = group.entries[dayOfYear() % group.entries.length];
    html += `<p class="eyebrow" style="color:var(--gold);">2. Psaume</p><p class="day-title">${p.name}</p><p class="entry-detail-text">${p.summary}</p>`;
  } else if(cur==='examen'){
    html += `<p class="eyebrow" style="color:var(--gold);">3. Examen éclair</p><p class="entry-detail-text">Prenez trente secondes de silence. Une seule question : de quoi ai-je le plus besoin de parler à Dieu, là, maintenant ?</p>`;
  } else if(cur==='intention'){
    html += `<p class="eyebrow" style="color:var(--gold);">4. Une intention</p><p class="entry-detail-text">Nommez, même intérieurement, une personne ou une situation à confier à Dieu aujourd'hui.</p>
      <textarea id="office-intention" rows="2" placeholder="Écrire cette intention (optionnel)"></textarea>`;
  } else {
    html += `<p class="day-title" style="text-align:center;">Office terminé ✦</p><p class="entry-detail-text" style="text-align:center;">Que cette courte prière accompagne le reste de votre journée.</p>`;
  }
  html += `<div style="text-align:center; margin-top:10px;">
      <button class="btn btn-primary btn-sm" id="office-next">${OFFICE_STATE.step<4?'Suivant →':'Recommencer'}</button>
    </div></div>`;
  document.getElementById('screen').innerHTML = html;
  document.getElementById('office-next').onclick = async ()=>{
    const intentEl = document.getElementById('office-intention');
    if(intentEl && intentEl.value.trim()){
      INTENTIONS.unshift({id:'i-'+Date.now(), name:'Anonyme', text:intentEl.value.trim(), prayers:0, createdAt:Date.now()});
      await saveIntentions(INTENTIONS);
    }
    if(OFFICE_STATE.step<4){ OFFICE_STATE.step++; render(); }
    else { await markPrayedToday('office', 'Office'); OFFICE_STATE=null; showToast('Office terminé ✦'); render(); }
  };
}

