const OFFICES_LIST = [
  {key:'lectures-office', icon:'📖', label:'Lectures', time:'À tout moment'},
  {key:'laudes', icon:'☀️', label:'Laudes', time:'Au lever'},
  {key:'tierce', icon:'🕘', label:'Tierce', time:'09:00 – 12:00'},
  {key:'sexte', icon:'☀️', label:'Sexte', time:'12:00 – 15:00'},
  {key:'none', icon:'🕒', label:'None', time:'15:00 – 17:00'},
  {key:'vepres', icon:'🌆', label:'Vêpres', time:'En soirée'},
  {key:'compline', icon:'🌌', label:'Complies', time:'Au coucher'}
];
function renderOffices(){
  const now = new Date().getHours();
  let currentKey = 'lectures-office';
  if(now>=5 && now<9) currentKey='laudes';
  else if(now>=9 && now<12) currentKey='tierce';
  else if(now>=12 && now<15) currentKey='sexte';
  else if(now>=15 && now<17) currentKey='none';
  else if(now>=17 && now<21) currentKey='vepres';
  else if(now>=21 || now<5) currentKey='compline';
  const html = `<h2 class="section-title">🕯️ Liturgie des Heures — les Offices</h2>
    <p class="section-desc">La prière officielle de l'Église, rythmée tout au long du jour. L'office du moment est mis en lumière.</p>
    <div class="offices-list">${OFFICES_LIST.map(o=>`
      <button class="offices-row ${o.key===currentKey?'current':''}" data-office="${o.key}">
        <span class="offices-icon">${o.icon}</span>
        <span class="offices-label">${o.label}</span>
        <span class="offices-time">${o.time}</span>
      </button>`).join('')}</div>
    <div style="text-align:center; margin-top:14px;"><button class="btn btn-gold btn-sm" id="goto-aelf-office-btn">📖 Textes officiels AELF, mot pour mot</button></div>`;
  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('[data-office]').forEach(btn=>{
    btn.onclick = ()=>{ SUBTAB.prier = btn.dataset.office; render(); };
  });
  document.getElementById('goto-aelf-office-btn').onclick = ()=>{ SUBTAB.prier = 'aelf-office'; render(); };
}
