/* ================= parcours guidé sur 7 jours ================= */
function renderParcours(){
  const completed = PARCOURS_PROGRESS.completedDays || [];
  const nextDayIdx = PARCOURS_JOURS.findIndex((_, i) => !completed.includes(i));
  const activeIdx = nextDayIdx === -1 ? PARCOURS_JOURS.length - 1 : nextDayIdx;
  const day = PARCOURS_JOURS[activeIdx];
  const allDone = completed.length >= PARCOURS_JOURS.length;

  let html = `<h2 class="section-title">🗺️ Parcours de 7 jours</h2>
    <p class="section-desc">Un petit chemin pour ancrer une habitude de prière, jour après jour — en s'appuyant sur ce qui existe déjà dans l'application.</p>
    <div class="day-dots">${PARCOURS_JOURS.map((_,i)=>{
      let cls = 'day-dot';
      if(completed.includes(i)) cls += ' done';
      else if(i===activeIdx && !allDone) cls += ' current';
      return `<div class="${cls}">${completed.includes(i)?'✓':i+1}</div>`;
    }).join('')}</div>`;

  if(allDone){
    html += `<div class="card" style="text-align:center;">
      <p class="day-title">Parcours terminé ✦</p>
      <p class="entry-detail-text">Vous avez traversé les sept jours. Rien ne vous empêche de le recommencer avec une intention différente, ou d'explorer plus librement l'application désormais.</p>
      <button class="btn btn-ghost btn-sm" id="parcours-restart-btn">Recommencer le parcours</button>
    </div>`;
  } else {
    html += `<div class="card">
      <p class="day-title">${day.title}</p>
      <p class="entry-detail-text">${day.intro}</p>
      <div style="display:flex; flex-direction:column; gap:8px; margin-top:10px;">
        ${day.actions.map(a=>`<button class="btn btn-ghost btn-sm parcours-action-btn" data-primary="${a.primary}" data-sub="${a.sub}" style="justify-content:flex-start;">→ ${a.label}</button>`).join('')}
      </div>
      <div style="text-align:center; margin-top:14px;">
        <button class="btn btn-primary btn-sm" id="parcours-done-btn">${activeIdx===PARCOURS_JOURS.length-1?'Terminer le parcours ✦':'J\u2019ai fait ce pas aujourd\u2019hui →'}</button>
      </div>
    </div>`;
  }
  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('.parcours-action-btn').forEach(btn=>{
    btn.onclick = ()=> goTo(btn.dataset.primary, btn.dataset.sub);
  });
  const doneBtn = document.getElementById('parcours-done-btn');
  if(doneBtn){
    doneBtn.onclick = async ()=>{
      if(!completed.includes(activeIdx)) completed.push(activeIdx);
      PARCOURS_PROGRESS.completedDays = completed;
      await saveParcoursProgress(PARCOURS_PROGRESS);
      await markPrayedToday('parcours', 'Étape de parcours');
      showToast('Bravo, une étape de plus 🕯️');
      renderParcours();
    };
  }
  const restartBtn = document.getElementById('parcours-restart-btn');
  if(restartBtn){
    restartBtn.onclick = async ()=>{
      PARCOURS_PROGRESS = { completedDays: [] };
      await saveParcoursProgress(PARCOURS_PROGRESS);
      renderParcours();
    };
  }
}

function renderCareme40(){
  const completed = CAREME_PROGRESS.completedDays || [];
  const nextDayIdx = CAREME_JOURS.findIndex((_, i) => !completed.includes(i));
  const activeIdx = nextDayIdx === -1 ? CAREME_JOURS.length - 1 : nextDayIdx;
  const day = CAREME_JOURS[activeIdx];
  const allDone = completed.length >= CAREME_JOURS.length;

  let html = `<h2 class="section-title">✝️ Carême — 40 jours</h2>
    <p class="section-desc">Un chemin de quarante jours, comme au désert, découpé en cinq semaines thématiques. Avancez à votre rythme, un jour à la fois.</p>
    <div class="long-progress-track"><div class="long-progress-fill" style="width:${(completed.length/CAREME_JOURS.length*100)}%;"></div></div>
    <p class="studio-note" style="margin-bottom:10px; text-align:center;">${completed.length} / ${CAREME_JOURS.length} jours parcourus (${Math.round(completed.length/CAREME_JOURS.length*100)}%)</p>
    <div class="day-dots" style="flex-wrap:wrap;">${CAREME_JOURS.map((_,i)=>{
      let cls = 'day-dot';
      if(completed.includes(i)) cls += ' done';
      else if(i===activeIdx && !allDone) cls += ' current';
      return `<div class="${cls}" style="width:26px; height:26px; font-size:11px;">${completed.includes(i)?'✓':i+1}</div>`;
    }).join('')}</div>`;

  if(allDone){
    html += `<div class="card" style="text-align:center;">
      <p class="day-title">Les 40 jours sont accomplis ✦</p>
      <p class="entry-detail-text">Vous avez traversé tout le chemin du Carême. Que cette préparation porte son fruit dans la joie de Pâques.</p>
      <button class="btn btn-ghost btn-sm" id="careme-restart-btn">Recommencer le parcours</button>
    </div>`;
  } else {
    const todayGoals = (CAREME_PROGRESS.goals && CAREME_PROGRESS.goals[activeIdx]) || {jeune:false, lecture:false, charite:false};
    html += `<div class="card">
      <p class="day-title">${day.title}</p>
      <p class="entry-detail-text">${day.intro}</p>
      <div style="display:flex; flex-direction:column; gap:8px; margin-top:10px;">
        ${day.actions.map(a=>`<button class="btn btn-ghost btn-sm careme-action-btn" data-primary="${a.primary}" data-sub="${a.sub}" style="justify-content:flex-start;">→ ${a.label}</button>`).join('')}
      </div>
      <p class="eyebrow" style="color:var(--gold); margin-top:14px;">Mes 3 objectifs du jour</p>
      <div class="lent-goal-row">
        <label class="lent-goal-check"><input type="checkbox" data-goal="jeune" ${todayGoals.jeune?'checked':''}> 🍞 Jeûne / privation</label>
        <label class="lent-goal-check"><input type="checkbox" data-goal="lecture" ${todayGoals.lecture?'checked':''}> 📖 Lecture / prière</label>
        <label class="lent-goal-check"><input type="checkbox" data-goal="charite" ${todayGoals.charite?'checked':''}> ❤️ Charité / geste concret</label>
      </div>
      <div style="text-align:center; margin-top:14px;">
        <button class="btn btn-primary btn-sm" id="careme-done-btn">${activeIdx===CAREME_JOURS.length-1?'Terminer le Carême ✦':'J\u2019ai fait ce pas aujourd\u2019hui →'}</button>
      </div>
    </div>`;
  }
  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('.careme-action-btn').forEach(btn=>{
    btn.onclick = ()=> goTo(btn.dataset.primary, btn.dataset.sub);
  });
  document.querySelectorAll('[data-goal]').forEach(cb=>{
    cb.onchange = async ()=>{
      if(!CAREME_PROGRESS.goals) CAREME_PROGRESS.goals = {};
      if(!CAREME_PROGRESS.goals[activeIdx]) CAREME_PROGRESS.goals[activeIdx] = {};
      CAREME_PROGRESS.goals[activeIdx][cb.dataset.goal] = cb.checked;
      await saveCaremeProgress(CAREME_PROGRESS);
    };
  });
  const doneBtn = document.getElementById('careme-done-btn');
  if(doneBtn){
    doneBtn.onclick = async ()=>{
      if(!completed.includes(activeIdx)) completed.push(activeIdx);
      CAREME_PROGRESS.completedDays = completed;
      await saveCaremeProgress(CAREME_PROGRESS);
      await markPrayedToday('careme', 'Jour de Carême');
      showToast('Un jour de plus sur le chemin ✝️');
      if(completed.length >= CAREME_JOURS.length) fireCelebration();
      renderCareme40();
    };
  }
  const restartBtn = document.getElementById('careme-restart-btn');
  if(restartBtn){
    restartBtn.onclick = async ()=>{
      CAREME_PROGRESS = { completedDays: [] };
      await saveCaremeProgress(CAREME_PROGRESS);
      renderCareme40();
    };
  }
}

function renderObjectifs(){
  let html = `<h2 class="section-title">🎯 Mes objectifs</h2>
    <p class="section-desc">Fixez-vous un petit objectif hebdomadaire, et cochez les jours où vous l'avez tenu.</p>
    <div class="card add-intention-box">
      <input type="text" id="obj-text" placeholder="Ex. Prier le chapelet 3 fois par semaine">
      <input type="number" id="obj-target" placeholder="Combien de fois par semaine ?" min="1" max="7" style="margin-top:8px;">
      <button class="btn btn-primary btn-sm" id="add-obj-btn" style="margin-top:8px;">Ajouter l'objectif</button>
    </div>`;
  if(OBJECTIFS.length===0){
    html += `<div class="card empty-state">Aucun objectif pour l'instant.</div>`;
  } else {
    const weekKey = (()=>{ const d=new Date(); const jan1=new Date(d.getFullYear(),0,1); return d.getFullYear()+'-w'+Math.ceil((((d-jan1)/86400000)+jan1.getDay()+1)/7); })();
    html += `<div class="grid">${OBJECTIFS.map(o=>{
      const thisWeek = (o.log||[]).filter(w=>w===weekKey).length;
      const pct = Math.min(100, Math.round(thisWeek/o.target*100));
      const circumference = 2 * Math.PI * 26;
      const offset = circumference * (1 - pct/100);
      return `<div class="card objectif-card" data-id="${o.id}">
        <div style="display:flex; align-items:center; gap:12px;">
          <div class="ring-progress">
            <svg width="60" height="60" viewBox="0 0 60 60">
              <circle cx="30" cy="30" r="26" fill="none" stroke="var(--hairline)" stroke-width="6"/>
              <circle cx="30" cy="30" r="26" fill="none" stroke="var(--gold)" stroke-width="6" stroke-linecap="round"
                stroke-dasharray="${circumference}" stroke-dashoffset="${offset}" transform="rotate(-90 30 30)"/>
            </svg>
            <span class="ring-progress-label">${thisWeek}/${o.target}</span>
          </div>
          <div style="flex:1; min-width:0;">
            <p class="entry-name">${o.text}</p>
            <p class="section-desc" style="margin:2px 0 0;">${pct}% cette semaine</p>
          </div>
        </div>
        <div class="objectif-progress-row">
          ${Array.from({length:o.target}).map((_,i)=>`<button class="objectif-dot-btn ${i<thisWeek?'done':''}" data-obj="${o.id}">${i<thisWeek?'✓':i+1}</button>`).join('')}
          <button class="icon-btn" data-del-obj="${o.id}" style="margin-left:auto;">🗑</button>
        </div>
      </div>`;
    }).join('')}</div>`;
  }
  document.getElementById('screen').innerHTML = html;
  document.getElementById('add-obj-btn').onclick = async ()=>{
    const textEl = document.getElementById('obj-text');
    const targetEl = document.getElementById('obj-target');
    const text = textEl.value.trim();
    const target = parseInt(targetEl.value,10) || 3;
    if(!text) { textEl.focus(); return; }
    OBJECTIFS.unshift({id:'o-'+Date.now(), text, target, log:[]});
    await saveObjectifs(OBJECTIFS);
    render();
  };
  document.querySelectorAll('.objectif-dot-btn').forEach(btn=>{
    btn.onclick = async ()=>{
      const o = OBJECTIFS.find(x=>x.id===btn.dataset.obj);
      const d = new Date(); const jan1 = new Date(d.getFullYear(),0,1);
      const weekKey = d.getFullYear()+'-w'+Math.ceil((((d-jan1)/86400000)+jan1.getDay()+1)/7);
      o.log = o.log || [];
      const thisWeekCount = o.log.filter(w=>w===weekKey).length;
      if(thisWeekCount < o.target) o.log.push(weekKey);
      await saveObjectifs(OBJECTIFS);
      render();
    };
  });
  document.querySelectorAll('[data-del-obj]').forEach(btn=>{
    btn.onclick = async ()=>{
      OBJECTIFS = OBJECTIFS.filter(o=>o.id!==btn.dataset.delObj);
      await saveObjectifs(OBJECTIFS);
      render();
    };
  });
}

/* ================= mémorisation de versets ================= */
function weekNumber(){
  const d = new Date(); const jan1 = new Date(d.getFullYear(),0,1);
  return Math.ceil((((d-jan1)/86400000)+jan1.getDay()+1)/7);
}
function renderMemorisation(){
  const v = VERSETS_DU_JOUR[weekNumber() % VERSETS_DU_JOUR.length];
  const dayOfWeek = new Date().getDay();
  const revealFraction = Math.min(1, (dayOfWeek+1)/7);
  const words = v.text.split(' ');
  const revealCount = Math.max(2, Math.round(words.length*revealFraction));
  let html = `<h2 class="section-title">🧠 Verset de la semaine</h2>
    <p class="section-desc">Un même verset toute la semaine : plus les jours passent, plus il se révèle. Essayez de compléter les mots manquants de mémoire.</p>
    <div class="card verset-card">
      <p class="verset-text">${words.map((w,i)=> i<revealCount ? `<span class="memo-word">${w}</span>` : `<span class="memo-word hidden-word">${w}</span>`).join(' ')}</p>
      <p class="verset-ref">${v.ref}</p>
    </div>
    <div style="text-align:center;"><button class="btn btn-ghost btn-sm" id="reveal-all-btn">👁️ Tout révéler</button></div>`;
  document.getElementById('screen').innerHTML = html;
  document.getElementById('reveal-all-btn').onclick = ()=>{
    document.querySelectorAll('.hidden-word').forEach(el=> el.classList.remove('hidden-word'));
  };
}

/* ================= calendrier Avent / Carême interactif ================= */
function renderAventCareme(){
  const banner = computeLiturgicalSeasonBanner();
  const today = new Date(); today.setHours(0,0,0,0);
  let startDate, totalDays, label;
  if(banner.includes('Avent')){
    startDate = adventStart(today.getMonth()===11 && today.getDate()>=25 ? today.getFullYear() : (today.getMonth()===11?today.getFullYear():today.getFullYear()-(today.getMonth()<10?0:0)));
    // find the advent start that is <= today and closest
    let y = today.getFullYear();
    let cand = adventStart(y);
    if(cand > today) cand = adventStart(y-1);
    startDate = cand;
    totalDays = 25; label = "Calendrier de l'Avent";
  } else if(banner.includes('Carême')){
    const easter = getEasterDate(today.getMonth()<6 ? today.getFullYear() : today.getFullYear()+1);
    startDate = addDays(easter, -46);
    totalDays = 40; label = "Calendrier du Carême";
  } else {
    document.getElementById('screen').innerHTML = `<h2 class="section-title">🕯️ Avent / Carême</h2>
      <div class="card empty-state">Ce calendrier interactif s'active pendant l'Avent et le Carême. Revenez à ce moment-là — en attendant, l'onglet Calendrier vous indique le temps liturgique actuel.</div>`;
    return;
  }
  const dayIndex = Math.floor((today - startDate)/86400000);
  let html = `<h2 class="section-title">🕯️ ${label}</h2>
    <p class="section-desc">Ouvrez la case du jour pour une courte méditation. Les cases précédentes restent accessibles.</p>
    <div class="advent-grid">`;
  for(let i=1;i<=totalDays;i++){
    const isOpen = ADVENT_PROGRESS[i];
    const isAvailable = i <= dayIndex+1;
    let cls = 'advent-door';
    if(isOpen) cls += ' opened'; else if(!isAvailable) cls += ' locked';
    html += `<div class="${cls}" data-day="${i}" data-available="${isAvailable}">${i}</div>`;
  }
  html += `</div>`;
  if(ADVENT_PROGRESS._open){
    const i = ADVENT_PROGRESS._open;
    const medit = MEDITATIONS[(i+dayOfYear()) % MEDITATIONS.length];
    const dayGoals = (ADVENT_PROGRESS.goals && ADVENT_PROGRESS.goals[i]) || {jeune:false, lecture:false, charite:false};
    html += `<div class="card">
      <p class="eyebrow" style="color:var(--gold);">Jour ${i}</p>
      <p class="saint-name">${medit.title}</p>
      <p class="entry-detail-text">${medit.text}</p>
      <p class="eyebrow" style="color:var(--gold); margin-top:12px;">Mes 3 objectifs du jour</p>
      <div class="lent-goal-row">
        <label class="lent-goal-check"><input type="checkbox" data-advent-goal="jeune" data-advent-day="${i}" ${dayGoals.jeune?'checked':''}> 🍞 Jeûne / privation</label>
        <label class="lent-goal-check"><input type="checkbox" data-advent-goal="lecture" data-advent-day="${i}" ${dayGoals.lecture?'checked':''}> 📖 Lecture / prière</label>
        <label class="lent-goal-check"><input type="checkbox" data-advent-goal="charite" data-advent-day="${i}" ${dayGoals.charite?'checked':''}> ❤️ Charité / geste concret</label>
      </div>
    </div>`;
  }
  document.getElementById('screen').innerHTML = html;
  document.querySelectorAll('.advent-door').forEach(door=>{
    door.onclick = async ()=>{
      if(door.dataset.available !== 'true') return;
      const i = parseInt(door.dataset.day,10);
      ADVENT_PROGRESS[i] = true;
      ADVENT_PROGRESS._open = i;
      await saveAdventProgress(ADVENT_PROGRESS);
      await markPrayedToday('avent', "Calendrier de l'Avent");
      render();
    };
  });
  document.querySelectorAll('[data-advent-goal]').forEach(cb=>{
    cb.onchange = async ()=>{
      if(!ADVENT_PROGRESS.goals) ADVENT_PROGRESS.goals = {};
      const d = cb.dataset.adventDay;
      if(!ADVENT_PROGRESS.goals[d]) ADVENT_PROGRESS.goals[d] = {};
      ADVENT_PROGRESS.goals[d][cb.dataset.adventGoal] = cb.checked;
      await saveAdventProgress(ADVENT_PROGRESS);
    };
  });
}

