/* ================= streak milestone check ================= */
function checkStreakMilestone(){
  const m = STREAK_MILESTONES.find(m=>m.days===STREAK.count);
  if(m && !SEEN_MILESTONES.includes(m.days)){
    SEEN_MILESTONES.push(m.days);
    savePrefs();
    showMilestoneModal(m);
  }
}
function showMilestoneModal(m){
  const overlay = document.getElementById('search-overlay');
  const panel = overlay.querySelector('.search-panel');
  const original = panel.innerHTML;
  panel.innerHTML = `<div class="milestone-content">
    <span class="milestone-flame">🔥</span>
    <p class="day-title">${m.title}</p>
    <p class="entry-detail-text">${m.text}</p>
    <button class="btn btn-primary btn-sm" id="milestone-close">Continuer</button>
  </div>`;
  overlay.classList.remove('hidden');
  document.getElementById('milestone-close').onclick = ()=>{ overlay.classList.add('hidden'); panel.innerHTML = original; };
}

