/* ================= global search ================= */
function buildSearchIndex(){
  const idx = [];
  function addGroups(groups, primary, sub, compKey){
    groups.forEach(g=>{
      (g.entries||[]).forEach((e,i)=>{
        idx.push({name:e.name, summary:e.summary, avatar:e.avatar, primary, sub, compKey, groupId:g.id, idx:i});
      });
    });
  }
  addGroups(PSALM_GROUPS, 'ecritures','psaumes','ecritures:psaumes');
  addGroups(HISTORY, 'ecritures','bible','ecritures:bible');
  addGroups(RECITS_GROUPS.filter(g=>!g.special && !g.diagram), 'ecritures','recits','ecritures:recits');
  addGroups(JESUS, 'jesus',null,'jesus:main');
  addGroups(SAINTS_LIBRARY, 'eglise','saints','eglise:saints');
  addGroups(EGLISE, 'eglise','vie-eglise','eglise:vie-eglise');
  addGroups(ACTUALITES, 'eglise','actualites','eglise:actualites');
  addGroups(SPIRITUALITE, 'sagesse','spiritualite','sagesse:spiritualite');
  addGroups(ENSEIGNEMENTS_ALL, 'sagesse','enseignements','sagesse:enseignements');
  addGroups(PRIERES, 'prier','prieres','prier:prieres');
  SAINTS.forEach(s=> idx.push({name:s.name, summary:s.bio, avatar:'🕊️', primary:'eglise', sub:'calendrier', isCalSaint:true}));
  return idx;
}
let SEARCH_INDEX = null;
function runSearch(query){
  if(!SEARCH_INDEX) SEARCH_INDEX = buildSearchIndex();
  const q = query.trim().toLowerCase();
  if(q.length < 2) return [];
  return SEARCH_INDEX.filter(item =>
    item.name.toLowerCase().includes(q) || (item.summary||'').toLowerCase().includes(q)
  ).slice(0, 30);
}
function renderSearchResults(query){
  const results = runSearch(query);
  const box = document.getElementById('search-results');
  if(!query.trim()){ box.innerHTML = '<p class="section-desc">Tapez au moins deux lettres pour chercher un psaume, un saint, une prière…</p>'; return; }
  if(results.length===0){ box.innerHTML = '<p class="section-desc">Aucun résultat pour cette recherche.</p>'; return; }
  box.innerHTML = results.map((r,i)=>`<div class="search-result-item" data-idx="${i}">
    <div class="entry-avatar" style="width:32px;height:32px;font-size:14px;">${r.avatar||'📖'}</div>
    <div><p class="search-result-name">${r.name}</p><p class="search-result-meta">${r.sub||''}</p></div>
  </div>`).join('');
  box.querySelectorAll('.search-result-item').forEach(el=>{
    el.onclick = ()=>{
      const r = results[parseInt(el.dataset.idx,10)];
      closeSearch();
      if(r.isCalSaint){ goTo('eglise','calendrier'); return; }
      PRIMARY = r.primary; SUBTAB[r.primary] = r.sub;
      GROUP_SEL[r.compKey] = r.groupId;
      ENTRY_OPEN = { compKey:r.compKey, groupId:r.groupId, idx:r.idx };
      render();
    };
  });
}
function openSearch(){
  document.getElementById('search-overlay').classList.remove('hidden');
  document.getElementById('search-input').value = '';
  document.getElementById('search-results').innerHTML = '';
  setTimeout(()=> document.getElementById('search-input').focus(), 50);
}
function closeSearch(){ document.getElementById('search-overlay').classList.add('hidden'); }

/* ================= theme / font size ================= */
const THEMES_LIST = [
  {key:'light', label:'Ambre', icon:'🕯️', swatches:['#F5EFE4','#6B2545','#C08A3E']},
  {key:'dark', label:'Ambre sombre', icon:'🌙', swatches:['#161B24','#5C7DA6','#D9A85C']}
];
const BG_PATTERN_LIST = [
  {key:'aucun', label:'Aucun', icon:'◻️'},
  {key:'croix', label:'Croix', icon:'✝️'},
  {key:'colombe', label:'Colombe', icon:'🕊️'},
  {key:'poisson', label:'Poisson (Ichthus)', icon:'🐟'},
  {key:'ble-raisin', label:'Épis & Raisin', icon:'🌾'},
  {key:'rayons', label:'Rayons de lumière', icon:'☀️'},
  {key:'ancre', label:'Ancre (espérance)', icon:'⚓'}
];
let BG_PATTERN = 'croix';
let THEME_MODE = 'auto';
let BRIGHTNESS = 100;
let CUSTOM_ACCENT = '';
function computeAutoTheme(){
  const h = new Date().getHours();
  return (h>=7 && h<20) ? 'light' : 'dark';
}
function applyThemeAndFont(){
  if(THEME_MODE === 'auto') THEME = computeAutoTheme();
  if(!THEMES_LIST.some(t=>t.key===THEME)) THEME = 'light';
  document.body.setAttribute('data-theme', THEME);
  document.body.setAttribute('data-pattern', BG_PATTERN);
  document.body.setAttribute('data-theme-mode', THEME_MODE);
  const current = THEMES_LIST.find(t=>t.key===THEME) || THEMES_LIST[0];
  const btn = document.getElementById('theme-btn');
  if(btn){ const iconEl = btn.querySelector('.tool-btn-icon'); if(iconEl) iconEl.textContent = THEME_MODE === 'auto' ? '🔄' : current.icon; }
  const app = document.getElementById('app');
  app.classList.remove('font-sm','font-md','font-lg');
  app.classList.add('font-'+FONT_SIZE);
  app.classList.toggle('dyslexic-font', DYSLEXIC_FONT);
  app.classList.remove('title-lora','title-cormorant');
  if(TITLE_FONT==='lora') app.classList.add('title-lora');
  else if(TITLE_FONT==='cormorant') app.classList.add('title-cormorant');
  app.style.filter = BRIGHTNESS !== 100 ? `brightness(${BRIGHTNESS}%)` : '';
  if(CUSTOM_ACCENT){
    app.style.setProperty('--wine', CUSTOM_ACCENT);
    app.style.setProperty('--wine-dark', shadeColor(CUSTOM_ACCENT, -25));
    app.style.setProperty('--gold', CUSTOM_ACCENT);
  } else {
    app.style.removeProperty('--wine');
    app.style.removeProperty('--wine-dark');
    app.style.removeProperty('--gold');
  }
}
function shadeColor(hex, percent){
  const num = parseInt(hex.replace('#',''), 16);
  let r = (num >> 16) + Math.round(255 * (percent/100));
  let g = ((num >> 8) & 0x00FF) + Math.round(255 * (percent/100));
  let b = (num & 0x0000FF) + Math.round(255 * (percent/100));
  r = Math.max(0, Math.min(255, r));
  g = Math.max(0, Math.min(255, g));
  b = Math.max(0, Math.min(255, b));
  return '#' + (0x1000000 + r*0x10000 + g*0x100 + b).toString(16).slice(1);
}
setInterval(()=>{ if(THEME_MODE === 'auto') applyThemeAndFont(); }, 5*60*1000);
function toggleTheme(){
  openThemePicker();
}
